function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function traceRegularOctagon(r) {
    // Flat-topped regular octagon (vertices offset by PI/8)
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i * TAU) / 8 + Math.PI / 8;
      const vx = Math.cos(a) * r;
      const vy = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(vx, vy);
      else ctx.lineTo(vx, vy);
    }
    ctx.closePath();
  }

  function drawBeveledSquareTile(x, y, size, flipScaleX, colTopLeft, colBotRight) {
    const absSX = Math.max(0.02, Math.abs(flipScaleX));
    const hs = size * 0.5;

    ctx.save();
    ctx.translate(x, y);
    ctx.scale(absSX, 1);

    // Base lower-right flat facet
    ctx.fillStyle = colBotRight;
    ctx.fillRect(-hs, -hs, size, size);

    // Upper-left diagonal crisp flat mosaic bevel facet
    ctx.fillStyle = colTopLeft;
    ctx.beginPath();
    ctx.moveTo(-hs, hs);
    ctx.lineTo(-hs, -hs);
    ctx.lineTo(hs, -hs);
    ctx.closePath();
    ctx.fill();

    ctx.restore();
  }

  function drawOrbitCloudOrnament(angle, orbitR, scaleAmt, isLight) {
    if (scaleAmt <= 0.01) return;
    ctx.save();
    ctx.rotate(angle);
    ctx.translate(0, -orbitR);
    ctx.scale(scaleAmt, scaleAmt);

    // Crisp stylized Ruyi auspicious cloud crest oriented tangentially around medallion
    const unit = 0.032 * s;
    ctx.fillStyle = isLight ? "#FFD6CA" : "#E8998B";
    ctx.beginPath();
    ctx.moveTo(-1.05 * unit, 0.22 * unit);
    ctx.bezierCurveTo(-1.05 * unit, -0.20 * unit, -0.62 * unit, -0.24 * unit, -0.44 * unit, -0.05 * unit);
    ctx.bezierCurveTo(-0.34 * unit, -0.48 * unit, 0.34 * unit, -0.48 * unit, 0.44 * unit, -0.05 * unit);
    ctx.bezierCurveTo(0.62 * unit, -0.24 * unit, 1.05 * unit, -0.20 * unit, 1.05 * unit, 0.22 * unit);
    ctx.bezierCurveTo(1.05 * unit, 0.44 * unit, 0.72 * unit, 0.46 * unit, 0.50 * unit, 0.30 * unit);
    ctx.lineTo(-0.50 * unit, 0.30 * unit);
    ctx.bezierCurveTo(-0.72 * unit, 0.46 * unit, -1.05 * unit, 0.44 * unit, -1.05 * unit, 0.22 * unit);
    ctx.closePath();
    ctx.fill();

    // Small centered champagne pearl dot above cloud crest
    ctx.fillStyle = "#FFF3E6";
    ctx.beginPath();
    ctx.arc(0, -0.56 * unit, 0.14 * unit, 0, TAU);
    ctx.fill();

    ctx.restore();
  }

  function drawBgOctagonMosaicAccent(x, y, r, color) {
    // Subtle flat matte octagonal tile motif in far-outer midnight background
    ctx.save();
    ctx.translate(x, y);
    traceRegularOctagon(r);
    ctx.fillStyle = color;
    ctx.fill();

    traceRegularOctagon(r * 0.56);
    ctx.fillStyle = "#060B17";
    ctx.fill();

    traceRegularOctagon(r * 0.26);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  // Exact 15-column x 5-row mosaic bitmap for "2027" (4 digits x 3 cols + 3 single-col gaps = 15 cols)
  const mosaicRows = [
    "111011101110111",
    "001010100010001",
    "111010101110010",
    "100010101000010",
    "111011101110010"
  ];
  const gridCols = 15;
  const gridRows = 5;

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const hoverY = Math.sin(loopPhase * 2) * 0.006 * s;

  let borderAssemble = 0;  // 0 = expanded poised constellation, 1 = locked octagonal frame
  let coreGridReveal = 0;  // 0..1 visibility of inner mosaic tile grid
  let waveFlipP = 0;       // 0 = dormant sapphire tiles, 1 = all "2027" rose-gold tiles flipped front
  let waveReverse = false;
  let orbitReveal = 0;
  let orbitAngle = 0;
  let shimmerPos = -1;
  let medallionPulse = 0;

  if (currentScene === 0) {
    // Scene 1: 16-Tile Radial Octagonal Mosaic Frame Assembly
    borderAssemble = easeInOutQuint(subProgress(sceneProgress, 0.06, 0.72));
    coreGridReveal = easeOutQuart(subProgress(sceneProgress, 0.62, 0.96));
    waveFlipP = 0;
  } else if (currentScene === 1) {
    // Scene 2: Left-to-Right 2D Wave-Flip Mosaic Reveal of "2027"
    borderAssemble = 1;
    coreGridReveal = 1;
    waveFlipP = subProgress(sceneProgress, 0.04, 0.92);
    waveReverse = false;
  } else if (currentScene === 2) {
    // Scene 3: Orbiting Rose-Gold Auspicious Cloud Ornaments & Twin Diagonal Shimmer Sweeps
    borderAssemble = 1;
    coreGridReveal = 1;
    waveFlipP = 1;
    const env = Math.sin(sceneProgress * Math.PI);
    orbitReveal = clamp01(env * 1.45);
    orbitAngle = easeInOutCubic(sceneProgress) * (TAU / 8); // Smooth exact 45-deg symmetric glide
    medallionPulse = 0.5 - 0.5 * Math.cos(sceneProgress * Math.PI * 4);

    if (sceneProgress >= 0.14 && sceneProgress <= 0.44) {
      shimmerPos = easeInOutCubic(subProgress(sceneProgress, 0.14, 0.44));
    } else if (sceneProgress >= 0.56 && sceneProgress <= 0.86) {
      shimmerPos = easeInOutCubic(subProgress(sceneProgress, 0.56, 0.86));
    }
  } else {
    // Scene 4: Reverse Mosaic Flip & Radial Border Dispersion back to Exact t=0 Poised Constellation
    waveFlipP = 1 - subProgress(sceneProgress, 0.0, 0.34);
    waveReverse = true;
    coreGridReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.24, 0.44));
    borderAssemble = 1 - easeInOutQuint(subProgress(sceneProgress, 0.32, 0.94));
  }

  // --- LAYER 1: Clean Dark Matte Midnight Navy-Charcoal Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#090F1F");
  bgGrad.addColorStop(0.52, "#060B17");
  bgGrad.addColorStop(1, "#03060E");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Octagonal Tile Accents (Strictly Outside Orbit Zone) ---
  const halfW = width * 0.5;
  if (halfW > 0.66 * s) {
    const outerX = Math.min(halfW - 0.09 * s, 0.74 * s);
    const drift = Math.sin(loopPhase) * 0.011 * s;
    drawBgOctagonMosaicAccent(cx - outerX, cy - 0.26 * s + drift, 0.042 * s, "#131F3D");
    drawBgOctagonMosaicAccent(cx - outerX, cy + 0.26 * s - drift, 0.034 * s, "#18284D");
    drawBgOctagonMosaicAccent(cx + outerX, cy - 0.26 * s - drift, 0.042 * s, "#131F3D");
    drawBgOctagonMosaicAccent(cx + outerX, cy + 0.26 * s + drift, 0.034 * s, "#18284D");
  }

  // --- LAYER 3: Hero Icon — 2027 Octagonal Mosaic Medallion ---
  const outerOctR = 0.248 * s;
  const innerOctR = 0.204 * s;
  const fieldOctR = 0.194 * s;

  ctx.save();
  ctx.translate(cx, cy + hoverY);

  // 3A. Scene 3 Orbiting Auspicious Flat Cloud Ornaments (Strictly Outside Octagon Medallion)
  if (orbitReveal > 0.005) {
    const orbitR = lerp(0.310 * s, 0.344 * s, easeOutQuart(orbitReveal));
    ctx.save();
    ctx.globalAlpha = orbitReveal;
    for (let i = 0; i < 8; i++) {
      const ang = (i * TAU) / 8 + orbitAngle;
      drawOrbitCloudOrnament(ang, orbitR, easeOutQuart(orbitReveal), i % 2 === 0);
    }
    ctx.restore();
  }

  const medScale = 1 + 0.018 * medallionPulse;
  ctx.scale(medScale, medScale);

  // 3B. Central Recessed Sapphire-Navy Octagonal Core (Always Cleanly Anchored at Center)
  ctx.save();
  const coreScale = lerp(0.86, 1.0, borderAssemble);
  ctx.scale(coreScale, coreScale);

  traceRegularOctagon(innerOctR);
  ctx.fillStyle = "#1E3766";
  ctx.fill();

  traceRegularOctagon(fieldOctR);
  ctx.fillStyle = "#0F1D3A";
  ctx.fill();

  // Subtle Inner Rose-Gold Perimeter Trim Hairline
  traceRegularOctagon(fieldOctR - 0.006 * s);
  ctx.strokeStyle = "#C97C70";
  ctx.lineWidth = Math.max(1.2, 0.0022 * s);
  ctx.stroke();

  ctx.restore();

  // 3C. 16 Precision-Fitted Rose-Gold Trapezoidal Octagonal Border Mosaic Tiles
  // Each of the 8 octagon sides is split cleanly into 2 symmetrical beveled tiles with crisp dark grout gaps!
  const groutGap = 0.0042 * s;
  for (let edge = 0; edge < 8; edge++) {
    const a0 = (edge * TAU) / 8 + Math.PI / 8;
    const a1 = ((edge + 1) * TAU) / 8 + Math.PI / 8;
    const v0x = Math.cos(a0);
    const v0y = Math.sin(a0);
    const v1x = Math.cos(a1);
    const v1y = Math.sin(a1);

    for (let sub = 0; sub < 2; sub++) {
      const tileIdx = edge * 2 + sub;
      const uStart = sub === 0 ? 0.04 : 0.52;
      const uEnd = sub === 0 ? 0.48 : 0.96;

      // Interpolated outer & inner endpoints along this octagon side
      const ox0 = lerp(v0x, v1x, uStart) * outerOctR;
      const oy0 = lerp(v0y, v1y, uStart) * outerOctR;
      const ox1 = lerp(v0x, v1x, uEnd) * outerOctR;
      const oy1 = lerp(v0y, v1y, uEnd) * outerOctR;

      const ix0 = lerp(v0x, v1x, uStart) * (innerOctR + groutGap * 0.5);
      const iy0 = lerp(v0y, v1y, uStart) * (innerOctR + groutGap * 0.5);
      const ix1 = lerp(v0x, v1x, uEnd) * (innerOctR + groutGap * 0.5);
      const iy1 = lerp(v0y, v1y, uEnd) * (innerOctR + groutGap * 0.5);

      const midX = (ox0 + ox1 + ix0 + ix1) * 0.25;
      const midY = (oy0 + oy1 + iy0 + iy1) * 0.25;
      const dirLen = Math.hypot(midX, midY) || 1;
      const nx = midX / dirLen;
      const ny = midY / dirLen;

      // Staggered radial glide per tile pair for lively yet disciplined mosaic assembly
      const stagger = (tileIdx % 4) * 0.055;
      const localAssemble = easeInOutQuint(subProgress(borderAssemble, stagger, 0.82 + stagger * 0.8));
      const radialDisp = lerp(0.118 * s, 0, localAssemble);
      const tileScale = lerp(0.84, 1.0, localAssemble);

      ctx.save();
      ctx.translate(nx * radialDisp, ny * radialDisp);
      ctx.translate(midX, midY);
      ctx.scale(tileScale, tileScale);
      ctx.translate(-midX, -midY);

      const isBright = tileIdx % 2 === 0;
      ctx.fillStyle = isBright ? "#F5B2A4" : "#DF897B";
      ctx.beginPath();
      ctx.moveTo(ox0, oy0);
      ctx.lineTo(ox1, oy1);
      ctx.lineTo(ix1, iy1);
      ctx.lineTo(ix0, iy0);
      ctx.closePath();
      ctx.fill();

      // Crisp upper facet highlight triangle inside each trapezoidal mosaic tile
      ctx.fillStyle = isBright ? "#FFE0D6" : "#F5B2A4";
      ctx.beginPath();
      ctx.moveTo(ox0, oy0);
      ctx.lineTo(ox1, oy1);
      ctx.lineTo(ix0, iy0);
      ctx.closePath();
      ctx.fill();

      ctx.restore();
    }
  }

  // 3D. True 15x5 Beveled Mosaic Tile Grid Inside Octagon Core ("2027" Wave-Flip Reveal)
  if (coreGridReveal > 0.01) {
    const pitch = 0.0192 * s;
    const tileSz = 0.0156 * s;
    const gridW = (gridCols - 1) * pitch;
    const gridH = (gridRows - 1) * pitch;
    const xStart = -gridW * 0.5;
    const yStart = -gridH * 0.5;

    ctx.save();
    ctx.globalAlpha = coreGridReveal;

    // Symmetrical Top & Bottom Rose-Gold Mini Diamond Mosaic Accents (Above & Below the 15x5 Grid)
    const accentY = gridH * 0.5 + 0.044 * s;
    const accentCols = [-3, -2, -1, 0, 1, 2, 3];
    for (let ai = 0; ai < accentCols.length; ai++) {
      const ax = accentCols[ai] * pitch * 1.15;
      const isCenter = accentCols[ai] === 0;
      const aSz = (isCenter ? 0.012 : 0.0085) * s * coreGridReveal;
      const aCol = isCenter ? "#FFF3E6" : "#E8998B";
      for (let sy = -1; sy <= 1; sy += 2) {
        ctx.fillStyle = aCol;
        ctx.beginPath();
        ctx.moveTo(ax, sy * accentY - aSz);
        ctx.lineTo(ax + aSz, sy * accentY);
        ctx.lineTo(ax, sy * accentY + aSz);
        ctx.lineTo(ax - aSz, sy * accentY);
        ctx.closePath();
        ctx.fill();
      }
    }

    // Render all 75 individual beveled mosaic tiles with wave-flip physics
    for (let r = 0; r < gridRows; r++) {
      for (let c = 0; c < gridCols; c++) {
        const isDigit = mosaicRows[r][c] === "1";
        const tx = xStart + c * pitch;
        const ty = yStart + r * pitch;

        // Compute diagonal-column wave trigger (0..1)
        const colNorm = waveReverse ? (gridCols - 1 - c) / (gridCols - 1) : c / (gridCols - 1);
        const waveStart = colNorm * 0.62 + (r / gridRows) * 0.08;
        const localFlip = easeInOutCubic(subProgress(waveFlipP, waveStart, waveStart + 0.30));
        const flipCos = Math.cos(localFlip * Math.PI); // +1 dormant sapphire, -1 flipped active
        const flippedFront = flipCos < 0;

        if (isDigit) {
          if (flippedFront) {
            const isTopRowAccent = r === 0 || (r + c) % 3 === 0;
            drawBeveledSquareTile(
              tx,
              ty,
              tileSz,
              flipCos,
              isTopRowAccent ? "#FFF3E6" : "#FFD4C8",
              isTopRowAccent ? "#F5B2A4" : "#E38B7D"
            );
          } else {
            drawBeveledSquareTile(tx, ty, tileSz, flipCos, "#223D70", "#162A52");
          }
        } else {
          // Background mosaic matrix tile subtly settles darker once wave passes for crisp contrast
          if (flippedFront) {
            drawBeveledSquareTile(tx, ty, tileSz * 0.88, flipCos, "#182D54", "#112140");
          } else {
            drawBeveledSquareTile(tx, ty, tileSz * 0.88, flipCos, "#203A6B", "#15284D");
          }
        }
      }
    }

    ctx.restore();
  }

  // 3E. Crisp Diagonal Champagne-Pearl Shimmer Sweep Clipped Strictly to Octagonal Medallion (Scene 3)
  if (shimmerPos >= 0 && shimmerPos <= 1) {
    ctx.save();
    traceRegularOctagon(outerOctR);
    ctx.clip();
    const sx = lerp(-outerOctR * 1.9, outerOctR * 1.9, shimmerPos);
    ctx.fillStyle = "rgba(255, 243, 230, 0.36)";
    ctx.beginPath();
    ctx.moveTo(sx - 0.032 * s, -outerOctR * 1.2);
    ctx.lineTo(sx + 0.028 * s, -outerOctR * 1.2);
    ctx.lineTo(sx - 0.068 * s, outerOctR * 1.2);
    ctx.lineTo(sx - 0.128 * s, outerOctR * 1.2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function mixHex(hexA, hexB, u) {
    u = clamp01(u);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const r = Math.round(lerp((a >> 16) & 255, (b >> 16) & 255, u));
    const g = Math.round(lerp((a >> 8) & 255, (b >> 8) & 255, u));
    const bl = Math.round(lerp(a & 255, b & 255, u));
    return "rgb(" + r + "," + g + "," + bl + ")";
  }

  function drawRoundedRectPath(x, y, w, h, r) {
    const rr = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawDiamond(x, y, rx, ry, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fill();
  }

  function drawRuyiCloud(x, y, scale, rotAngle, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rotAngle);
    ctx.scale(scale, scale);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-1.0, 0.22);
    ctx.bezierCurveTo(-1.0, -0.18, -0.62, -0.22, -0.45, -0.05);
    ctx.bezierCurveTo(-0.36, -0.46, 0.36, -0.46, 0.45, -0.05);
    ctx.bezierCurveTo(0.62, -0.22, 1.0, -0.18, 1.0, 0.22);
    ctx.bezierCurveTo(1.0, 0.42, 0.72, 0.44, 0.52, 0.30);
    ctx.lineTo(-0.52, 0.30);
    ctx.bezierCurveTo(-0.72, 0.44, -1.0, 0.42, -1.0, 0.22);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawBgSoundBarMotif(x, y, unit, color) {
    // Subtle flat architectural stacked rhythm-bar motif in far-outer background
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = color;
    const widths = [unit * 0.65, unit * 1.15, unit * 0.85];
    const barH = unit * 0.22;
    const gap = unit * 0.34;
    for (let i = 0; i < 3; i++) {
      const w = widths[i];
      drawRoundedRectPath(-w * 0.5, (i - 1) * gap - barH * 0.5, w, barH, barH * 0.5);
      ctx.fill();
    }
    ctx.restore();
  }

  function drawRhythmRibbon(side, xStart, yCenter, maxLen, ampY, thick, energy, phase, color) {
    if (energy <= 0.01) return;
    const curLen = maxLen * energy;
    const steps = 22;
    ctx.save();
    ctx.globalAlpha = clamp01(energy * 1.15);
    ctx.strokeStyle = color;
    ctx.lineWidth = thick;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const env = Math.sin(u * Math.PI);
      const px = xStart + side * u * curLen;
      const py = yCenter + Math.sin(u * Math.PI * 2.2 - phase) * ampY * env;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();

    // Crisp leading flat diamond pulse tip strictly clear of ribbon end
    const tipX = xStart + side * (curLen + 0.018 * s);
    const tipR = thick * 0.85 * energy;
    drawDiamond(tipX, yCenter, tipR * 1.2, tipR * 0.9, color);
    ctx.restore();
  }

  // Smooth beat envelope helper: returns { impulse (0..1), beatIdx (0..3) }
  function computeBeat(p, beatCount) {
    const scaled = p * beatCount;
    const beatIdx = Math.min(beatCount - 1, Math.floor(scaled));
    const local = scaled - beatIdx;
    // Fast clean attack (0..0.16), smooth exponential-like release (0.16..0.95)
    let imp = 0;
    if (local < 0.16) {
      imp = easeOutQuart(local / 0.16);
    } else if (local < 0.94) {
      const dec = (local - 0.16) / 0.78;
      imp = Math.pow(1 - dec, 2.2);
    }
    return { impulse: imp, beatIdx: beatIdx, local: local };
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const subtleFloat = Math.sin(loopPhase * 2) * 0.005 * s;

  let drumAngle = 0;
  let drumBaseScale = 1.0;
  let rivetReveal = 1;
  let motifReveal = 1;
  let beatImpulse = 0;
  let beatIndex = 0;
  let ribbonMaster = 0;
  let ribbonPhase = 0;
  let lightShowAmt = 0;
  let drumSheen = -1;

  if (currentScene === 0) {
    // Scene 1: Ceremonial Rotation-Entry onto Stand & Ornament Reveal
    const enterP = easeOutQuart(subProgress(sceneProgress, 0.04, 0.56));
    drumAngle = lerp(-0.38, 0, enterP); // -22 deg to 0 deg
    drumBaseScale = lerp(0.86, 1.0, enterP);
    rivetReveal = easeOutQuart(subProgress(sceneProgress, 0.42, 0.84));
    motifReveal = easeOutQuart(subProgress(sceneProgress, 0.54, 0.94));
  } else if (currentScene === 1) {
    // Scene 2: 4 Rhythmic Drum Beats with Squash & Stretch + Expanding Rhythm Ribbons
    const b = computeBeat(sceneProgress, 4);
    beatImpulse = b.impulse;
    beatIndex = b.beatIdx;
    const env = Math.sin(sceneProgress * Math.PI);
    ribbonMaster = clamp01(env * 1.6) * (0.45 + 0.55 * beatImpulse);
    ribbonPhase = sceneProgress * TAU * 3;
  } else if (currentScene === 2) {
    // Scene 3: Full Festival Beat Showcase — Alternating Rivet Chase & Cloud Illumination
    const b = computeBeat(sceneProgress, 4);
    beatImpulse = b.impulse;
    beatIndex = b.beatIdx;
    lightShowAmt = Math.sin(sceneProgress * Math.PI);
    ribbonMaster = (0.55 + 0.45 * beatImpulse) * clamp01(Math.sin(sceneProgress * Math.PI) * 2.2 + 0.35);
    ribbonPhase = TAU * 3 + sceneProgress * TAU * 4;
    if (sceneProgress >= 0.40 && sceneProgress <= 0.74) {
      drumSheen = easeInOutCubic(subProgress(sceneProgress, 0.40, 0.74));
    }
  } else {
    // Scene 4: Gentle Final Beat Settle, Ribbon Retract & Seamless Return to Exact t=0
    const closingBeat = computeBeat(subProgress(sceneProgress, 0.0, 0.32), 1);
    beatImpulse = closingBeat.impulse * 0.55 * (1 - subProgress(sceneProgress, 0.22, 0.36));
    ribbonMaster = (1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.34))) * 0.55;
    ribbonPhase = TAU * 7 + sceneProgress * TAU;
    motifReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.30, 0.58));
    rivetReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.38, 0.66));
    const exitP = easeInOutCubic(subProgress(sceneProgress, 0.54, 0.96));
    drumAngle = lerp(0, -0.38, exitP);
    drumBaseScale = lerp(1.0, 0.86, exitP);
  }

  // --- LAYER 1: Clean Dark Matte Abyssal Petrol-Teal Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#061A1E");
  bgGrad.addColorStop(0.52, "#041215");
  bgGrad.addColorStop(1, "#02090B");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Rhythm-Bar Motifs (Strictly Outside Sound Ribbon Zone) ---
  const halfW = width * 0.5;
  if (halfW > 0.68 * s) {
    const outerX = Math.min(halfW - 0.08 * s, 0.77 * s);
    const drift = Math.sin(loopPhase) * 0.010 * s;
    drawBgSoundBarMotif(cx - outerX, cy - 0.27 * s + drift, 0.044 * s, "#0D2E35");
    drawBgSoundBarMotif(cx - outerX, cy + 0.27 * s - drift, 0.036 * s, "#113A42");
    drawBgSoundBarMotif(cx + outerX, cy - 0.27 * s - drift, 0.044 * s, "#0D2E35");
    drawBgSoundBarMotif(cx + outerX, cy + 0.27 * s + drift, 0.036 * s, "#113A42");
  }

  const drumY = -0.028 * s;
  const drumR = 0.224 * s;
  const headR = 0.168 * s;

  ctx.save();
  ctx.translate(cx, cy + subtleFloat);

  // --- LAYER 3: Symmetrical 5-Lane Geometric Soundwave Visualizer Ribbons (Strictly Outside Drum) ---
  // Starts at |x| = 0.292*s (0.068*s clear air gap outside drumR = 0.224*s!), 5 disjoint horizontal lanes!
  if (ribbonMaster > 0.005 && halfW > 0.36 * s) {
    const startX = 0.292 * s;
    const maxAvail = Math.min(0.320 * s, halfW - startX - 0.095 * s);
    if (maxAvail > 0.06 * s) {
      const lanes = [
        { yOff: -0.156, lenMult: 0.62, amp: 0.012, thick: 0.0052, col: "#2DD9CE", phOff: 0.0 },
        { yOff: -0.078, lenMult: 0.84, amp: 0.016, thick: 0.0062, col: "#FF654D", phOff: 0.9 },
        { yOff:  0.000, lenMult: 1.00, amp: 0.019, thick: 0.0074, col: "#F2C252", phOff: 1.8 },
        { yOff:  0.078, lenMult: 0.84, amp: 0.016, thick: 0.0062, col: "#FF654D", phOff: 2.7 },
        { yOff:  0.156, lenMult: 0.62, amp: 0.012, thick: 0.0052, col: "#2DD9CE", phOff: 3.6 }
      ];
      for (let side = -1; side <= 1; side += 2) {
        for (let i = 0; i < lanes.length; i++) {
          const ln = lanes[i];
          drawRhythmRibbon(
            side,
            side * startX,
            drumY + ln.yOff * s,
            maxAvail * ln.lenMult,
            ln.amp * s,
            Math.max(2, ln.thick * s),
            ribbonMaster,
            ribbonPhase + ln.phOff,
            ln.col
          );
        }
      }
    }
  }

  // --- LAYER 4: Sculpted Ceremonial Wooden Drum Stand (Always Anchored Cleanly Beneath Drum) ---
  ctx.save();
  const standBaseY = 0.312 * s;
  const standTopY = drumY + drumR * 0.58;

  // Left & Right Angled Cradle Legs (Tucked cleanly behind drum shell across all scales 0.86..1.00)
  ctx.strokeStyle = "#12424C";
  ctx.lineWidth = Math.max(4, 0.022 * s);
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-0.122 * s, standTopY);
  ctx.lineTo(-0.185 * s, standBaseY);
  ctx.moveTo(0.122 * s, standTopY);
  ctx.lineTo(0.185 * s, standBaseY);
  ctx.stroke();

  // Horizontal Crossbeam Tie Bar
  ctx.fillStyle = "#1B5966";
  drawRoundedRectPath(-0.175 * s, standBaseY - 0.048 * s, 0.350 * s, 0.018 * s, 0.006 * s);
  ctx.fill();

  // Centered Brass Ornament Boss on Crossbeam
  ctx.fillStyle = "#F2C252";
  drawDiamond(0, standBaseY - 0.039 * s, 0.014 * s, 0.014 * s, "#F2C252");
  drawDiamond(0, standBaseY - 0.039 * s, 0.006 * s, 0.006 * s, "#FFF2D9");

  // Brass Foot Caps Anchoring the Stand
  ctx.fillStyle = "#F2C252";
  drawRoundedRectPath(-0.205 * s, standBaseY - 0.006 * s, 0.040 * s, 0.014 * s, 0.005 * s);
  ctx.fill();
  drawRoundedRectPath(0.165 * s, standBaseY - 0.006 * s, 0.040 * s, 0.014 * s, 0.005 * s);
  ctx.fill();
  ctx.restore();

  // --- LAYER 5: Hero Icon — Festival Drum (Tanggŭ) with Beat Squash & Stretch ---
  ctx.save();
  ctx.translate(0, drumY);
  const sqX = drumBaseScale * (1 + 0.052 * beatImpulse);
  const sqY = drumBaseScale * (1 - 0.044 * beatImpulse);
  ctx.scale(sqX, sqY);
  ctx.rotate(drumAngle);

  // 5A. Outer Lacquered Tomato-Vermilion Drum Shell Rim
  ctx.save();
  ctx.beginPath();
  ctx.arc(0, 0, drumR, 0, TAU);
  ctx.clip();

  ctx.fillStyle = "#DF3624";
  ctx.fillRect(-drumR - 2, -drumR - 2, drumR * 2 + 4, drumR * 2 + 4);

  // Clean 2D Flat Editorial Upper-Left Lacquer Highlight Half
  ctx.fillStyle = "#F5533D";
  ctx.beginPath();
  ctx.moveTo(-drumR, drumR);
  ctx.lineTo(-drumR, -drumR);
  ctx.lineTo(drumR, -drumR);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // Crisp Outer Gold Trim Ring on Drum Shell Edge
  ctx.strokeStyle = "#F2C252";
  ctx.lineWidth = Math.max(1.8, 0.0042 * s);
  ctx.beginPath();
  ctx.arc(0, 0, drumR, 0, TAU);
  ctx.stroke();

  // 5B. 12 Symmetrical Brass Rivets (Paku Hias) with Scene 3 Beat Chase Illumination
  if (rivetReveal > 0.01) {
    const rivetCount = 12;
    const rivetOrbit = (drumR + headR) * 0.5; // Centered cleanly mid-rim
    const rivetR = 0.0105 * s;

    for (let i = 0; i < rivetCount; i++) {
      const rp = easeOutQuart(subProgress(rivetReveal, (i / rivetCount) * 0.55, 0.45 + (i / rivetCount) * 0.55));
      if (rp <= 0.01) continue;
      const ang = (i * TAU) / rivetCount - Math.PI * 0.5;
      const rx = Math.cos(ang) * rivetOrbit;
      const ry = Math.sin(ang) * rivetOrbit;

      // In Scene 3, alternating triplets light up cleanly in sync with beatIndex
      const isBeatLit = lightShowAmt > 0.05 && ((i + beatIndex) % 3 === 0);
      const litFactor = isBeatLit ? lightShowAmt * (0.45 + 0.55 * beatImpulse) : 0;
      const outerCol = mixHex("#F2C252", "#7BF2E9", litFactor);
      const innerCol = mixHex("#FFF2C2", "#FFFFFF", litFactor);

      ctx.fillStyle = "#9C1E12";
      ctx.beginPath();
      ctx.arc(rx, ry + 0.002 * s, rivetR * rp, 0, TAU);
      ctx.fill();

      ctx.fillStyle = outerCol;
      ctx.beginPath();
      ctx.arc(rx, ry, rivetR * rp, 0, TAU);
      ctx.fill();

      ctx.fillStyle = innerCol;
      ctx.beginPath();
      ctx.arc(rx - rivetR * 0.24 * rp, ry - rivetR * 0.24 * rp, rivetR * 0.34 * rp, 0, TAU);
      ctx.fill();
    }
  }

  // 5C. Warm Ivory Parchment Drumhead Membrane
  ctx.fillStyle = "#A32215";
  ctx.beginPath();
  ctx.arc(0, 0, headR + 0.006 * s, 0, TAU);
  ctx.fill();

  const headCol = mixHex("#FFF2D9", "#FFFFFF", beatImpulse * 0.45);
  ctx.fillStyle = headCol;
  ctx.beginPath();
  ctx.arc(0, 0, headR, 0, TAU);
  ctx.fill();

  // Painted Ceremonial Aqua-Turquoise Ring Band on Drumhead Perimeter (Flashes Warm Brass on Beat)
  const bandCol = mixHex("#26BFB5", "#F2C252", beatImpulse * 0.65);
  ctx.strokeStyle = bandCol;
  ctx.lineWidth = Math.max(2.5, 0.0085 * s);
  ctx.beginPath();
  ctx.arc(0, 0, headR - 0.014 * s, 0, TAU);
  ctx.stroke();

  // 5D. Painted Drumhead Motifs: 4 Auspicious Clouds + Centered Geometric "2027"
  if (motifReveal > 0.01) {
    ctx.save();
    ctx.globalAlpha = motifReveal;

    // 4 Symmetrical Painted Ruyi Cloud Motifs around the Drumhead (Top, Bottom, Left, Right)
    const cloudDist = headR * 0.66;
    const cloudScale = 0.024 * s * motifReveal * (1 + 0.08 * beatImpulse);
    const cloudPositions = [
      { x: 0, y: -cloudDist, rot: 0 },
      { x: 0, y:  cloudDist, rot: Math.PI },
      { x: -cloudDist, y: 0, rot: -Math.PI * 0.5 },
      { x:  cloudDist, y: 0, rot:  Math.PI * 0.5 }
    ];
    for (let c = 0; c < 4; c++) {
      const cp = cloudPositions[c];
      const activePair = lightShowAmt > 0.05 && ((c + beatIndex) % 2 === 0);
      const cCol = activePair
        ? mixHex("#22B8AE", "#F04632", lightShowAmt * (0.4 + 0.6 * beatImpulse))
        : (c % 2 === 0 ? "#22B8AE" : "#DF3624");
      drawRuyiCloud(cp.x, cp.y, cloudScale, cp.rot, cCol);
    }

    // Crisp Horizontal Framing Accent Lines Above & Below "2027"
    const ruleHalfW = 0.068 * s * motifReveal;
    ctx.strokeStyle = "#22B8AE";
    ctx.lineWidth = Math.max(1.4, 0.0028 * s);
    ctx.beginPath();
    ctx.moveTo(-ruleHalfW, -0.036 * s);
    ctx.lineTo(ruleHalfW, -0.036 * s);
    ctx.moveTo(-ruleHalfW, 0.036 * s);
    ctx.lineTo(ruleHalfW, 0.036 * s);
    ctx.stroke();

    // Custom Geometric Vector "2027" Numerals Centered Cleanly on Drumhead
    const digits = ["2", "0", "2", "7"];
    const dW = 0.025 * s;
    const dH = 0.038 * s;
    const dGap = 0.010 * s;
    const totalDW = digits.length * dW + (digits.length - 1) * dGap;
    const startX = -totalDW * 0.5;
    const dLineW = Math.max(2, 0.0054 * s);
    const digitCol = mixHex("#C72416", "#0D5954", lightShowAmt * beatImpulse * 0.35);
    for (let di = 0; di < digits.length; di++) {
      drawVectorDigit(digits[di], startX + di * (dW + dGap), -dH * 0.5, dW, dH, digitCol, dLineW);
    }

    ctx.restore();
  }

  // Crisp Diagonal Sheen Sweep Clipped Strictly Inside Drumhead (Scene 3)
  if (drumSheen >= 0 && drumSheen <= 1) {
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, headR, 0, TAU);
    ctx.clip();
    const sx = lerp(-headR * 1.8, headR * 1.8, drumSheen);
    ctx.fillStyle = "rgba(255, 255, 255, 0.45)";
    ctx.beginPath();
    ctx.moveTo(sx - 0.026 * s, -headR * 1.2);
    ctx.lineTo(sx + 0.022 * s, -headR * 1.2);
    ctx.lineTo(sx - 0.052 * s, headR * 1.2);
    ctx.lineTo(sx - 0.100 * s, headR * 1.2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  ctx.restore();
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function drawRoundedRectPath(x, y, w, h, r) {
    const rr = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawFlatCloud(x, y, unit, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-1.05 * unit, 0.22 * unit);
    ctx.arc(-0.68 * unit, 0.04 * unit, 0.30 * unit, Math.PI * 0.72, Math.PI * 1.88);
    ctx.arc(-0.14 * unit, -0.14 * unit, 0.39 * unit, Math.PI * 1.05, Math.PI * 1.94);
    ctx.arc(0.45 * unit, 0.02 * unit, 0.32 * unit, Math.PI * 1.12, Math.PI * 2.02);
    ctx.arc(0.82 * unit, 0.12 * unit, 0.20 * unit, Math.PI * 1.25, Math.PI * 0.5);
    ctx.lineTo(-0.88 * unit, 0.32 * unit);
    ctx.arc(-0.88 * unit, 0.22 * unit, 0.10 * unit, Math.PI * 0.5, Math.PI * 1.15);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawAbstractPetal(x, y, r, rot, color) {
    if (r <= 0.4) return;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, -r * 1.35);
    ctx.bezierCurveTo(r * 0.85, -r * 0.45, r * 0.85, r * 0.45, 0, r * 1.35);
    ctx.bezierCurveTo(-r * 0.85, r * 0.45, -r * 0.85, -r * 0.45, 0, -r * 1.35);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawWindRibbon(side, xStart, yCenter, spanX, ampY, thickness, drawP, fadeAlpha, phase, color) {
    if (drawP <= 0.01 || fadeAlpha <= 0.01) return;
    const steps = 26;
    const maxStep = Math.max(2, Math.floor(steps * drawP));
    ctx.save();
    ctx.globalAlpha = fadeAlpha;
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    for (let i = 0; i <= maxStep; i++) {
      const u = i / steps;
      const px = xStart + side * u * spanX;
      const py = yCenter + Math.sin(u * Math.PI * 1.6 + phase) * ampY;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawBgCrescentEmblem(x, y, r, flipX, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(flipX ? -1 : 1, 1);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#050C1A";
    ctx.beginPath();
    ctx.arc(r * 0.36, -r * 0.14, r * 0.78, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  function traceFanSector(rIn, rOut, halfAngle) {
    const a0 = -Math.PI * 0.5 - halfAngle;
    const a1 = -Math.PI * 0.5 + halfAngle;
    ctx.beginPath();
    ctx.arc(0, 0, rOut, a0, a1, false);
    ctx.arc(0, 0, rIn, a1, a0, true);
    ctx.closePath();
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const hoverY = Math.sin(loopPhase * 2) * 0.005 * s;

  const maxHalfOpen = (70 * Math.PI) / 180; // 140-deg graceful full span
  let openAmt = 0;        // 0 = closed vertical stick, 1 = fully opened fan
  let mtnBackReveal = 0;
  let mtnMidReveal = 0;
  let mtnFrontReveal = 0;
  let moonReveal = 0;
  let cloudReveal = 0;
  let digitsReveal = 0;
  let parallaxShift = 0;
  let fanWaveAngle = 0;
  let windAmt = 0;
  let windFlow = 0;
  let fanSheen = -1;

  if (currentScene === 0) {
    // Scene 1: Blade-by-Blade Symmetrical Fan Opening
    openAmt = easeInOutQuint(subProgress(sceneProgress, 0.06, 0.88));
  } else if (currentScene === 1) {
    // Scene 2: Layered Mountain & Cloud Parallax Reveal + Moon & "2027" Typography
    openAmt = 1;
    mtnBackReveal = easeOutQuart(subProgress(sceneProgress, 0.02, 0.38));
    mtnMidReveal = easeOutQuart(subProgress(sceneProgress, 0.14, 0.50));
    mtnFrontReveal = easeOutQuart(subProgress(sceneProgress, 0.26, 0.62));
    moonReveal = easeOutQuart(subProgress(sceneProgress, 0.24, 0.60));
    cloudReveal = easeOutQuart(subProgress(sceneProgress, 0.38, 0.78));
    digitsReveal = easeInOutCubic(subProgress(sceneProgress, 0.44, 0.88));
    parallaxShift = lerp(-0.025 * s, 0, easeOutQuart(subProgress(sceneProgress, 0.10, 0.92)));
    if (sceneProgress >= 0.66 && sceneProgress <= 0.96) {
      fanSheen = easeInOutCubic(subProgress(sceneProgress, 0.66, 0.96));
    }
  } else if (currentScene === 2) {
    // Scene 3: Graceful Ceremonial Fan Wave + Flowing Outer Wind Ribbons & Petals
    openAmt = 1;
    mtnBackReveal = 1;
    mtnMidReveal = 1;
    mtnFrontReveal = 1;
    moonReveal = 1;
    cloudReveal = 1;
    digitsReveal = 1;
    const waveEnv = Math.sin(sceneProgress * Math.PI);
    fanWaveAngle = waveEnv * Math.sin(sceneProgress * Math.PI * 3) * 0.072; // Gentle +-4.1 deg ceremonial wave
    parallaxShift = Math.sin(sceneProgress * Math.PI * 2) * 0.024 * s;
    windAmt = clamp01(waveEnv * 1.4);
    windFlow = sceneProgress;
  } else {
    // Scene 4: Landscape Settle & Graceful Blade-by-Blade Fan Close back to Exact t=0
    const landOut = 1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.34));
    mtnBackReveal = landOut;
    mtnMidReveal = landOut;
    mtnFrontReveal = landOut;
    moonReveal = landOut;
    cloudReveal = landOut;
    digitsReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.24));
    openAmt = 1 - easeInOutQuint(subProgress(sceneProgress, 0.28, 0.94));
  }

  const halfOpen = maxHalfOpen * openAmt;
  const pivotY = 0.255 * s;
  const rIn = 0.235 * s;
  const rOut = 0.555 * s; // Apex at +0.255 - 0.555 = -0.300*s (20% top margin!)

  // --- LAYER 1: Clean Dark Matte Arctic Navy-Slate Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#071022");
  bgGrad.addColorStop(0.52, "#050C1A");
  bgGrad.addColorStop(1, "#02060E");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Subtle Architectural Crescent Motifs (Strictly Outside Fan & Wind Zones) ---
  const halfW = width * 0.5;
  if (halfW > 0.72 * s) {
    const outerX = Math.min(halfW - 0.075 * s, 0.80 * s);
    const drift = Math.sin(loopPhase) * 0.010 * s;
    drawBgCrescentEmblem(cx - outerX, cy - 0.33 * s + drift, 0.028 * s, false, "#112245");
    drawBgCrescentEmblem(cx + outerX, cy - 0.33 * s - drift, 0.028 * s, true, "#112245");
  }

  // --- LAYER 3: Scene 3 Strictly Disjoint Outer Wind Ribbons & Abstract Petals ---
  // Fan outer swept horizontal extent <= 0.555 * sin(74 deg) = 0.534*s; wind strictly starts at |x| >= 0.585*s!
  if (windAmt > 0.005 && halfW > 0.64 * s) {
    ctx.save();
    ctx.translate(cx, cy + hoverY);

    const windStart = 0.585 * s;
    const windSpan = Math.min(0.235 * s, halfW - windStart - 0.045 * s);
    const drawP = easeOutQuart(subProgress(windFlow, 0.0, 0.55));
    const fadeOut = 1 - easeInOutCubic(subProgress(windFlow, 0.68, 1.0));
    const ribbonAlpha = clamp01(windAmt) * fadeOut;

    if (windSpan > 0.06 * s) {
      const lanes = [
        { yOff: -0.21, amp: 0.018, thick: 0.0052, col: "#6EC4F5", petalCol: "#E8F1FC", ph: 0.4 },
        { yOff:  0.00, amp: 0.022, thick: 0.0062, col: "#E8F1FC", petalCol: "#F5D68E", ph: 1.6 },
        { yOff:  0.20, amp: 0.016, thick: 0.0048, col: "#F5D68E", petalCol: "#6EC4F5", ph: 2.8 }
      ];

      for (let side = -1; side <= 1; side += 2) {
        for (let i = 0; i < lanes.length; i++) {
          const ln = lanes[i];
          const ly = ln.yOff * s;
          drawWindRibbon(
            side,
            side * windStart,
            ly,
            windSpan,
            ln.amp * s,
            Math.max(1.8, ln.thick * s),
            drawP,
            ribbonAlpha,
            ln.ph + windFlow * Math.PI * 1.4,
            ln.col
          );

          // Single crisp abstract petal gliding smoothly ahead of ribbon tip (zero overlap with ribbon)
          const petU = clamp01(drawP * 0.85 + 0.15 * windFlow);
          const petX = side * (windStart + petU * windSpan * 0.72);
          const petY = ly - 0.036 * s + Math.sin(windFlow * TAU + i) * 0.008 * s;
          drawAbstractPetal(petX, petY, 0.0095 * s * ribbonAlpha, side * (0.6 + windFlow * 1.5), ln.petalCol);
        }
      }
    }
    ctx.restore();
  }

  // --- LAYER 4: Hero Icon — Folding Fan (Zheshan) Centered & Pivoted Cleanly ---
  ctx.save();
  ctx.translate(cx, cy + hoverY + pivotY);
  ctx.rotate(fanWaveAngle);

  const ribCount = 11; // Index 0..10 (0 & 10 are sculpted outer silver guard sticks)

  // 4A. Inner Exposed Bamboo-Silver Fan Sticks (from pivot to rIn)
  if (openAmt > 0.002) {
    for (let i = 1; i < ribCount - 1; i++) {
      const frac = i / (ribCount - 1);
      const ang = lerp(-halfOpen, halfOpen, frac);
      ctx.save();
      ctx.rotate(ang);
      ctx.fillStyle = i % 2 === 0 ? "#A9C4E4" : "#8AA8CC";
      drawRoundedRectPath(-0.0038 * s, -rIn - 0.01 * s, 0.0076 * s, rIn + 0.01 * s, 0.003 * s);
      ctx.fill();
      ctx.restore();
    }
  }

  // 4B. Unfolded Silk Fan Leaf & Clipped Parallax Mountain/Cloud Landscape Painting
  if (halfOpen > 0.008) {
    ctx.save();
    traceFanSector(rIn, rOut, halfOpen);
    ctx.clip();

    // Base Ice-Pearl Silk Paper Fill
    ctx.fillStyle = "#EAF2FC";
    ctx.fillRect(-rOut - 4, -rOut - 4, rOut * 2 + 8, rOut + 8);

    // Subtle Pleated Fan Fold Tonal Bands Between Adjacent Ribs (gives crisp tactile 2D vector craft)
    const pleatSteps = ribCount - 1;
    for (let p = 0; p < pleatSteps; p++) {
      if (p % 2 === 1) {
        const a0 = -Math.PI * 0.5 + lerp(-halfOpen, halfOpen, p / pleatSteps);
        const a1 = -Math.PI * 0.5 + lerp(-halfOpen, halfOpen, (p + 1) / pleatSteps);
        ctx.fillStyle = "#DCE9F8";
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.arc(0, 0, rOut + 2, a0, a1, false);
        ctx.closePath();
        ctx.fill();
      }
    }

    // Warm Moon-Gold Full Moon Rising Behind Left Ridge (Strictly Clear of Center "2027")
    if (moonReveal > 0.01) {
      const moonX = -0.175 * s + parallaxShift * 0.25;
      const moonY = lerp(-0.340 * s, -0.430 * s, moonReveal);
      const moonR = 0.042 * s * moonReveal;
      ctx.fillStyle = "#F5D68E";
      ctx.beginPath();
      ctx.arc(moonX, moonY, moonR, 0, TAU);
      ctx.fill();

      // Subtle flat upper crescent highlight on moon
      ctx.fillStyle = "#FFF1C7";
      ctx.beginPath();
      ctx.arc(moonX - moonR * 0.16, moonY - moonR * 0.16, moonR * 0.58, 0, TAU);
      ctx.fill();
    }

    // Mountain Layer 1 (Distant Pale Indigo Ridge — extends cleanly to pivot baseline inside fan clip)
    if (mtnBackReveal > 0.005) {
      const yShift = lerp(0.24 * s, 0, mtnBackReveal);
      const px = parallaxShift * 0.4;
      ctx.fillStyle = "#7BA1D4";
      ctx.beginPath();
      ctx.moveTo(-rOut - 10, 0);
      ctx.lineTo(-rOut - 10, -0.32 * s + yShift);
      ctx.lineTo(-0.46 * s + px, -0.34 * s + yShift);
      ctx.lineTo(-0.26 * s + px, -0.40 * s + yShift);
      ctx.lineTo(-0.08 * s + px, -0.33 * s + yShift);
      ctx.lineTo(0.14 * s + px, -0.41 * s + yShift);
      ctx.lineTo(0.34 * s + px, -0.33 * s + yShift);
      ctx.lineTo(0.50 * s + px, -0.37 * s + yShift);
      ctx.lineTo(rOut + 10, -0.31 * s + yShift);
      ctx.lineTo(rOut + 10, 0);
      ctx.closePath();
      ctx.fill();
    }

    // Parallax Flat Cloud Layer 1 (Mid-High Valley Drift)
    if (cloudReveal > 0.01) {
      ctx.save();
      ctx.globalAlpha = cloudReveal;
      drawFlatCloud(-0.24 * s + parallaxShift * 1.1, -0.355 * s, 0.042 * s * cloudReveal, "#FFFFFF");
      drawFlatCloud(0.24 * s - parallaxShift * 0.9, -0.370 * s, 0.038 * s * cloudReveal, "#FFFFFF");
      ctx.restore();
    }

    // Mountain Layer 2 (Mid Royal Indigo Peaks — extends cleanly to pivot baseline inside fan clip)
    if (mtnMidReveal > 0.005) {
      const yShift = lerp(0.24 * s, 0, mtnMidReveal);
      const px = parallaxShift * 0.75;
      ctx.fillStyle = "#3A64B3";
      ctx.beginPath();
      ctx.moveTo(-rOut - 10, 0);
      ctx.lineTo(-rOut - 10, -0.25 * s + yShift);
      ctx.lineTo(-0.44 * s + px, -0.28 * s + yShift);
      ctx.lineTo(-0.18 * s + px, -0.365 * s + yShift);
      ctx.lineTo(0.02 * s + px, -0.295 * s + yShift);
      ctx.lineTo(0.22 * s + px, -0.360 * s + yShift);
      ctx.lineTo(0.46 * s + px, -0.265 * s + yShift);
      ctx.lineTo(rOut + 10, -0.24 * s + yShift);
      ctx.lineTo(rOut + 10, 0);
      ctx.closePath();
      ctx.fill();
    }

    // Mountain Layer 3 (Foreground Deep Midnight Indigo Silhouette Anchoring Entire Lower Fan Arc)
    if (mtnFrontReveal > 0.005) {
      const yShift = lerp(0.22 * s, 0, mtnFrontReveal);
      const px = parallaxShift * 1.15;
      ctx.fillStyle = "#19336E";
      ctx.beginPath();
      ctx.moveTo(-rOut - 10, 0);
      ctx.lineTo(-rOut - 10, -0.18 * s + yShift);
      ctx.lineTo(-0.36 * s + px, -0.24 * s + yShift);
      ctx.lineTo(-0.12 * s + px, -0.315 * s + yShift);
      ctx.lineTo(0.08 * s + px, -0.255 * s + yShift);
      ctx.lineTo(0.28 * s + px, -0.305 * s + yShift);
      ctx.lineTo(0.46 * s + px, -0.22 * s + yShift);
      ctx.lineTo(rOut + 10, -0.17 * s + yShift);
      ctx.lineTo(rOut + 10, 0);
      ctx.closePath();
      ctx.fill();
    }

    // Crisp Midnight Indigo "2027" Vector Numerals Centered in Clean Upper Sky Band
    if (digitsReveal > 0.01) {
      const digits = ["2", "0", "2", "7"];
      const dW = 0.029 * s;
      const dH = 0.042 * s;
      const dGap = 0.012 * s;
      const totalDW = digits.length * dW + (digits.length - 1) * dGap;
      const startX = -totalDW * 0.5;
      const skyCenterY = -0.472 * s;
      const dLineW = Math.max(1.8, 0.0052 * s);

      ctx.save();
      ctx.beginPath();
      ctx.rect(-totalDW * 0.65, skyCenterY - dH * 0.68, totalDW * 1.30, dH * 1.36);
      ctx.clip();

      for (let di = 0; di < digits.length; di++) {
        const dp = easeOutQuart(subProgress(digitsReveal, di * 0.14, 0.58 + di * 0.14));
        if (dp <= 0.001) continue;
        const dx = startX + di * (dW + dGap);
        const dy = skyCenterY - dH * 0.5 + (1 - dp) * 0.028 * s;
        ctx.save();
        ctx.globalAlpha = dp;
        drawVectorDigit(digits[di], dx, dy, dW, dH, "#162D61", dLineW);
        ctx.restore();
      }
      ctx.restore();
    }

    // Subtle Crisp Pleat Crease Hairlines inside Fan Leaf
    ctx.strokeStyle = "rgba(25, 51, 110, 0.14)";
    ctx.lineWidth = Math.max(1, 0.0018 * s);
    for (let i = 1; i < ribCount - 1; i++) {
      const ang = -Math.PI * 0.5 + lerp(-halfOpen, halfOpen, i / (ribCount - 1));
      ctx.beginPath();
      ctx.moveTo(Math.cos(ang) * rIn, Math.sin(ang) * rIn);
      ctx.lineTo(Math.cos(ang) * rOut, Math.sin(ang) * rOut);
      ctx.stroke();
    }

    // Crisp Curved Silver Sheen Sweeping Across Fan Leaf (Scene 2 Finale)
    if (fanSheen >= 0 && fanSheen <= 1) {
      const sheenAng = lerp(-halfOpen * 1.15, halfOpen * 1.15, fanSheen) - Math.PI * 0.5;
      ctx.fillStyle = "rgba(255, 255, 255, 0.42)";
      ctx.beginPath();
      ctx.arc(0, 0, rOut + 2, sheenAng - 0.10, sheenAng + 0.10, false);
      ctx.arc(0, 0, rIn - 2, sheenAng + 0.10, sheenAng - 0.10, true);
      ctx.closePath();
      ctx.fill();
    }

    ctx.restore();

    // Crisp Warm Gold Outer & Inner Fan Arc Borders
    const a0 = -Math.PI * 0.5 - halfOpen;
    const a1 = -Math.PI * 0.5 + halfOpen;
    ctx.strokeStyle = "#E8C67A";
    ctx.lineWidth = Math.max(2, 0.0052 * s);
    ctx.beginPath();
    ctx.arc(0, 0, rOut, a0, a1, false);
    ctx.stroke();

    ctx.lineWidth = Math.max(1.6, 0.0040 * s);
    ctx.beginPath();
    ctx.arc(0, 0, rIn, a0, a1, false);
    ctx.stroke();
  }

  // 4C. Left & Right Sculpted Platinum-Silver Outer Guard Sticks (Close Together Seamlessly at halfOpen = 0)
  for (let side = -1; side <= 1; side += 2) {
    ctx.save();
    ctx.rotate(side * halfOpen);
    const guardW = 0.022 * s;
    const guardLen = rOut + 0.012 * s;

    // Outer guard stick base
    drawRoundedRectPath(-guardW * 0.5, -guardLen, guardW, guardLen + 0.018 * s, guardW * 0.45);
    ctx.fillStyle = "#D4E4F7";
    ctx.fill();

    // Inner recessed indigo enamel inlay strip along guard stick
    drawRoundedRectPath(-guardW * 0.22, -guardLen + 0.035 * s, guardW * 0.44, guardLen - 0.075 * s, guardW * 0.2);
    ctx.fillStyle = "#23438A";
    ctx.fill();

    // Crisp gold ferrule tip accent
    drawRoundedRectPath(-guardW * 0.5, -guardLen, guardW, 0.022 * s, guardW * 0.4);
    ctx.fillStyle = "#F5D68E";
    ctx.fill();

    ctx.restore();
  }

  // 4D. Hanging Silver & Gold Pivot Tassel Cord (Below Fan Pivot, Gentle Counter-Sway)
  ctx.save();
  ctx.rotate(-fanWaveAngle * 1.4);
  ctx.fillStyle = "#E8C67A";
  drawRoundedRectPath(-0.004 * s, 0.016 * s, 0.008 * s, 0.036 * s, 0.004 * s);
  ctx.fill();

  // Frost-Cyan Bead Accent
  ctx.fillStyle = "#6EC4F5";
  ctx.beginPath();
  ctx.arc(0, 0.056 * s, 0.012 * s, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#C2E8FF";
  ctx.beginPath();
  ctx.arc(-0.003 * s, 0.053 * s, 0.004 * s, 0, TAU);
  ctx.fill();

  // 5 Crisp Separated Vertical Silver & Gold Tassel Strands
  const tCount = 5;
  const tGap = 0.0068 * s;
  const tW = 0.0036 * s;
  for (let k = 0; k < tCount; k++) {
    const idx = k - (tCount - 1) * 0.5;
    const tLen = (0.058 * s) * (1 - Math.abs(idx) * 0.08);
    ctx.fillStyle = k % 2 === 0 ? "#E8F1FC" : "#F5D68E";
    drawRoundedRectPath(idx * tGap - tW * 0.5, 0.070 * s, tW, tLen, tW * 0.5);
    ctx.fill();
  }
  ctx.restore();

  // 4E. Central Sculpted Gold & Indigo Fan Pivot Rivet Pin (Anchors All Ribs Cleanly)
  ctx.fillStyle = "#F5D68E";
  ctx.beginPath();
  ctx.arc(0, 0, 0.019 * s, 0, TAU);
  ctx.fill();

  ctx.fillStyle = "#1B3675";
  ctx.beginPath();
  ctx.arc(0, 0, 0.010 * s, 0, TAU);
  ctx.fill();

  ctx.fillStyle = "#E8F1FC";
  ctx.beginPath();
  ctx.arc(-0.002 * s, -0.002 * s, 0.0035 * s, 0, TAU);
  ctx.fill();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInQuart(u) {
    u = clamp01(u);
    return u * u * u * u;
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function drawRoundedRectPath(x, y, w, h, r) {
    const rr = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawFourPointSparkle(x, y, rOut, rIn, rot, color) {
    if (rOut <= 0.4) return;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? rOut : rIn;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawBgRoyalHex(x, y, r, color) {
    // Subtle matte geometric hexagon motif strictly in far-outer background
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i * Math.PI) / 3 - Math.PI / 6;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "#10081F";
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i * Math.PI) / 3 - Math.PI / 6;
      if (i === 0) ctx.moveTo(Math.cos(a) * r * 0.58, Math.sin(a) * r * 0.58);
      else ctx.lineTo(Math.cos(a) * r * 0.58, Math.sin(a) * r * 0.58);
    }
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = color;
    const sq = r * 0.24;
    ctx.fillRect(-sq, -sq, sq * 2, sq * 2);
    ctx.restore();
  }

  function drawFlatCoinDisc(x, y, w, h, alpha) {
    if (alpha <= 0.005) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    const hw = w * 0.5;
    const r = h * 0.34;

    // Lower bronze bevel base
    drawRoundedRectPath(x - hw, y, w, h, r);
    ctx.fillStyle = "#C98018";
    ctx.fill();

    // Main amber gold coin face band
    drawRoundedRectPath(x - hw, y, w, h * 0.72, r);
    ctx.fillStyle = "#F7B93E";
    ctx.fill();

    // Crisp top champagne highlight strip
    drawRoundedRectPath(x - hw + w * 0.05, y + h * 0.09, w * 0.90, h * 0.22, r * 0.5);
    ctx.fillStyle = "#FFE69E";
    ctx.fill();

    // Centered royal-amethyst recessed square coin mark
    const markW = w * 0.14;
    const markH = h * 0.42;
    ctx.fillStyle = "#5F2B9E";
    ctx.fillRect(x - markW * 0.5, y + (h - markH) * 0.5, markW, markH);

    // Symmetrical side milling notches
    ctx.fillStyle = "#B56F10";
    ctx.fillRect(x - hw * 0.65, y + h * 0.34, w * 0.045, h * 0.32);
    ctx.fillRect(x + hw * 0.65 - w * 0.045, y + h * 0.34, w * 0.045, h * 0.32);

    ctx.restore();
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const subtleBreath = Math.sin(loopPhase * 2) * 0.004 * s;

  // Coin stack specs (3 strictly separated columns: center 4 coins, left 3 coins, right 3 coins)
  const baseY = 0.268 * s;
  const coinH = 0.025 * s;
  const coinGap = 0.004 * s;
  const coinStep = coinH + coinGap;
  const centerW = 0.148 * s;
  const sideW = 0.124 * s;
  const sideX = 0.156 * s; // Clear gap between center half (0.074*s) and side inner edge (0.094*s) = 0.020*s!

  // Define all 10 coins with exact drop order (coin 0 = bottom center anchor always poised at t=0 & t=20)
  const coins = [
    { x: 0,      tier: 0, w: centerW, anchor: true,  tIn: 0.00, tOut: 1.00 },
    { x: -sideX, tier: 0, w: sideW,   anchor: false, tIn: 0.04, tOut: 0.72 },
    { x: sideX,  tier: 0, w: sideW,   anchor: false, tIn: 0.08, tOut: 0.72 },
    { x: 0,      tier: 1, w: centerW, anchor: false, tIn: 0.18, tOut: 0.60 },
    { x: -sideX, tier: 1, w: sideW,   anchor: false, tIn: 0.26, tOut: 0.52 },
    { x: sideX,  tier: 1, w: sideW,   anchor: false, tIn: 0.30, tOut: 0.52 },
    { x: 0,      tier: 2, w: centerW, anchor: false, tIn: 0.40, tOut: 0.42 },
    { x: -sideX, tier: 2, w: sideW,   anchor: false, tIn: 0.48, tOut: 0.34 },
    { x: sideX,  tier: 2, w: sideW,   anchor: false, tIn: 0.52, tOut: 0.34 },
    { x: 0,      tier: 3, w: centerW, anchor: false, tIn: 0.62, tOut: 0.26 }
  ];

  let ingotVisible = 0;
  let ingotYOff = 0;
  let ingotSX = 1;
  let ingotSY = 1;
  let plaqueReveal = 0;
  let impactP = -1;
  let raysReveal = 0;
  let raysRot = 0;
  let sparklePhase = -1;
  let ingotSheen = -1;
  let treasurePulse = 0;

  if (currentScene === 0) {
    // Scene 1: Staggered Coin Stack Cascade & Controlled Settle
    ingotVisible = 0;
  } else if (currentScene === 1) {
    // Scene 2: Golden Yuanbao Ingot Drop, Controlled Squash & Solid Flat Impact Wave
    const dropP = subProgress(sceneProgress, 0.04, 0.42);
    ingotVisible = easeOutQuart(subProgress(sceneProgress, 0.02, 0.14));
    ingotYOff = lerp(-0.34 * s, 0, easeInQuart(dropP));

    if (sceneProgress >= 0.42 && sceneProgress <= 0.72) {
      const sqP = subProgress(sceneProgress, 0.42, 0.72);
      const damped = Math.sin(sqP * Math.PI * 2) * (1 - sqP);
      ingotSX = 1 + 0.068 * damped;
      ingotSY = 1 - 0.064 * damped;
    }

    if (sceneProgress >= 0.42 && sceneProgress <= 0.86) {
      impactP = subProgress(sceneProgress, 0.42, 0.86);
    }

    plaqueReveal = easeOutQuart(subProgress(sceneProgress, 0.56, 0.94));
  } else if (currentScene === 2) {
    // Scene 3: Rotating Flat Sunburst Rays, Twinkling 4-Point Sparkles & Gold Sheen
    ingotVisible = 1;
    plaqueReveal = 1;
    const env = Math.sin(sceneProgress * Math.PI);
    raysReveal = clamp01(env * 1.45);
    raysRot = easeInOutCubic(sceneProgress) * (TAU / 10); // Clean 36-deg rotational glide
    sparklePhase = sceneProgress;
    treasurePulse = 0.5 - 0.5 * Math.cos(sceneProgress * Math.PI * 4);
    if (sceneProgress >= 0.22 && sceneProgress <= 0.62) {
      ingotSheen = easeInOutCubic(subProgress(sceneProgress, 0.22, 0.62));
    }
  } else {
    // Scene 4: Graceful Levitation & Reverse Stack Lift back to Exact t=0 Poised Anchor Coin
    plaqueReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.20));
    const liftP = easeInOutCubic(subProgress(sceneProgress, 0.06, 0.40));
    ingotYOff = lerp(0, -0.34 * s, liftP);
    ingotVisible = 1 - easeInOutCubic(subProgress(sceneProgress, 0.24, 0.42));
  }

  // --- LAYER 1: Clean Dark Matte Royal Aubergine-Indigo Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#160B29");
  bgGrad.addColorStop(0.52, "#10081F");
  bgGrad.addColorStop(1, "#070310");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Hex Motifs (Strictly Outside Ray & Sparkle Zones) ---
  const halfW = width * 0.5;
  if (halfW > 0.66 * s) {
    const outerX = Math.min(halfW - 0.09 * s, 0.74 * s);
    const drift = Math.sin(loopPhase) * 0.011 * s;
    drawBgRoyalHex(cx - outerX, cy - 0.25 * s + drift, 0.042 * s, "#231240");
    drawBgRoyalHex(cx - outerX, cy + 0.25 * s - drift, 0.034 * s, "#2C174F");
    drawBgRoyalHex(cx + outerX, cy - 0.25 * s - drift, 0.042 * s, "#231240");
    drawBgRoyalHex(cx + outerX, cy + 0.25 * s + drift, 0.034 * s, "#2C174F");
  }

  ctx.save();
  ctx.translate(cx, cy + subtleBreath);

  // --- LAYER 3: Scene 3 Upper-Hemisphere Ceremonial Flat Sunburst Rays (Strictly Above Plinth & Outside Ingot) ---
  // Spans strictly above the plinth horizon (-166 deg to -14 deg) at rInner = 0.270*s, ZERO overlap with coins/plinth, ZERO glow!
  if (raysReveal > 0.005) {
    const rayCenterY = 0.020 * s;
    const rayCount = 9;
    const arcStart = (-166 * Math.PI) / 180;
    const arcEnd = (-14 * Math.PI) / 180;
    const rInner = 0.270 * s;
    const rOuter = lerp(0.290 * s, 0.405 * s, easeOutQuart(raysReveal));
    const swayRot = Math.sin(raysRot * 5) * 0.065; // Gentle ceremonial harmonic fan sweep (returns cleanly to 0)

    ctx.save();
    ctx.translate(0, rayCenterY);
    ctx.rotate(swayRot);
    ctx.globalAlpha = raysReveal;

    for (let i = 0; i < rayCount; i++) {
      const frac = rayCount > 1 ? i / (rayCount - 1) : 0.5;
      const midA = lerp(arcStart, arcEnd, frac);
      const halfSpanIn = 0.042;
      const halfSpanOut = 0.088;
      ctx.fillStyle = i % 2 === 0 ? "#2D1854" : "#3E2273";
      ctx.beginPath();
      ctx.moveTo(Math.cos(midA - halfSpanIn) * rInner, Math.sin(midA - halfSpanIn) * rInner);
      ctx.lineTo(Math.cos(midA - halfSpanOut) * rOuter, Math.sin(midA - halfSpanOut) * rOuter);
      ctx.lineTo(Math.cos(midA + halfSpanOut) * rOuter, Math.sin(midA + halfSpanOut) * rOuter);
      ctx.lineTo(Math.cos(midA + halfSpanIn) * rInner, Math.sin(midA + halfSpanIn) * rInner);
      ctx.closePath();
      ctx.fill();

      // Crisp amber-gold accent cap bar at outer tip of alternating rays
      if (i % 2 === 0) {
        const capR0 = rOuter - 0.013 * s;
        const capR1 = rOuter;
        ctx.fillStyle = "#F7B93E";
        ctx.beginPath();
        ctx.moveTo(Math.cos(midA - halfSpanOut * 0.65) * capR0, Math.sin(midA - halfSpanOut * 0.65) * capR0);
        ctx.lineTo(Math.cos(midA - halfSpanOut * 0.65) * capR1, Math.sin(midA - halfSpanOut * 0.65) * capR1);
        ctx.lineTo(Math.cos(midA + halfSpanOut * 0.65) * capR1, Math.sin(midA + halfSpanOut * 0.65) * capR1);
        ctx.lineTo(Math.cos(midA + halfSpanOut * 0.65) * capR0, Math.sin(midA + halfSpanOut * 0.65) * capR0);
        ctx.closePath();
        ctx.fill();
      }
    }
    ctx.restore();
  }

  // --- LAYER 4: Scene 2 Symmetrical Solid Flat Impact Chevron Waves (Strictly Outside Coin Base) ---
  if (impactP >= 0 && impactP <= 1) {
    const env = Math.sin(impactP * Math.PI);
    const travel = easeOutQuart(impactP);
    const waveY = baseY - 0.055 * s;

    ctx.save();
    ctx.globalAlpha = clamp01(env * 1.25);
    for (let side = -1; side <= 1; side += 2) {
      const wx = side * lerp(0.255 * s, 0.425 * s, travel);
      const wThick = lerp(0.018 * s, 0.008 * s, impactP);
      const wHeight = lerp(0.038 * s, 0.068 * s, travel);

      // Solid flat tapered chevron block (NOT thin stroke)
      ctx.fillStyle = "#F7B93E";
      ctx.beginPath();
      ctx.moveTo(wx, waveY - wHeight);
      ctx.lineTo(wx + side * wThick * 1.5, waveY);
      ctx.lineTo(wx, waveY + wHeight);
      ctx.lineTo(wx - side * wThick * 0.6, waveY + wHeight * 0.65);
      ctx.lineTo(wx + side * wThick * 0.45, waveY);
      ctx.lineTo(wx - side * wThick * 0.6, waveY - wHeight * 0.65);
      ctx.closePath();
      ctx.fill();

      // Secondary outer lavender mini-chevron strictly spaced outside
      const wx2 = wx + side * 0.032 * s;
      ctx.fillStyle = "#B884FF";
      ctx.beginPath();
      ctx.moveTo(wx2, waveY - wHeight * 0.55);
      ctx.lineTo(wx2 + side * wThick * 0.9, waveY);
      ctx.lineTo(wx2, waveY + wHeight * 0.55);
      ctx.lineTo(wx2 - side * wThick * 0.3, waveY);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  // --- LAYER 5: Scene 3 Strictly Disjoint Twinkling 4-Point Diamond Sparkles ---
  if (sparklePhase >= 0 && sparklePhase <= 1) {
    const sparkles = [
      { x: -0.315, y: -0.235, r: 0.026, phase: 0.00, col: "#FFE9A6" },
      { x:  0.315, y: -0.235, r: 0.026, phase: 0.16, col: "#FFE9A6" },
      { x: -0.445, y: -0.055, r: 0.022, phase: 0.32, col: "#C494FF" },
      { x:  0.445, y: -0.055, r: 0.022, phase: 0.48, col: "#C494FF" },
      { x: -0.365, y:  0.125, r: 0.020, phase: 0.24, col: "#F7B93E" },
      { x:  0.365, y:  0.125, r: 0.020, phase: 0.40, col: "#F7B93E" }
    ];
    const masterEnv = Math.sin(sparklePhase * Math.PI);
    for (let i = 0; i < sparkles.length; i++) {
      const sp = sparkles[i];
      const twinkle = 0.35 + 0.65 * Math.pow(Math.max(0, Math.sin((sparklePhase * 2.2 + sp.phase) * Math.PI)), 1.5);
      const curR = sp.r * s * twinkle * clamp01(masterEnv * 1.6);
      drawFourPointSparkle(sp.x * s, sp.y * s, curR, curR * 0.28, sparklePhase * 0.8 * (i % 2 === 0 ? 1 : -1), sp.col);
    }
  }

  // --- LAYER 6: Ceremonial Plinth Base & 3-Column Stacked Gold Coins ---
  // Sleek dark-amethyst flat architectural plinth bar (always poised cleanly at baseY)
  const plinthW = 0.470 * s;
  const plinthH = 0.014 * s;
  drawRoundedRectPath(-plinthW * 0.5, baseY + 0.004 * s, plinthW, plinthH, plinthH * 0.5);
  ctx.fillStyle = "#361C63";
  ctx.fill();
  drawRoundedRectPath(-plinthW * 0.46, baseY + 0.004 * s, plinthW * 0.92, plinthH * 0.35, plinthH * 0.2);
  ctx.fillStyle = "#6F40BF";
  ctx.fill();

  for (let i = 0; i < coins.length; i++) {
    const c = coins[i];
    const restY = baseY - coinH - c.tier * coinStep;
    let curY = restY;
    let curAlpha = 1;

    if (!c.anchor) {
      if (currentScene === 0) {
        const dropP = subProgress(sceneProgress, c.tIn, c.tIn + 0.28);
        if (dropP <= 0.001) {
          curAlpha = 0;
        } else {
          curAlpha = clamp01(dropP * 4);
          // Smooth gravity drop with tiny controlled settle (zero wild bounce)
          const fallP = easeOutQuart(dropP);
          const tinySettle = Math.sin(subProgress(dropP, 0.72, 1.0) * Math.PI) * 0.004 * s;
          curY = lerp(restY - 0.16 * s, restY, fallP) - tinySettle;
        }
      } else if (currentScene === 3) {
        const liftP = subProgress(sceneProgress, c.tOut, c.tOut + 0.24);
        if (liftP >= 0.999) {
          curAlpha = 0;
        } else if (liftP > 0) {
          curAlpha = 1 - easeInOutCubic(liftP);
          curY = lerp(restY, restY - 0.14 * s, easeInOutCubic(liftP));
        }
      }
    }

    drawFlatCoinDisc(c.x, curY, c.w, coinH, curAlpha);
  }

  // --- LAYER 7: Hero Icon — Sculpted 2D Flat Vector Golden Yuanbao Ingot ---
  if (ingotVisible > 0.005) {
    const ingotRestBotY = baseY - 4 * coinStep + coinGap - 0.002 * s; // Flush atop center 4-coin stack (+0.154*s)
    const pScale = 1 + 0.016 * treasurePulse;

    ctx.save();
    ctx.translate(0, ingotRestBotY + ingotYOff);
    ctx.scale(ingotSX * pScale, ingotSY * pScale);
    ctx.globalAlpha = ingotVisible;

    // 7A. Central Golden Pearl Dome (Rising from inside ingot cradle)
    const domeRx = 0.096 * s;
    const domeRy = 0.088 * s;
    const domeCY = -0.172 * s;

    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, domeCY, domeRx, domeRy, 0, Math.PI, TAU);
    ctx.lineTo(domeRx, domeCY + 0.04 * s);
    ctx.lineTo(-domeRx, domeCY + 0.04 * s);
    ctx.closePath();
    ctx.clip();

    // Main Amber Gold Dome Fill
    ctx.fillStyle = "#F7B93E";
    ctx.fillRect(-domeRx - 2, domeCY - domeRy - 2, domeRx * 2 + 4, domeRy + 0.05 * s);

    // Flat 2D Editorial Upper-Left Highlight Crescent on Dome
    ctx.fillStyle = "#FFE596";
    ctx.beginPath();
    ctx.ellipse(-domeRx * 0.24, domeCY - domeRy * 0.16, domeRx * 0.66, domeRy * 0.72, -0.25, 0, TAU);
    ctx.fill();

    // Subtle Crisp Right Bronze Shadow Crescent on Dome
    ctx.fillStyle = "#D9921A";
    ctx.beginPath();
    ctx.ellipse(domeRx * 0.78, domeCY + domeRy * 0.08, domeRx * 0.52, domeRy * 0.92, 0.15, 0, TAU);
    ctx.fill();
    ctx.restore();

    // 7B. Sweeping Golden Yuanbao Boat Cradle Silhouette
    function traceIngotBoatPath() {
      ctx.beginPath();
      // Left high curled wing tip
      ctx.moveTo(-0.205 * s, -0.185 * s);
      // Graceful inner upper saddle dipping smoothly across the front of the dome
      ctx.bezierCurveTo(-0.130 * s, -0.118 * s, 0.130 * s, -0.118 * s, 0.205 * s, -0.185 * s);
      // Right outer sweeping wing curving down smoothly to footing
      ctx.bezierCurveTo(0.215 * s, -0.090 * s, 0.155 * s, -0.015 * s, 0.098 * s, 0);
      // Crisp flat footing resting flush on the center coin stack
      ctx.lineTo(-0.098 * s, 0);
      // Left outer sweeping wing back up to left tip
      ctx.bezierCurveTo(-0.155 * s, -0.015 * s, -0.215 * s, -0.090 * s, -0.205 * s, -0.185 * s);
      ctx.closePath();
    }

    ctx.save();
    traceIngotBoatPath();
    ctx.clip();

    // Base Sovereign Amber Gold Cradle
    ctx.fillStyle = "#F2AB2C";
    ctx.fillRect(-0.23 * s, -0.21 * s, 0.46 * s, 0.23 * s);

    // Upper Bright Gold Lip Rim Following Saddle Curve
    ctx.strokeStyle = "#FFE8A3";
    ctx.lineWidth = Math.max(3, 0.014 * s);
    ctx.beginPath();
    ctx.moveTo(-0.210 * s, -0.185 * s);
    ctx.bezierCurveTo(-0.130 * s, -0.116 * s, 0.130 * s, -0.116 * s, 0.210 * s, -0.185 * s);
    ctx.stroke();

    // Crisp Flat 2D Lower Bronze Pedestal Band
    ctx.fillStyle = "#C77D12";
    ctx.fillRect(-0.23 * s, -0.028 * s, 0.46 * s, 0.032 * s);

    // Subtle Flat Wing Highlight Left Side
    ctx.fillStyle = "#FFD76E";
    ctx.beginPath();
    ctx.moveTo(-0.205 * s, -0.175 * s);
    ctx.bezierCurveTo(-0.155 * s, -0.135 * s, -0.115 * s, -0.060 * s, -0.095 * s, -0.028 * s);
    ctx.lineTo(-0.145 * s, -0.028 * s);
    ctx.bezierCurveTo(-0.185 * s, -0.075 * s, -0.215 * s, -0.125 * s, -0.205 * s, -0.175 * s);
    ctx.closePath();
    ctx.fill();

    // Diagonal Flat Sheen Sweep Across Ingot Boat (Scene 3)
    if (ingotSheen >= 0 && ingotSheen <= 1) {
      const sx = lerp(-0.28 * s, 0.28 * s, ingotSheen);
      ctx.fillStyle = "rgba(255, 250, 230, 0.44)";
      ctx.beginPath();
      ctx.moveTo(sx - 0.025 * s, -0.22 * s);
      ctx.lineTo(sx + 0.025 * s, -0.22 * s);
      ctx.lineTo(sx - 0.045 * s, 0.02 * s);
      ctx.lineTo(sx - 0.095 * s, 0.02 * s);
      ctx.closePath();
      ctx.fill();
    }

    ctx.restore();

    // Crisp Gold Outer Perimeter Stroke on Boat Cradle
    ctx.strokeStyle = "#FFE69E";
    ctx.lineWidth = Math.max(1.5, 0.003 * s);
    traceIngotBoatPath();
    ctx.stroke();

    // 7C. Front Royal-Amethyst & Gold "2027" Cartouche Plaque Centered on Ingot Face
    if (plaqueReveal > 0.01) {
      const pqY = -0.080 * s;
      const pqW = 0.148 * s;
      const pqH = 0.052 * s;

      ctx.save();
      ctx.translate(0, pqY);
      const pqScale = lerp(0.65, 1.0, plaqueReveal);
      ctx.scale(pqScale, pqScale);
      ctx.globalAlpha = ingotVisible * plaqueReveal;

      drawRoundedRectPath(-pqW * 0.5, -pqH * 0.5, pqW, pqH, 0.011 * s);
      ctx.fillStyle = "#FFE69E";
      ctx.fill();

      const pad = 0.005 * s;
      drawRoundedRectPath(-pqW * 0.5 + pad, -pqH * 0.5 + pad, pqW - pad * 2, pqH - pad * 2, 0.007 * s);
      ctx.fillStyle = "#52208C";
      ctx.fill();

      const digits = ["2", "0", "2", "7"];
      const dW = 0.020 * s;
      const dH = 0.027 * s;
      const dGap = 0.009 * s;
      const totalDW = digits.length * dW + (digits.length - 1) * dGap;
      const startX = -totalDW * 0.5;
      const dLineW = Math.max(1.6, 0.0042 * s);
      for (let di = 0; di < digits.length; di++) {
        drawVectorDigit(digits[di], startX + di * (dW + dGap), -dH * 0.5, dW, dH, "#FFF3D1", dLineW);
      }

      ctx.restore();
    }

    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;
  const INV_SQRT2 = 0.7071067811865476;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function drawRoundedRectPath(x, y, w, h, r) {
    const rr = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawDiamond(x, y, rx, ry, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fill();
  }

  function drawBgKnotAccent(x, y, unit, color) {
    // Subtle flat architectural diamond-frame motif in far-outer wine background
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(2, unit * 0.16);
    ctx.lineJoin = "round";
    ctx.beginPath();
    ctx.moveTo(0, -unit);
    ctx.lineTo(unit, 0);
    ctx.lineTo(0, unit);
    ctx.lineTo(-unit, 0);
    ctx.closePath();
    ctx.stroke();

    drawDiamond(0, 0, unit * 0.36, unit * 0.36, color);
    ctx.restore();
  }

  // Build exact continuous single-loop 3x3 Pan Chang (Chinese Endless Lucky Knot) in rotated (u, v) grid
  // Starting from the exact top apex of the top 270-deg ear loop (-1.5, -1.5) so weave radiates symmetrically!
  function uvToXY(u, v, d, knotY) {
    return [(u - v) * d * INV_SQRT2, knotY + (u + v) * d * INV_SQRT2];
  }

  function buildPanChangPolyline(d, knotY) {
    const pts = [];
    function pushUV(u, v) {
      const p = uvToXY(u, v, d, knotY);
      if (pts.length > 0) {
        const prev = pts[pts.length - 1];
        if (Math.hypot(p[0] - prev[0], p[1] - prev[1]) < 0.01) return;
      }
      pts.push(p);
    }
    function addLine(u0, v0, u1, v1, steps) {
      for (let i = 0; i <= steps; i++) {
        const f = i / steps;
        pushUV(lerp(u0, u1, f), lerp(v0, v1, f));
      }
    }
    function addArc(cu, cv, r, a0, a1, steps) {
      for (let i = 0; i <= steps; i++) {
        const a = lerp(a0, a1, i / steps);
        pushUV(cu + Math.cos(a) * r, cv + Math.sin(a) * r);
      }
    }

    // Start at top apex of top ear loop (-1.5, -1.5) at angle -3*PI/4 -> sweep to (-1, -1.5) going +v
    addArc(-1.5, -1.5, 0.5, -Math.PI * 0.75, 0, 14);
    // Down-left strand u = -1, v: -1.5 -> +1.5
    addLine(-1, -1.5, -1, 1.5, 24);
    // Lower-left 180-deg ear loop: (-1, +1.5) -> (0, +1.5), center (-0.5, +1.5)
    addArc(-0.5, 1.5, 0.5, Math.PI, 0, 18);
    // Center strand u = 0, v: +1.5 -> -1.5
    addLine(0, 1.5, 0, -1.5, 24);
    // Upper-right 180-deg ear loop: (0, -1.5) -> (+1, -1.5), center (+0.5, -1.5)
    addArc(0.5, -1.5, 0.5, Math.PI, TAU, 18);
    // Down-right strand u = +1, v: -1.5 -> +1.5
    addLine(1, -1.5, 1, 1.5, 24);
    // Bottom 270-deg ear loop: (+1, +1.5) -> (+1.5, +1), center (+1.5, +1.5)
    addArc(1.5, 1.5, 0.5, Math.PI, -Math.PI * 0.5, 24);
    // Lower-right-to-left strand v = +1, u: +1.5 -> -1.5
    addLine(1.5, 1, -1.5, 1, 24);
    // Left-lower 180-deg ear loop: (-1.5, +1) -> (-1.5, 0), center (-1.5, +0.5)
    addArc(-1.5, 0.5, 0.5, Math.PI * 0.5, Math.PI * 1.5, 18);
    // Center cross strand v = 0, u: -1.5 -> +1.5
    addLine(-1.5, 0, 1.5, 0, 24);
    // Right-upper 180-deg ear loop: (+1.5, 0) -> (+1.5, -1), center (+1.5, -0.5)
    addArc(1.5, -0.5, 0.5, Math.PI * 0.5, -Math.PI * 0.5, 18);
    // Upper-right-to-left strand v = -1, u: +1.5 -> -1.5
    addLine(1.5, -1, -1.5, -1, 24);
    // Return arc completing top 270-deg ear loop: (-1.5, -1) -> apex (-1.5 - 0.3535, -1.5 - 0.3535)
    addArc(-1.5, -1.5, 0.5, Math.PI * 0.5, Math.PI * 1.25, 14);

    // Precompute cumulative arc lengths for exact constant-speed weave & bead glide
    const cumLen = [0];
    let total = 0;
    for (let i = 1; i < pts.length; i++) {
      total += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
      cumLen.push(total);
    }
    return { pts: pts, cumLen: cumLen, total: total };
  }

  function samplePointAtDist(poly, dist) {
    const target = ((dist % poly.total) + poly.total) % poly.total;
    const cl = poly.cumLen;
    let lo = 0;
    let hi = cl.length - 1;
    while (lo < hi - 1) {
      const mid = (lo + hi) >> 1;
      if (cl[mid] <= target) lo = mid;
      else hi = mid;
    }
    const span = cl[hi] - cl[lo];
    const frac = span > 0 ? (target - cl[lo]) / span : 0;
    return [
      lerp(poly.pts[lo][0], poly.pts[hi][0], frac),
      lerp(poly.pts[lo][1], poly.pts[hi][1], frac)
    ];
  }

  function strokePolylineRange(poly, maxDist) {
    if (maxDist <= 0.01) return;
    const pts = poly.pts;
    const cl = poly.cumLen;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) {
      if (cl[i] <= maxDist) {
        ctx.lineTo(pts[i][0], pts[i][1]);
      } else {
        const span = cl[i] - cl[i - 1];
        const frac = span > 0 ? (maxDist - cl[i - 1]) / span : 0;
        ctx.lineTo(lerp(pts[i - 1][0], pts[i][0], frac), lerp(pts[i - 1][1], pts[i][1], frac));
        break;
      }
    }
    ctx.stroke();
  }

  function drawOverCrossingPatch(u, v, overIsU, d, knotY, ribbonW, goldW) {
    // Draws a crisp short flat over-crossing segment with clean dark border gap for authentic weave depth
    const halfSpan = 0.34;
    let p0, p1;
    if (overIsU) {
      p0 = uvToXY(u - halfSpan, v, d, knotY);
      p1 = uvToXY(u + halfSpan, v, d, knotY);
    } else {
      p0 = uvToXY(u, v - halfSpan, d, knotY);
      p1 = uvToXY(u, v + halfSpan, d, knotY);
    }

    ctx.save();
    ctx.lineCap = "butt";

    // Crisp recessed dark-wine gap border separating over-strand cleanly from under-strand
    ctx.strokeStyle = "#16080E";
    ctx.lineWidth = ribbonW + 0.0068 * s;
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    ctx.lineTo(p1[0], p1[1]);
    ctx.stroke();

    // Rich Ruby Carmine Over-Strand Ribbon
    ctx.strokeStyle = "#DE214F";
    ctx.lineWidth = ribbonW;
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    ctx.lineTo(p1[0], p1[1]);
    ctx.stroke();

    // Inner Champagne-Gold Center Thread
    ctx.strokeStyle = "#F4CB6E";
    ctx.lineWidth = goldW;
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    ctx.lineTo(p1[0], p1[1]);
    ctx.stroke();

    ctx.restore();
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const hoverY = Math.sin(loopPhase * 2) * 0.007 * s;

  let weaveAmt = 1;
  let knotScaleX = 1;
  let knotScaleY = 1;
  let beadCapReveal = 1;
  let tasselBloom = 1;
  let tasselAngle = 0;
  let slidingBeadAlpha = 0;
  let slidingBeadOffset = 0;
  let plaqueSheen = -1;

  if (currentScene === 0) {
    // Scene 1: Thick Silk Ribbon Continuous Pan Chang Weave
    weaveAmt = easeInOutCubic(subProgress(sceneProgress, 0.04, 0.86));
    beadCapReveal = easeOutQuart(subProgress(sceneProgress, 0.72, 0.96));
    tasselBloom = 0;
  } else if (currentScene === 1) {
    // Scene 2: Controlled Squash & Stretch Knot Tighten + Silk Tassel Bloom
    weaveAmt = 1;
    beadCapReveal = 1;
    const sqP = subProgress(sceneProgress, 0.0, 0.56);
    const damped = Math.sin(sqP * Math.PI * 2) * (1 - sqP);
    knotScaleX = 1 - 0.055 * damped;
    knotScaleY = 1 + 0.050 * damped;
    tasselBloom = easeOutQuart(subProgress(sceneProgress, 0.34, 0.92));
    if (sceneProgress >= 0.42 && sceneProgress <= 0.76) {
      plaqueSheen = easeInOutCubic(subProgress(sceneProgress, 0.42, 0.76));
    }
  } else if (currentScene === 2) {
    // Scene 3: Luminous Jade Beads Sliding Along Knot Path + Natural Pendulum Tassel Sway
    weaveAmt = 1;
    beadCapReveal = 1;
    tasselBloom = 1;
    const breath = 0.5 - 0.5 * Math.cos(sceneProgress * Math.PI * 4);
    knotScaleX = 1 + 0.015 * breath;
    knotScaleY = 1 + 0.015 * breath;

    const env = Math.sin(sceneProgress * Math.PI);
    tasselAngle = env * Math.sin(sceneProgress * Math.PI * 4) * 0.074;

    const beadIn = easeOutQuart(subProgress(sceneProgress, 0.0, 0.14));
    const beadOut = 1 - easeInOutCubic(subProgress(sceneProgress, 0.84, 1.0));
    slidingBeadAlpha = beadIn * beadOut;
    slidingBeadOffset = sceneProgress; // Completes 1 smooth full lap
  } else {
    // Scene 4: Graceful Tassel Tuck & Silk Weave Unravel back to Exact t=0 Poised Plaque
    tasselBloom = 1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.28));
    beadCapReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.12, 0.36));
    weaveAmt = 1 - easeInOutCubic(subProgress(sceneProgress, 0.22, 0.94));
  }

  // --- LAYER 1: Clean Dark Matte Wine-Charcoal Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#1A0A12");
  bgGrad.addColorStop(0.52, "#12070C");
  bgGrad.addColorStop(1, "#090306");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Diamond-Knot Accents (Strictly Outside Hero Zone) ---
  const halfW = width * 0.5;
  if (halfW > 0.60 * s) {
    const outerX = Math.min(halfW - 0.10 * s, 0.72 * s);
    const driftY = Math.sin(loopPhase) * 0.011 * s;
    drawBgKnotAccent(cx - outerX, cy - 0.24 * s + driftY, 0.044 * s, "#2A121E");
    drawBgKnotAccent(cx - outerX, cy + 0.24 * s - driftY, 0.036 * s, "#331624");
    drawBgKnotAccent(cx + outerX, cy - 0.24 * s - driftY, 0.044 * s, "#2A121E");
    drawBgKnotAccent(cx + outerX, cy + 0.24 * s + driftY, 0.036 * s, "#331624");
  }

  // --- LAYER 3: Hero Icon — Lucky Knot Weave Assembly ---
  const ringCenterY = -0.365 * s;
  const ringR = 0.020 * s;
  const plaqueTopY = -0.332 * s;
  const plaqueW = 0.132 * s;
  const plaqueH = 0.050 * s;
  const plaqueBotY = plaqueTopY + plaqueH; // -0.282 * s
  const knotY = -0.052 * s;
  const gridD = 0.068 * s; // Pan Chang spans +/- 0.178*s vertically around knotY -> -0.230*s to +0.126*s
  const ribbonW = Math.max(4, 0.0165 * s);
  const goldThreadW = Math.max(1.4, 0.0034 * s);

  const knotTopAnchorY = knotY - 2.5 * gridD * INV_SQRT2 - 0.5 * gridD * INV_SQRT2;
  const knotBotAnchorY = knotY + 2.5 * gridD * INV_SQRT2 + 0.5 * gridD * INV_SQRT2;

  ctx.save();
  ctx.translate(cx, cy + hoverY);

  // 3A. Link Cord from Plaque Bottom to Top of Knot (grows cleanly at start of weave)
  const linkAppear = clamp01(weaveAmt * 8);
  if (linkAppear > 0.01) {
    ctx.fillStyle = "#F4CB6E";
    const cordH = (knotTopAnchorY - plaqueBotY + 0.014 * s) * linkAppear;
    drawRoundedRectPath(-0.004 * s, plaqueBotY - 0.002 * s, 0.008 * s, cordH, 0.004 * s);
    ctx.fill();
  }

  // 3B. Always-Present Top Gold Hanging Ring & Sleek "2027" Champagne-Gold Plaque
  ctx.save();
  ctx.strokeStyle = "#F4CB6E";
  ctx.lineWidth = Math.max(2, 0.0072 * s);
  ctx.beginPath();
  ctx.arc(0, ringCenterY, ringR, 0, TAU);
  ctx.stroke();

  ctx.fillStyle = "#D4A13E";
  ctx.beginPath();
  ctx.arc(0, ringCenterY + ringR, 0.0085 * s, 0, TAU);
  ctx.fill();

  // Plaque Outer Gold Capsule Frame
  drawRoundedRectPath(-plaqueW * 0.5, plaqueTopY, plaqueW, plaqueH, 0.010 * s);
  ctx.fillStyle = "#F4CB6E";
  ctx.fill();

  // Plaque Inner Ruby Field
  const pPad = 0.0055 * s;
  drawRoundedRectPath(-plaqueW * 0.5 + pPad, plaqueTopY + pPad, plaqueW - pPad * 2, plaqueH - pPad * 2, 0.006 * s);
  ctx.fillStyle = "#A31234";
  ctx.fill();

  // Custom Crisp Geometric Vector "2027" Numerals Inside Plaque
  const digits = ["2", "0", "2", "7"];
  const dW = 0.018 * s;
  const dH = 0.025 * s;
  const dGap = 0.008 * s;
  const totalDW = digits.length * dW + (digits.length - 1) * dGap;
  const startX = -totalDW * 0.5;
  const dLineW = Math.max(1.5, 0.0038 * s);
  const plaqueMidY = plaqueTopY + plaqueH * 0.5;
  for (let di = 0; di < digits.length; di++) {
    drawVectorDigit(digits[di], startX + di * (dW + dGap), plaqueMidY - dH * 0.5, dW, dH, "#FFF2D4", dLineW);
  }

  // Diagonal Flat Sheen Sweep Clipped Strictly Inside Plaque
  if (plaqueSheen >= 0 && plaqueSheen <= 1) {
    ctx.save();
    drawRoundedRectPath(-plaqueW * 0.5 + pPad, plaqueTopY + pPad, plaqueW - pPad * 2, plaqueH - pPad * 2, 0.006 * s);
    ctx.clip();
    const sx = lerp(-plaqueW * 0.9, plaqueW * 0.9, plaqueSheen);
    ctx.fillStyle = "rgba(255, 242, 212, 0.42)";
    ctx.beginPath();
    ctx.moveTo(sx - 0.014 * s, plaqueTopY);
    ctx.lineTo(sx + 0.012 * s, plaqueTopY);
    ctx.lineTo(sx - 0.012 * s, plaqueBotY);
    ctx.lineTo(sx - 0.038 * s, plaqueBotY);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  // 3C. Woven 3x3 Pan Chang Thick Silk Ribbon Knot
  if (weaveAmt > 0.002) {
    const poly = buildPanChangPolyline(gridD, knotY);
    const activeDist = poly.total * weaveAmt;

    ctx.save();
    ctx.translate(0, knotY);
    ctx.scale(knotScaleX, knotScaleY);
    ctx.translate(0, -knotY);

    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    // Outer subtle dark-ruby edge backing for crisp silhouette definition
    ctx.strokeStyle = "#6E0B24";
    ctx.lineWidth = ribbonW + 0.004 * s;
    strokePolylineRange(poly, activeDist);

    // Main Thick Ruby Carmine Silk Ribbon
    ctx.strokeStyle = "#DE214F";
    ctx.lineWidth = ribbonW;
    strokePolylineRange(poly, activeDist);

    // Inner Champagne-Gold Center Silk Thread
    ctx.strokeStyle = "#F4CB6E";
    ctx.lineWidth = goldThreadW;
    strokePolylineRange(poly, activeDist);

    // Authentic Alternating Over/Under Weave Crossing Patches (appear ONLY after BOTH crossing strands are woven)
    for (let iu = -1; iu <= 1; iu++) {
      for (let iv = -1; iv <= 1; iv++) {
        const cPos = uvToXY(iu, iv, gridD, knotY);
        const tol = gridD * 0.22;
        let secondVisitDist = poly.total;
        let visits = 0;
        let inZone = false;
        for (let pi = 0; pi < poly.pts.length; pi++) {
          const distToC = Math.hypot(poly.pts[pi][0] - cPos[0], poly.pts[pi][1] - cPos[1]);
          if (distToC < tol) {
            if (!inZone) {
              inZone = true;
              visits++;
              if (visits === 2) {
                secondVisitDist = poly.cumLen[pi];
              }
            }
          } else {
            inZone = false;
          }
        }
        const patchP = clamp01((activeDist - (secondVisitDist + gridD * 0.12)) / (gridD * 0.24));
        if (patchP > 0.01) {
          const overIsU = ((iu + iv + 4) % 2) === 0;
          ctx.save();
          ctx.globalAlpha = patchP;
          drawOverCrossingPatch(iu, iv, overIsU, gridD, knotY, ribbonW, goldThreadW);
          ctx.restore();
        }
      }
    }

    // 4 Symmetrically Spaced Luminous Celadon-Jade Beads Gliding Along the Exact Knot Path (Scene 3)
    if (slidingBeadAlpha > 0.01) {
      const beadCount = 4;
      const beadR = 0.0125 * s * slidingBeadAlpha;
      for (let b = 0; b < beadCount; b++) {
        const frac = (slidingBeadOffset + b / beadCount) % 1;
        const pos = samplePointAtDist(poly, frac * poly.total);

        ctx.save();
        ctx.translate(pos[0], pos[1]);
        ctx.globalAlpha = slidingBeadAlpha;

        // Crisp dark ring collar separating jade bead from ruby silk ribbon
        ctx.fillStyle = "#16080E";
        ctx.beginPath();
        ctx.arc(0, 0, beadR + 0.0028 * s, 0, TAU);
        ctx.fill();

        // Luminous Celadon-Jade Bead Sphere
        ctx.fillStyle = "#3CC499";
        ctx.beginPath();
        ctx.arc(0, 0, beadR, 0, TAU);
        ctx.fill();

        // Crisp Flat 2D Highlight Facet
        ctx.fillStyle = "#91F0D2";
        ctx.beginPath();
        ctx.arc(-beadR * 0.28, -beadR * 0.28, beadR * 0.34, 0, TAU);
        ctx.fill();

        ctx.restore();
      }
    }

    ctx.restore();
  }

  // 3D. Lower Celadon-Jade Anchor Bead, Gold Collars & 7-Strand Separated Silk Tassel
  if (beadCapReveal > 0.01) {
    const beadTopY = knotBotAnchorY + 0.014 * s;
    const beadR = 0.020 * s;
    const beadCY = beadTopY + beadR + 0.008 * s;
    const tasselPivotY = beadCY + beadR + 0.010 * s;
    const tasselLen = 0.140 * s;

    ctx.save();
    ctx.globalAlpha = beadCapReveal;

    // Upper Gold Collar Spacer
    ctx.fillStyle = "#F4CB6E";
    drawRoundedRectPath(-0.014 * s * beadCapReveal, beadTopY, 0.028 * s * beadCapReveal, 0.008 * s, 0.003 * s);
    ctx.fill();

    // Central Celadon-Jade Bead
    const curBeadR = beadR * beadCapReveal;
    ctx.fillStyle = "#3CC499";
    ctx.beginPath();
    ctx.arc(0, beadCY, curBeadR, 0, TAU);
    ctx.fill();

    ctx.fillStyle = "#91F0D2";
    ctx.beginPath();
    ctx.arc(-curBeadR * 0.28, beadCY - curBeadR * 0.26, curBeadR * 0.34, 0, TAU);
    ctx.fill();

    // Lower Gold Collar Spacer
    ctx.fillStyle = "#F4CB6E";
    drawRoundedRectPath(-0.014 * s * beadCapReveal, beadCY + curBeadR - 0.002 * s, 0.028 * s * beadCapReveal, 0.008 * s, 0.003 * s);
    ctx.fill();

    // Pendulum Tassel Assembly
    ctx.save();
    ctx.translate(0, tasselPivotY);
    ctx.rotate(tasselAngle);

    // Gold Tassel Bell Cap
    ctx.fillStyle = "#F4CB6E";
    ctx.beginPath();
    ctx.moveTo(-0.018 * s * beadCapReveal, 0);
    ctx.lineTo(0.018 * s * beadCapReveal, 0);
    ctx.lineTo(0.029 * s * beadCapReveal, 0.024 * s * beadCapReveal);
    ctx.lineTo(-0.029 * s * beadCapReveal, 0.024 * s * beadCapReveal);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "#D4A13E";
    ctx.fillRect(-0.029 * s * beadCapReveal, 0.018 * s * beadCapReveal, 0.058 * s * beadCapReveal, 0.006 * s * beadCapReveal);

    // 7 Clearly Separated Vertical Flat Gold & Ruby Silk Strands (Bloom cleanly in Scene 2, Sway in Scene 3)
    if (tasselBloom > 0.01) {
      const strandCount = 7;
      const strandSpacing = 0.0084 * s * lerp(0.55, 1.0, tasselBloom);
      const strandW = 0.0044 * s;
      const maxStrandH = tasselLen - 0.024 * s;

      for (let i = 0; i < strandCount; i++) {
        const idxFromCenter = i - (strandCount - 1) * 0.5;
        const sx = idxFromCenter * strandSpacing;
        const lenFactor = 1 - Math.abs(idxFromCenter) * 0.055;
        const curLen = maxStrandH * lenFactor * tasselBloom;
        const localLag = tasselAngle * 0.28 * (1 + Math.abs(idxFromCenter) * 0.12);

        ctx.save();
        ctx.translate(sx, 0.024 * s);
        ctx.rotate(localLag);
        ctx.fillStyle = i % 2 === 0 ? "#F4CB6E" : "#DE214F";
        drawRoundedRectPath(-strandW * 0.5, 0, strandW, curLen, strandW * 0.5);
        ctx.fill();
        ctx.restore();
      }
    }

    ctx.restore();
    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function mixHex(hexA, hexB, u) {
    u = clamp01(u);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const r = Math.round(lerp((a >> 16) & 255, (b >> 16) & 255, u));
    const g = Math.round(lerp((a >> 8) & 255, (b >> 8) & 255, u));
    const bl = Math.round(lerp(a & 255, b & 255, u));
    return "rgb(" + r + "," + g + "," + bl + ")";
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawOctagonPath(x, y, rx, ry, cut) {
    ctx.beginPath();
    ctx.moveTo(x - rx + cut, y - ry);
    ctx.lineTo(x + rx - cut, y - ry);
    ctx.lineTo(x + rx, y - ry + cut);
    ctx.lineTo(x + rx, y + ry - cut);
    ctx.lineTo(x + rx - cut, y + ry);
    ctx.lineTo(x - rx + cut, y + ry);
    ctx.lineTo(x - rx, y + ry - cut);
    ctx.lineTo(x - rx, y - ry + cut);
    ctx.closePath();
  }

  function drawBgFloralMotif(x, y, r, rot, color) {
    // Subtle flat matte architectural window-flower motif strictly in far-outer background
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.fillStyle = color;
    for (let i = 0; i < 4; i++) {
      ctx.save();
      ctx.rotate(i * Math.PI * 0.5);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(r * 0.42, -r * 0.42, 0, -r);
      ctx.quadraticCurveTo(-r * 0.42, -r * 0.42, 0, 0);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.fillStyle = "#051317";
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.24, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  function addQuarterCutoutSubpaths(qSize, cut1, cut2, cut3, cut4) {
    // Quadrant sits in [0..qSize, 0..qSize] where (0,0) is the center of the full mandala
    // and (qSize, qSize) is the outer corner of the paper square.
    // All cutouts are mathematically disjoint with crisp paper bridges between them.

    // Cut 1: Outer corner scalloped notch & twin edge petal notches
    if (cut1 > 0.005) {
      const nr = qSize * 0.24 * cut1;
      ctx.moveTo(qSize, qSize - nr);
      ctx.arc(qSize, qSize, nr, -Math.PI * 0.5, Math.PI, true);
      ctx.lineTo(qSize, qSize);
      ctx.closePath();

      // Symmetrical outer edge semicircular scallops along X and Y outer borders
      const sr = qSize * 0.14 * cut1;
      ctx.moveTo(qSize, qSize * 0.36 - sr);
      ctx.arc(qSize, qSize * 0.36, sr, -Math.PI * 0.5, Math.PI * 0.5, true);
      ctx.closePath();

      ctx.moveTo(qSize * 0.36 + sr, qSize);
      ctx.arc(qSize * 0.36, qSize, sr, 0, Math.PI, true);
      ctx.closePath();
    }

    // Cut 2: Diagonal auspicious leaf / teardrop cutout pair (cleanly inside outer quadrant)
    if (cut2 > 0.005) {
      const k = cut2;
      // Diagonal outer petal hole centered near (0.64, 0.64)
      const cx2 = qSize * 0.64;
      const cy2 = qSize * 0.64;
      const rad = qSize * 0.14 * k;
      ctx.moveTo(cx2 - rad, cy2 - rad);
      ctx.quadraticCurveTo(cx2 + rad * 0.55, cy2 - rad * 1.15, cx2 + rad, cy2 + rad);
      ctx.quadraticCurveTo(cx2 - rad * 1.15, cy2 + rad * 0.55, cx2 - rad, cy2 - rad);
      ctx.closePath();

      // Flanking symmetrical almond cutouts near (0.76, 0.22) and (0.22, 0.76)
      const ax = qSize * 0.74;
      const ay = qSize * 0.21;
      const rx = qSize * 0.085 * k;
      const ry = qSize * 0.052 * k;
      ctx.moveTo(ax - rx, ay);
      ctx.quadraticCurveTo(ax, ay - ry * 1.5, ax + rx, ay);
      ctx.quadraticCurveTo(ax, ay + ry * 1.5, ax - rx, ay);
      ctx.closePath();

      ctx.moveTo(ay, ax - rx);
      ctx.quadraticCurveTo(ay - ry * 1.5, ax, ay, ax + rx);
      ctx.quadraticCurveTo(ay + ry * 1.5, ax, ay, ax - rx);
      ctx.closePath();
    }

    // Cut 3: Mid geometric diamond lattice holes near (0.44, 0.44), (0.48, 0.14), (0.14, 0.48)
    if (cut3 > 0.005) {
      const d1 = qSize * 0.082 * cut3;
      const mx = qSize * 0.43;
      const my = qSize * 0.43;
      ctx.moveTo(mx, my - d1);
      ctx.lineTo(mx + d1, my);
      ctx.lineTo(mx, my + d1);
      ctx.lineTo(mx - d1, my);
      ctx.closePath();

      const d2 = qSize * 0.056 * cut3;
      const ex = qSize * 0.48;
      const ey = qSize * 0.14;
      ctx.moveTo(ex, ey - d2);
      ctx.lineTo(ex + d2 * 1.25, ey);
      ctx.lineTo(ex, ey + d2);
      ctx.lineTo(ex - d2 * 1.25, ey);
      ctx.closePath();

      ctx.moveTo(ey, ex - d2 * 1.25);
      ctx.lineTo(ey + d2, ex);
      ctx.lineTo(ey, ex + d2 * 1.25);
      ctx.lineTo(ey - d2, ex);
      ctx.closePath();
    }

    // Cut 4: Inner floral arch cutout around center origin (0,0) creating center mandala ring
    if (cut4 > 0.005) {
      const ir = qSize * 0.22 * cut4;
      ctx.moveTo(0, 0);
      ctx.lineTo(ir, 0);
      ctx.arc(0, 0, ir, 0, Math.PI * 0.5, false);
      ctx.closePath();
    }
  }

  function drawQuarterPaperSheet(qSize, fillColor, highlightColor, cut1, cut2, cut3, cut4, cornerRoundAmt) {
    // Draws one [0..qSize, 0..qSize] quadrant of the vermilion paper-cut sheet with authentic evenodd cutouts.
    ctx.save();
    ctx.beginPath();

    // Outer quadrant perimeter: square when cornerRoundAmt=0, gracefully scalloped lotus petal when =1
    const rOuter = qSize * 0.18 * cornerRoundAmt;
    ctx.moveTo(0, 0);
    ctx.lineTo(qSize - rOuter, 0);
    ctx.quadraticCurveTo(qSize, 0, qSize, rOuter);
    ctx.lineTo(qSize, qSize - rOuter);
    ctx.quadraticCurveTo(qSize, qSize, qSize - rOuter, qSize);
    ctx.lineTo(0, qSize);
    ctx.closePath();

    addQuarterCutoutSubpaths(qSize, cut1, cut2, cut3, cut4);

    ctx.fillStyle = fillColor;
    ctx.fill("evenodd");

    // Subtle crisp inner flat trim edge along the outer sheet edge (gives rich layered paper depth)
    if (highlightColor) {
      ctx.save();
      ctx.clip("evenodd");
      ctx.fillStyle = highlightColor;
      ctx.fillRect(0, 0, qSize, qSize * 0.032);
      ctx.fillRect(0, 0, qSize * 0.032, qSize);
      ctx.restore();
    }

    ctx.restore();
  }

  function drawOuterTealMandalaCrown(innerClearR, outerTipR, revealAmt, rotAngle) {
    if (revealAmt <= 0.005) return;
    const petalCount = 8;
    const step = TAU / petalCount;
    const rBase = lerp(innerClearR * 0.94, innerClearR, revealAmt);
    const rTip = lerp(innerClearR * 1.02, outerTipR, revealAmt);
    const petalSpan = (outerTipR - innerClearR);

    ctx.save();
    ctx.rotate(rotAngle);
    ctx.globalAlpha = revealAmt;

    for (let i = 0; i < petalCount; i++) {
      ctx.save();
      ctx.rotate(i * step + step * 0.5);

      // Outer Ceramic Teal Lotus Crown Petal (strictly outside max diagonal radius of vermilion mandala)
      ctx.beginPath();
      ctx.moveTo(-petalSpan * 0.42, -rBase);
      ctx.quadraticCurveTo(-petalSpan * 0.48, -(rBase + rTip) * 0.50, 0, -rTip);
      ctx.quadraticCurveTo(petalSpan * 0.48, -(rBase + rTip) * 0.50, petalSpan * 0.42, -rBase);
      ctx.closePath();

      // Inner cutout diamond inside each teal petal
      const midY = -(rBase * 0.46 + rTip * 0.54);
      const dw = petalSpan * 0.14;
      const dh = petalSpan * 0.21;
      ctx.moveTo(0, midY - dh);
      ctx.lineTo(-dw, midY);
      ctx.lineTo(0, midY + dh);
      ctx.lineTo(dw, midY);
      ctx.closePath();

      ctx.fillStyle = i % 2 === 0 ? "#26B8B8" : "#1E9C9C";
      ctx.fill("evenodd");

      // Small parchment-gold pearl accent floating cleanly just past each teal petal tip
      const dotR = 0.0062 * s * revealAmt;
      ctx.fillStyle = "#FCE2A6";
      ctx.beginPath();
      ctx.arc(0, -rTip - 0.014 * s, dotR, 0, TAU);
      ctx.fill();

      ctx.restore();
    }
    ctx.restore();
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const hoverY = Math.sin(loopPhase * 2) * 0.006 * s;

  // Origami fold states: 0 = fully flat open, 1 = fully folded into quarter packet
  let foldH = 0; // folds Left half onto Right half
  let foldV = 0; // folds Top half onto Bottom half
  let cut1 = 0;
  let cut2 = 0;
  let cut3 = 0;
  let cut4 = 0;
  let scrapP1 = -1;
  let scrapP2 = -1;
  let scrapP3 = -1;
  let cornerRound = 0;
  let crownReveal = 0;
  let crownRot = 0;
  let mandalaRot = 0;
  let centerPlaqueReveal = 0;
  let plaqueSheen = -1;
  let creaseAlpha = 0.24;

  if (currentScene === 0) {
    // Scene 1: 2D Origami Paper Fold (Horizontal -> Vertical into centered quarter-square packet)
    foldH = easeInOutQuint(subProgress(sceneProgress, 0.08, 0.48));
    foldV = easeInOutQuint(subProgress(sceneProgress, 0.52, 0.92));
    creaseAlpha = lerp(0.24, 0.0, subProgress(sceneProgress, 0.04, 0.18));
  } else if (currentScene === 1) {
    // Scene 2: Staggered Geometric Paper-Cut Perforations on Folded Packet
    foldH = 1;
    foldV = 1;
    creaseAlpha = 0;
    cut1 = easeOutQuart(subProgress(sceneProgress, 0.06, 0.28));
    cut2 = easeOutQuart(subProgress(sceneProgress, 0.26, 0.50));
    cut3 = easeOutQuart(subProgress(sceneProgress, 0.48, 0.72));
    cut4 = easeOutQuart(subProgress(sceneProgress, 0.70, 0.94));
    scrapP1 = subProgress(sceneProgress, 0.08, 0.44);
    scrapP2 = subProgress(sceneProgress, 0.28, 0.64);
    scrapP3 = subProgress(sceneProgress, 0.50, 0.86);
  } else if (currentScene === 2) {
    // Scene 3: Kaleidoscopic Unfold + Counter-Rotating Layered Mandala & "2027" Core
    cut1 = 1;
    cut2 = 1;
    cut3 = 1;
    cut4 = 1;
    creaseAlpha = 0;
    foldV = 1 - easeInOutQuint(subProgress(sceneProgress, 0.00, 0.24));
    foldH = 1 - easeInOutQuint(subProgress(sceneProgress, 0.20, 0.44));
    cornerRound = easeOutQuart(subProgress(sceneProgress, 0.36, 0.58));
    crownReveal = easeOutQuart(subProgress(sceneProgress, 0.44, 0.72));
    centerPlaqueReveal = easeOutQuart(subProgress(sceneProgress, 0.50, 0.78));

    const spinPhase = subProgress(sceneProgress, 0.48, 1.0);
    const spinCurve = Math.sin(spinPhase * Math.PI);
    crownRot = spinCurve * (Math.PI / 8);    // +22.5 deg clockwise and smoothly back to 0
    mandalaRot = -spinCurve * (Math.PI / 16); // -11.25 deg counter-clockwise and smoothly back to 0

    if (sceneProgress >= 0.66 && sceneProgress <= 0.94) {
      plaqueSheen = easeInOutCubic(subProgress(sceneProgress, 0.66, 0.94));
    }
  } else {
    // Scene 4: Graceful Layer Retraction, Cutout Seal & Seamless Return to Uncut Vermilion Square
    foldH = 0;
    foldV = 0;
    crownReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.00, 0.26));
    centerPlaqueReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.04, 0.28));
    cornerRound = 1 - easeInOutCubic(subProgress(sceneProgress, 0.24, 0.54));

    cut4 = 1 - easeInOutCubic(subProgress(sceneProgress, 0.28, 0.52));
    cut3 = 1 - easeInOutCubic(subProgress(sceneProgress, 0.42, 0.66));
    cut2 = 1 - easeInOutCubic(subProgress(sceneProgress, 0.56, 0.80));
    cut1 = 1 - easeInOutCubic(subProgress(sceneProgress, 0.70, 0.94));
    creaseAlpha = lerp(0.0, 0.24, easeInOutCubic(subProgress(sceneProgress, 0.76, 0.98)));
  }

  // --- LAYER 1: Clean Dark Matte Slate-Teal Obsidian Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#071A1F");
  bgGrad.addColorStop(0.52, "#051317");
  bgGrad.addColorStop(1, "#020A0D");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Floral Silhouettes (Strictly Outside Mandala Zone) ---
  const halfW = width * 0.5;
  if (halfW > 0.62 * s) {
    const outerX = Math.min(halfW - 0.10 * s, 0.73 * s);
    const rotSlow = Math.sin(loopPhase) * 0.22;
    drawBgFloralMotif(cx - outerX, cy - 0.25 * s, 0.056 * s, rotSlow, "#0C2930");
    drawBgFloralMotif(cx - outerX, cy + 0.25 * s, 0.046 * s, -rotSlow, "#10353E");
    drawBgFloralMotif(cx + outerX, cy - 0.25 * s, 0.056 * s, -rotSlow, "#0C2930");
    drawBgFloralMotif(cx + outerX, cy + 0.25 * s, 0.046 * s, rotSlow, "#10353E");
  }

  // --- LAYER 3: Hero Icon — Chuanghua Paper-Cut Window Flower ---
  const qSize = 0.198 * s; // Unfolded square = 0.396*s x 0.396*s; max notched corner radius <= 0.245*s
  // Smoothly keep folded packet centered on (cx, cy) as it folds into quadrant [+x, +y]
  const centerShiftX = -qSize * 0.5 * foldH;
  const centerShiftY = -qSize * 0.5 * foldV;

  ctx.save();
  ctx.translate(cx + centerShiftX, cy + hoverY + centerShiftY);

  // 3A. Outer Counter-Rotating Ceramic Teal Mandala Crown (Strictly Clear of Rotating Vermilion Corners)
  if (crownReveal > 0.005) {
    drawOuterTealMandalaCrown(0.278 * s, 0.352 * s, crownReveal, crownRot);
  }

  // 3B. Main Vermilion Paper-Cut Sheet & Precision 2D Origami Folding/Unfolding
  ctx.save();
  ctx.rotate(mandalaRot);

  const frontCol = "#E6392E";
  const frontHi = "#F55C4C";
  const backCol = "#BD251C";

  // Helper to draw a vertical column (top + bottom quadrants) with vertical foldV
  function drawVerticalColumn(isLeftSide) {
    ctx.save();
    if (isLeftSide) ctx.scale(-1, 1);

    // Bottom quadrant (+y) is the stationary anchor during foldV
    drawQuarterPaperSheet(qSize, frontCol, frontHi, cut1, cut2, cut3, cut4, cornerRound);

    // Top quadrant (-y) hinges cleanly along y = 0 from scaleY = -1 (open top) -> 0 -> +1 (folded onto bottom)
    if (foldV < 0.999) {
      const cosV = Math.cos(foldV * Math.PI); // +1 open, -1 folded onto bottom
      const absV = Math.abs(cosV);
      if (absV > 0.004) {
        ctx.save();
        if (cosV >= 0) {
          // Still on top half (-y), showing front face
          ctx.scale(1, -absV);
          const tone = mixHex("#B8241B", frontCol, absV);
          drawQuarterPaperSheet(qSize, tone, frontHi, cut1, cut2, cut3, cut4, cornerRound);
        } else {
          // Folded past 90 deg onto bottom half (+y), showing darker back paper face
          ctx.scale(1, absV);
          const tone = mixHex("#9C1B14", backCol, absV);
          drawQuarterPaperSheet(qSize, tone, null, cut1, cut2, cut3, cut4, cornerRound);
        }
        ctx.restore();
      }
    }
    ctx.restore();
  }

  // Right half (+x) is stationary anchor during foldH
  drawVerticalColumn(false);

  // Left half (-x) hinges cleanly along x = 0 from open (-x) onto right half (+x)
  if (foldH < 0.999) {
    const cosH = Math.cos(foldH * Math.PI); // +1 open left, -1 folded onto right
    const absH = Math.abs(cosH);
    if (absH > 0.004) {
      ctx.save();
      if (cosH >= 0) {
        // Still on left side (-x)
        ctx.scale(absH, 1);
        drawVerticalColumn(true);
      } else {
        // Folded past 90 deg onto right side (+x), showing back paper face
        ctx.scale(-absH, 1);
        // Draw back-toned version cleanly folded over right side
        ctx.save();
        const tone = mixHex("#9C1B14", backCol, absH);
        drawQuarterPaperSheet(qSize, tone, null, cut1, cut2, cut3, cut4, cornerRound);
        if (foldV < 0.999) {
          ctx.scale(1, -1);
          drawQuarterPaperSheet(qSize, tone, null, cut1, cut2, cut3, cut4, cornerRound);
        }
        ctx.restore();
      }
      ctx.restore();
    }
  }

  // Subtle Crisp Parchment-Gold Crease Guidelines on Uncut Square Sheet (Scene 1 Start & Scene 4 End)
  if (creaseAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha = creaseAlpha;
    ctx.strokeStyle = "#FCE2A6";
    ctx.lineWidth = Math.max(1.2, 0.0022 * s);
    ctx.setLineDash([0.012 * s, 0.010 * s]);
    ctx.beginPath();
    ctx.moveTo(-qSize * 0.90, 0);
    ctx.lineTo(qSize * 0.90, 0);
    ctx.moveTo(0, -qSize * 0.90);
    ctx.lineTo(0, qSize * 0.90);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }

  // Crisp Disappearing Paper-Cut Scraps Sliding Cleanly Outward from Folded Packet (Scene 2 Only)
  const scraps = [
    { p: scrapP1, sx: qSize * 1.06, sy: qSize * 1.06, dx: 0.055 * s, dy: 0.055 * s, r: 0.022 * s },
    { p: scrapP2, sx: qSize * 1.06, sy: qSize * 0.36, dx: 0.062 * s, dy: -0.015 * s, r: 0.016 * s },
    { p: scrapP3, sx: qSize * 0.36, sy: qSize * 1.06, dx: -0.015 * s, dy: 0.062 * s, r: 0.016 * s }
  ];
  for (let i = 0; i < scraps.length; i++) {
    const sc = scraps[i];
    if (sc.p > 0.01 && sc.p < 0.99) {
      const ep = easeOutQuart(sc.p);
      const scAlpha = 1 - sc.p;
      const scSize = sc.r * (1 - sc.p * 0.6);
      ctx.save();
      ctx.translate(sc.sx + sc.dx * ep, sc.sy + sc.dy * ep);
      ctx.rotate(ep * 0.9);
      ctx.globalAlpha = scAlpha;
      ctx.fillStyle = "#E6392E";
      ctx.beginPath();
      ctx.moveTo(0, -scSize);
      ctx.lineTo(scSize * 0.85, 0);
      ctx.lineTo(0, scSize);
      ctx.lineTo(-scSize * 0.85, 0);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  }

  ctx.restore();

  // 3C. Central Parchment-Gold Octagonal Core & "2027" Numerals (Cleanly Centered inside Cut-4 Mandala Ring)
  if (centerPlaqueReveal > 0.01) {
    ctx.save();
    const pScale = lerp(0.55, 1.0, centerPlaqueReveal);
    ctx.scale(pScale, pScale);
    ctx.globalAlpha = centerPlaqueReveal;

    const pR = qSize * 0.44;
    const pCut = pR * 0.32;

    // Outer Parchment-Gold Octagon
    drawOctagonPath(0, 0, pR, pR * 0.78, pCut);
    ctx.fillStyle = "#FCE2A6";
    ctx.fill();

    // Inner Deep Slate-Teal Field (Echoing paper-cut contrast cleanly)
    drawOctagonPath(0, 0, pR - 0.008 * s, pR * 0.78 - 0.008 * s, pCut * 0.82);
    ctx.fillStyle = "#082229";
    ctx.fill();

    // Inner Ceramic Teal Hairline Frame
    drawOctagonPath(0, 0, pR - 0.015 * s, pR * 0.78 - 0.015 * s, pCut * 0.70);
    ctx.strokeStyle = "#26B8B8";
    ctx.lineWidth = Math.max(1.2, 0.0024 * s);
    ctx.stroke();

    // Crisp Custom Geometric Vector "2027" Numerals in Warm Parchment Gold
    const digits = ["2", "0", "2", "7"];
    const dW = 0.022 * s;
    const dH = 0.032 * s;
    const dGap = 0.009 * s;
    const totalDW = digits.length * dW + (digits.length - 1) * dGap;
    const startX = -totalDW * 0.5;
    const dLineW = Math.max(1.6, 0.0044 * s);
    for (let di = 0; di < digits.length; di++) {
      drawVectorDigit(digits[di], startX + di * (dW + dGap), -dH * 0.5, dW, dH, "#FCE2A6", dLineW);
    }

    // Symmetrical Teal Micro-Diamond Accents Top & Bottom inside Plaque
    ctx.fillStyle = "#52D9D9";
    const md = 0.0045 * s;
    ctx.beginPath();
    ctx.moveTo(0, -pR * 0.50 - md);
    ctx.lineTo(md, -pR * 0.50);
    ctx.lineTo(0, -pR * 0.50 + md);
    ctx.lineTo(-md, -pR * 0.50);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, pR * 0.50 - md);
    ctx.lineTo(md, pR * 0.50);
    ctx.lineTo(0, pR * 0.50 + md);
    ctx.lineTo(-md, pR * 0.50);
    ctx.closePath();
    ctx.fill();

    // Clean Diagonal Sheen Sweep Clipped Strictly Inside Center Octagon
    if (plaqueSheen >= 0 && plaqueSheen <= 1) {
      ctx.save();
      drawOctagonPath(0, 0, pR - 0.008 * s, pR * 0.78 - 0.008 * s, pCut * 0.82);
      ctx.clip();
      const sx = lerp(-pR * 1.8, pR * 1.8, plaqueSheen);
      ctx.fillStyle = "rgba(252, 226, 166, 0.32)";
      ctx.beginPath();
      ctx.moveTo(sx - 0.018 * s, -pR);
      ctx.lineTo(sx + 0.014 * s, -pR);
      ctx.lineTo(sx - 0.018 * s, pR);
      ctx.lineTo(sx - 0.050 * s, pR);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function drawRoundedRectPath(x, y, w, h, r) {
    const rr = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawDiamond(x, y, rx, ry, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fill();
  }

  function drawStarPolygon(x, y, points, rOut, rIn, rot, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.fillStyle = color;
    ctx.beginPath();
    const total = points * 2;
    for (let i = 0; i < total; i++) {
      const a = (i * Math.PI) / points;
      const r = i % 2 === 0 ? rOut : rIn;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawBgOctaStar(x, y, r, color) {
    ctx.save();
    ctx.translate(x, y);
    drawStarPolygon(0, 0, 4, r, r * 0.42, 0, color);
    drawDiamond(0, 0, r * 0.28, r * 0.28, "#0D081B");
    ctx.restore();
  }

  function drawFirecrackerTube(attachX, attachY, side, angle, scaleAmt, isMagenta) {
    if (scaleAmt <= 0.01) return;
    const len = 0.092 * s;
    const h = 0.030 * s;
    const capW = 0.014 * s;
    const bodyCol = isMagenta ? "#E82E7B" : "#FF6B2B";
    const hiCol = isMagenta ? "#FF73AD" : "#FFA06B";
    const shCol = isMagenta ? "#AD1857" : "#CC4614";

    ctx.save();
    ctx.translate(attachX, attachY);
    ctx.rotate(side * angle);
    ctx.scale(side * scaleAmt, scaleAmt);

    // Small gold cord link connecting tube cleanly to spine
    ctx.fillStyle = "#FFD15C";
    ctx.fillRect(0, -0.003 * s, 0.014 * s, 0.006 * s);

    const x0 = 0.012 * s;
    const y0 = -h * 0.5;

    // Tube Base Body
    ctx.save();
    drawRoundedRectPath(x0, y0, len, h, h * 0.24);
    ctx.clip();

    ctx.fillStyle = bodyCol;
    ctx.fillRect(x0, y0, len, h);

    // Clean 2D Flat Top Highlight & Bottom Shadow Bands
    ctx.fillStyle = hiCol;
    ctx.fillRect(x0, y0, len, h * 0.24);

    ctx.fillStyle = shCol;
    ctx.fillRect(x0, y0 + h * 0.76, len, h * 0.24);

    // Gold End Cap Bands
    ctx.fillStyle = "#FFD15C";
    ctx.fillRect(x0, y0, capW, h);
    ctx.fillRect(x0 + len - capW, y0, capW, h);

    // Crisp Gold Center Accent Ring
    ctx.fillStyle = "#FFE699";
    ctx.fillRect(x0 + len * 0.47, y0, len * 0.06, h);

    ctx.restore();
    ctx.restore();
  }

  function drawGeometricFireworkBurst(bx, by, maxR, localP, palette) {
    if (localP <= 0.002 || localP >= 0.998) return;

    ctx.save();
    ctx.translate(bx, by);

    // Phase A: Crisp Tapered Geometric Starburst Rays & Outer Diamonds (0.0 -> 0.78)
    const burstP = subProgress(localP, 0.0, 0.78);
    if (burstP > 0 && burstP < 1) {
      const expand = easeOutQuart(burstP);
      const fade = burstP < 0.62 ? 1 : 1 - easeInOutCubic(subProgress(burstP, 0.62, 1.0));
      const rayCount = 8;
      const innerR = lerp(maxR * 0.14, maxR * 0.62, easeInOutCubic(burstP));
      const outerR = lerp(maxR * 0.32, maxR * 1.0, expand);
      const rayHalfW = lerp(maxR * 0.135, maxR * 0.048, burstP);

      ctx.save();
      ctx.globalAlpha = fade;

      // Central crisp geometric star flash (early burst 0.0 -> 0.42)
      const coreP = subProgress(burstP, 0.0, 0.42);
      if (coreP < 1) {
        const coreR = lerp(maxR * 0.38, 0, easeOutQuart(coreP));
        drawStarPolygon(0, 0, 8, coreR, coreR * 0.48, coreP * 0.45, "#FFF4D6");
      }

      // 8 Symmetrical Bold Tapered Solid Flat Vector Rays
      for (let i = 0; i < rayCount; i++) {
        const ang = (i * TAU) / rayCount;
        const col = palette[i % palette.length];
        ctx.save();
        ctx.rotate(ang);
        ctx.fillStyle = col;
        ctx.beginPath();
        ctx.moveTo(innerR, -rayHalfW * 0.55);
        ctx.lineTo(outerR, 0);
        ctx.lineTo(innerR, rayHalfW * 0.55);
        ctx.lineTo(innerR - rayHalfW * 0.72, 0);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }

      // 8 Alternating Bold Outer Flat Diamonds strictly at Mid-Angles (Zero Ray Overlap)
      const diaDist = lerp(maxR * 0.28, maxR * 0.94, expand);
      const diaSize = lerp(maxR * 0.125, maxR * 0.055, burstP);
      for (let i = 0; i < rayCount; i++) {
        const ang = ((i + 0.5) * TAU) / rayCount;
        const dx = Math.cos(ang) * diaDist;
        const dy = Math.sin(ang) * diaDist;
        ctx.save();
        ctx.translate(dx, dy);
        ctx.rotate(ang);
        drawDiamond(0, 0, diaSize * 1.28, diaSize * 0.78, palette[(i + 1) % palette.length]);
        ctx.restore();
      }

      ctx.restore();
    }

    // Phase B: Minimalist Clean Flat Smoke Puffs Shrinking Smoothly to 0 (0.48 -> 1.0)
    const smokeP = subProgress(localP, 0.48, 1.0);
    if (smokeP > 0 && smokeP < 1) {
      const smokeEnv = Math.sin(smokeP * Math.PI);
      const puffDist = lerp(maxR * 0.14, maxR * 0.34, easeOutQuart(smokeP));
      const puffR = maxR * 0.14 * smokeEnv;
      ctx.save();
      ctx.globalAlpha = 0.72 * smokeEnv;
      ctx.fillStyle = "#261945";
      for (let k = 0; k < 3; k++) {
        const ang = (k * TAU) / 3 - Math.PI * 0.5;
        ctx.beginPath();
        ctx.arc(Math.cos(ang) * puffDist, Math.sin(ang) * puffDist, puffR, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }

    ctx.restore();
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const hoverY = Math.sin(loopPhase * 2) * 0.006 * s;

  const pairCount = 5;
  // Pair pop trigger times (in seconds of loopT, bottom pair 4 -> top pair 0 during Scene 3: 10s..15s)
  const burstStartTimes = [13.5, 12.7, 11.9, 11.1, 10.3];
  const burstDuration = 3.8;

  // Strictly disjoint symmetrical starburst positions (Left & Right mirrored, zero pairwise overlap)
  const burstSpecs = [
    { xDist: 0.35, yOff: -0.24, maxR: 0.088, pal: ["#FFD15C", "#FF6B2B", "#E82E7B"] }, // Pair 0 (top)
    { xDist: 0.58, yOff: -0.13, maxR: 0.094, pal: ["#E82E7B", "#FFD15C", "#FFA06B"] }, // Pair 1
    { xDist: 0.37, yOff: 0.00,  maxR: 0.090, pal: ["#FF6B2B", "#FFD15C", "#E82E7B"] }, // Pair 2
    { xDist: 0.57, yOff: 0.13,  maxR: 0.094, pal: ["#FFD15C", "#E82E7B", "#FF6B2B"] }, // Pair 3
    { xDist: 0.35, yOff: 0.25,  maxR: 0.088, pal: ["#E82E7B", "#FF6B2B", "#FFD15C"] }  // Pair 4 (bottom)
  ];

  let spineExtend = 1; // 0 = retracted behind header, 1 = fully extended
  let chainSway = 0;
  let fuseBurnAmt = 0; // 0 = full fuse, 1 = burned to bottom pair
  let sparkActive = 0;
  let plaquePulse = 0;
  let plaqueSheen = -1;

  if (currentScene === 0) {
    // Scene 1: Graceful Chain Cascade Descent & Natural Damped Sway
    spineExtend = easeOutQuart(subProgress(sceneProgress, 0.0, 0.62));
    chainSway = Math.sin(sceneProgress * Math.PI * 2) * (1 - sceneProgress) * 0.062;
    fuseBurnAmt = 0;
    sparkActive = 0;
  } else if (currentScene === 1) {
    // Scene 2: Geometric Spark Ignites & Travels Smoothly Up the Fuse
    spineExtend = 1;
    chainSway = 0;
    sparkActive = easeOutQuart(subProgress(sceneProgress, 0.0, 0.14));
    fuseBurnAmt = easeInOutCubic(subProgress(sceneProgress, 0.10, 0.96));
  } else if (currentScene === 2) {
    // Scene 3: Sequential Pair-by-Pair Geometric Starbursts (Bottom -> Top)
    spineExtend = 1;
    chainSway = 0;
    fuseBurnAmt = 1;
    sparkActive = 0;
    plaquePulse = Math.sin(subProgress(sceneProgress, 0.55, 0.95) * Math.PI);
    if (sceneProgress >= 0.58 && sceneProgress <= 0.92) {
      plaqueSheen = easeInOutCubic(subProgress(sceneProgress, 0.58, 0.92));
    }
  } else {
    // Scene 4: Final Smoke Puffs Clear, Ceremonial Plaque Glint & Seamless Reset to t=0
    fuseBurnAmt = 1;
    sparkActive = 0;
    chainSway = 0;
    spineExtend = 0;
    plaquePulse = Math.sin(subProgress(sceneProgress, 0.35, 0.85) * Math.PI) * 0.45;
    if (sceneProgress >= 0.42 && sceneProgress <= 0.82) {
      plaqueSheen = easeInOutCubic(subProgress(sceneProgress, 0.42, 0.82));
    }
  }

  // --- LAYER 1: Clean Dark Matte Indigo-Violet Obsidian Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#120B24");
  bgGrad.addColorStop(0.52, "#0C071A");
  bgGrad.addColorStop(1, "#06030F");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Star Medallions (Strictly Outside All Starburst Zones) ---
  const halfW = width * 0.5;
  if (halfW > 0.72 * s) {
    const outerX = Math.min(halfW - 0.08 * s, 0.78 * s);
    const drift = Math.sin(loopPhase) * 0.010 * s;
    drawBgOctaStar(cx - outerX, cy - 0.31 * s + drift, 0.032 * s, "#1C1236");
    drawBgOctaStar(cx - outerX, cy + 0.31 * s - drift, 0.026 * s, "#221640");
    drawBgOctaStar(cx + outerX, cy - 0.31 * s - drift, 0.032 * s, "#1C1236");
    drawBgOctaStar(cx + outerX, cy + 0.31 * s + drift, 0.026 * s, "#221640");
  }

  // --- LAYER 3: Symmetrical Strictly Non-Overlapping Geometric Firework Bursts (Scene 3 & Early Scene 4) ---
  if (halfW > 0.42 * s) {
    for (let k = 0; k < pairCount; k++) {
      const startT = burstStartTimes[k];
      if (loopT >= startT && loopT <= startT + burstDuration) {
        const localP = (loopT - startT) / burstDuration;
        const spec = burstSpecs[k];
        const bxDist = Math.min(halfW - spec.maxR - 0.03 * s, spec.xDist * s);
        const by = cy + spec.yOff * s;
        drawGeometricFireworkBurst(cx - bxDist, by, spec.maxR * s, localP, spec.pal);
        drawGeometricFireworkBurst(cx + bxDist, by, spec.maxR * s, localP, spec.pal);
      }
    }
  }

  // --- LAYER 4: Hero Icon — Structured Firecracker Chain & Top "2027" Diamond Header ---
  const headerCenterY = -0.278 * s;
  const ringCenterY = -0.365 * s;
  const ringR = 0.021 * s;
  const spineTopY = -0.212 * s;
  const spineFullBotY = 0.246 * s;
  const fuseBotY = 0.365 * s;
  const pairYOffsets = [-0.140 * s, -0.050 * s, 0.040 * s, 0.130 * s, 0.220 * s];

  ctx.save();
  ctx.translate(cx, cy + hoverY);

  // 4A. Hanging Spine, 5 Symmetrical Pairs of Firecrackers & Fuse (Pivoting cleanly from bottom of header plaque)
  if (spineExtend > 0.005) {
    ctx.save();
    ctx.translate(0, spineTopY);
    ctx.rotate(chainSway);
    ctx.translate(0, -spineTopY);

    // Determine visible spine length (always reaches lowest unpopped firecracker pair; retracts cleanly after top pair pops)
    let activeSpineBotY = lerp(spineTopY, spineFullBotY, spineExtend);
    if (currentScene === 2) {
      let targetBotY = spineTopY;
      for (let k = pairCount - 1; k >= 0; k--) {
        const popT = burstStartTimes[k];
        if (loopT < popT) {
          targetBotY = pairYOffsets[k] + 0.012 * s;
          break;
        } else if (loopT < popT + 0.28) {
          const prevY = pairYOffsets[k] + 0.012 * s;
          const nextY = k > 0 ? pairYOffsets[k - 1] + 0.012 * s : spineTopY;
          targetBotY = lerp(prevY, nextY, easeInOutCubic((loopT - popT) / 0.28));
          break;
        }
      }
      activeSpineBotY = targetBotY;
    } else if (currentScene === 3) {
      activeSpineBotY = spineTopY;
    }

    // Central Braided Gold Spine Cord
    if (activeSpineBotY > spineTopY + 0.002 * s) {
      ctx.fillStyle = "#FFD15C";
      drawRoundedRectPath(-0.004 * s, spineTopY, 0.008 * s, activeSpineBotY - spineTopY, 0.004 * s);
      ctx.fill();
    }

    // Bottom Fuse Cord & Crisp Geometric Burning Spark (Scene 1 End & Scene 2)
    if (currentScene === 0 || currentScene === 1) {
      const fuseAppear = currentScene === 0 ? easeOutQuart(subProgress(sceneProgress, 0.50, 0.85)) : 1;
      const curFuseBotY = lerp(spineFullBotY, fuseBotY, fuseAppear * (1 - fuseBurnAmt));
      if (curFuseBotY > spineFullBotY + 0.003 * s) {
        ctx.strokeStyle = "#FFE6A8";
        ctx.lineWidth = Math.max(2, 0.0055 * s);
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(0, spineFullBotY);
        const midY = (spineFullBotY + curFuseBotY) * 0.5;
        ctx.quadraticCurveTo(0.014 * s * (1 - fuseBurnAmt), midY, 0, curFuseBotY);
        ctx.stroke();

        // Crisp Geometric Spark Star at Active Fuse Tip (Zero Blurry Glow)
        if (sparkActive > 0.01 && fuseBurnAmt < 0.99) {
          const sparkSpin = loopT * 7.5;
          const sparkPulse = 1 + 0.16 * Math.sin(loopT * 24);
          const spR = 0.024 * s * sparkActive * sparkPulse;
          drawStarPolygon(0, curFuseBotY, 8, spR, spR * 0.42, sparkSpin, "#FF6B2B");
          drawStarPolygon(0, curFuseBotY, 4, spR * 0.78, spR * 0.30, -sparkSpin * 1.2, "#FFD15C");
          drawDiamond(0, curFuseBotY, spR * 0.32, spR * 0.32, "#FFF8E6");

          // 4 Cleanly Separated Downward Micro-Sparks (Strictly Below Fuse Tip, Zero Tube Overlap)
          const microAngles = [Math.PI * 0.28, Math.PI * 0.42, Math.PI * 0.58, Math.PI * 0.72];
          for (let m = 0; m < microAngles.length; m++) {
            const mp = (sceneProgress * 4.5 + m * 0.25) % 1;
            const mDist = lerp(0.028 * s, 0.068 * s, easeOutQuart(mp));
            const mSize = lerp(0.0075 * s, 0.002 * s, mp) * sparkActive;
            const mx = Math.cos(microAngles[m]) * mDist;
            const my = curFuseBotY + Math.sin(microAngles[m]) * mDist;
            ctx.save();
            ctx.globalAlpha = 1 - mp;
            drawDiamond(mx, my, mSize, mSize * 1.2, m % 2 === 0 ? "#FFD15C" : "#FF6B2B");
            ctx.restore();
          }
        }
      }
    }

    // 5 Symmetrical Pairs of Firecracker Tubes (Clean Staggered Entry & Sequential Bottom-Up Pop)
    for (let k = 0; k < pairCount; k++) {
      let tubeScale = 0;
      let tubeAngle = 0.34; // ~19.5 deg clean outward-downward tilt

      if (currentScene === 0) {
        const entryP = easeOutQuart(subProgress(sceneProgress, 0.08 + k * 0.10, 0.36 + k * 0.10));
        tubeScale = entryP;
        tubeAngle = lerp(0.12, 0.34, entryP);
      } else if (currentScene === 1) {
        tubeScale = 1;
        // Subtle anticipation scale pulse moving upward near end of fuse burn
        const readyBoost = subProgress(sceneProgress, 0.65, 1.0);
        tubeScale = 1 + 0.035 * readyBoost * Math.sin((k + 1) * 0.6 + sceneProgress * Math.PI * 2);
      } else if (currentScene === 2) {
        const popT = burstStartTimes[k];
        if (loopT < popT) {
          tubeScale = 1;
        } else if (loopT < popT + 0.16) {
          tubeScale = 1 - easeOutQuart((loopT - popT) / 0.16);
        } else {
          tubeScale = 0;
        }
      } else {
        tubeScale = 0;
      }

      if (tubeScale > 0.01) {
        const ty = pairYOffsets[k];
        const lagOffset = chainSway * (k + 1) * 0.005 * s;
        const isMagenta = k % 2 === 1;
        drawFirecrackerTube(-0.003 * s + lagOffset, ty, -1, tubeAngle, tubeScale, isMagenta);
        drawFirecrackerTube(0.003 * s + lagOffset, ty, 1, tubeAngle, tubeScale, !isMagenta);
      }
    }

    ctx.restore();
  }

  // 4B. Always-Present Top Hanging Gold Ring & Festive "2027" Diamond Header Plaque
  ctx.save();
  const hScale = 1 + 0.06 * plaquePulse;
  ctx.translate(0, headerCenterY);
  ctx.scale(hScale, hScale);
  ctx.translate(0, -headerCenterY);

  // Top Gold Hanging Ring & Knot
  ctx.strokeStyle = "#FFD15C";
  ctx.lineWidth = Math.max(2, 0.0075 * s);
  ctx.beginPath();
  ctx.arc(0, ringCenterY, ringR, 0, TAU);
  ctx.stroke();

  ctx.fillStyle = "#E6A82E";
  ctx.beginPath();
  ctx.arc(0, ringCenterY + ringR, 0.009 * s, 0, TAU);
  ctx.fill();

  // Outer Gold Elongated Diamond Header Plaque
  const diaRx = 0.116 * s;
  const diaRy = 0.068 * s;

  function traceHeaderDiamond(rx, ry) {
    ctx.beginPath();
    ctx.moveTo(0, headerCenterY - ry);
    ctx.lineTo(rx, headerCenterY);
    ctx.lineTo(0, headerCenterY + ry);
    ctx.lineTo(-rx, headerCenterY);
    ctx.closePath();
  }

  traceHeaderDiamond(diaRx, diaRy);
  ctx.fillStyle = "#FFD15C";
  ctx.fill();

  // Inner Rich Magenta Diamond Field
  traceHeaderDiamond(diaRx - 0.009 * s, diaRy - 0.006 * s);
  ctx.fillStyle = "#C91E63";
  ctx.fill();

  // Inner Precision Gold Accent Border
  traceHeaderDiamond(diaRx - 0.016 * s, diaRy - 0.011 * s);
  ctx.strokeStyle = "#FFE699";
  ctx.lineWidth = Math.max(1.2, 0.0022 * s);
  ctx.stroke();

  // Custom Geometric Vector "2027" Numerals Centered Cleanly Inside Diamond
  const digits = ["2", "0", "2", "7"];
  const dW = 0.020 * s;
  const dH = 0.029 * s;
  const dGap = 0.008 * s;
  const totalDW = digits.length * dW + (digits.length - 1) * dGap;
  const startX = -totalDW * 0.5;
  const dLineW = Math.max(1.6, 0.0042 * s);
  for (let di = 0; di < digits.length; di++) {
    drawVectorDigit(digits[di], startX + di * (dW + dGap), headerCenterY - dH * 0.5, dW, dH, "#FFF5DB", dLineW);
  }

  // Symmetrical Top & Bottom Mini Gold Accent Dots inside Diamond Tips
  drawDiamond(0, headerCenterY - diaRy * 0.62, 0.0045 * s, 0.0045 * s, "#FFD15C");
  drawDiamond(0, headerCenterY + diaRy * 0.62, 0.0045 * s, 0.0045 * s, "#FFD15C");

  // Crisp Diagonal Sheen Sweep Clipped Strictly Inside Header Plaque (Scene 3 Climax)
  if (plaqueSheen >= 0 && plaqueSheen <= 1) {
    ctx.save();
    traceHeaderDiamond(diaRx - 0.009 * s, diaRy - 0.006 * s);
    ctx.clip();
    const sx = lerp(-diaRx * 1.6, diaRx * 1.6, plaqueSheen);
    ctx.fillStyle = "rgba(255, 245, 219, 0.42)";
    ctx.beginPath();
    ctx.moveTo(sx - 0.018 * s, headerCenterY - diaRy * 1.2);
    ctx.lineTo(sx + 0.014 * s, headerCenterY - diaRy * 1.2);
    ctx.lineTo(sx - 0.018 * s, headerCenterY + diaRy * 1.2);
    ctx.lineTo(sx - 0.050 * s, headerCenterY + diaRy * 1.2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  ctx.restore();
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawDiamond(x, y, rx, ry, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fill();
  }

  function drawSeigaihaFan(x, y, r, colOuter, colMid, colInner) {
    // Solid layered flat-vector Seigaiha wave fan (filled semicircles, zero thin strokes)
    ctx.save();
    ctx.translate(x, y);
    ctx.beginPath();
    ctx.arc(0, 0, r, Math.PI, TAU);
    ctx.closePath();
    ctx.fillStyle = colOuter;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, r * 0.68, Math.PI, TAU);
    ctx.closePath();
    ctx.fillStyle = colMid;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, r * 0.36, Math.PI, TAU);
    ctx.closePath();
    ctx.fillStyle = colInner;
    ctx.fill();
    ctx.restore();
  }

  function drawSideSeigaihaCluster(centerX, centerY, unit, waveShift) {
    // Architectural 3-row solid flat Seigaiha wave cluster positioned cleanly in outer margins
    const r = unit;
    const cols = ["#0B2621", "#123831", "#1A4D43"];
    const baseDark = "#061714";

    ctx.save();
    // Back row (2 fans)
    for (let i = 0; i < 2; i++) {
      const fx = centerX + (i === 0 ? -r * 0.85 : r * 0.85) + waveShift * 0.5;
      const fy = centerY - r * 0.55;
      drawSeigaihaFan(fx, fy, r, cols[0], baseDark, cols[1]);
    }
    // Mid row (3 fans)
    for (let i = -1; i <= 1; i++) {
      const fx = centerX + i * r * 1.12 - waveShift * 0.7;
      const fy = centerY + r * 0.08;
      drawSeigaihaFan(fx, fy, r, cols[1], baseDark, cols[2]);
    }
    // Front row (2 fans)
    for (let i = 0; i < 2; i++) {
      const fx = centerX + (i === 0 ? -r * 0.62 : r * 0.62) + waveShift;
      const fy = centerY + r * 0.68;
      drawSeigaihaFan(fx, fy, r, cols[2], cols[0], cols[1]);
    }
    ctx.restore();
  }

  function drawFretMotif(x, y, size, color) {
    // Crisp flat geometric Chinese square-spiral fret emblem
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(1.6, size * 0.14);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    const h = size * 0.5;
    ctx.beginPath();
    ctx.moveTo(-h, -h);
    ctx.lineTo(h, -h);
    ctx.lineTo(h, h);
    ctx.lineTo(-h, h);
    ctx.lineTo(-h, -h * 0.35);
    ctx.lineTo(h * 0.42, -h * 0.35);
    ctx.lineTo(h * 0.42, h * 0.42);
    ctx.lineTo(-h * 0.35, h * 0.42);
    ctx.stroke();
    ctx.restore();
  }

  function drawRadialSeigaihaPetal(angle, baseR, fanR, colOuter, colMid, colInner) {
    // Sculptural solid-filled traditional Seigaiha wave-fan oriented radially outward (NOT a thin HUD arc)
    ctx.save();
    ctx.rotate(angle);
    ctx.translate(0, -baseR);

    ctx.beginPath();
    ctx.arc(0, 0, fanR, Math.PI, TAU);
    ctx.closePath();
    ctx.fillStyle = colOuter;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, fanR * 0.68, Math.PI, TAU);
    ctx.closePath();
    ctx.fillStyle = colMid;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, fanR * 0.36, Math.PI, TAU);
    ctx.closePath();
    ctx.fillStyle = colInner;
    ctx.fill();

    ctx.restore();
  }

  function traceCoinSilhouetteWithHole(R, holeHalf) {
    ctx.beginPath();
    ctx.arc(0, 0, R, 0, TAU, false);
    // Counter-clockwise inner square for authentic hollow cut-out
    ctx.moveTo(-holeHalf, -holeHalf);
    ctx.lineTo(-holeHalf, holeHalf);
    ctx.lineTo(holeHalf, holeHalf);
    ctx.lineTo(holeHalf, -holeHalf);
    ctx.closePath();
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const hoverY = Math.sin(loopPhase * 2) * 0.007 * s;

  let assembleAmt = 1; // 0 = poised 8-segment outer ring, 1 = assembled whole coin
  let detailReveal = 1;
  let flipCos = 1;     // +1 front, -1 back
  let sheenPos = -1;
  let waveStageP = 0;  // 0..1 active during Scene 3
  let coinPulse = 0;
  let sideWaveBoost = 0;

  if (currentScene === 0) {
    // Scene 1: 8-Segment Radial Assembly & Gold Carving Reveal
    assembleAmt = easeInOutQuint(subProgress(sceneProgress, 0.06, 0.68));
    detailReveal = easeOutQuart(subProgress(sceneProgress, 0.62, 0.96));
    flipCos = 1;
  } else if (currentScene === 1) {
    // Scene 2: Silky 2D scaleX Coin Flip & Crisp Diagonal Sheen Sweep
    assembleAmt = 1;
    detailReveal = 1;
    const flipP = easeInOutCubic(subProgress(sceneProgress, 0.06, 0.66));
    flipCos = Math.cos(flipP * TAU);
    if (sceneProgress >= 0.66 && sceneProgress <= 0.96) {
      sheenPos = easeInOutCubic(subProgress(sceneProgress, 0.66, 0.96));
    }
  } else if (currentScene === 2) {
    // Scene 3: Solid Layered Seigaiha Wave Bloom & Harmonious Pulse
    assembleAmt = 1;
    detailReveal = 1;
    flipCos = 1;
    waveStageP = sceneProgress;
    coinPulse = 0.5 - 0.5 * Math.cos(sceneProgress * Math.PI * 4);
    sideWaveBoost = Math.sin(sceneProgress * Math.PI);
    if (sceneProgress >= 0.34 && sceneProgress <= 0.68) {
      sheenPos = easeInOutCubic(subProgress(sceneProgress, 0.34, 0.68));
    }
  } else {
    // Scene 4: Graceful Disassembly back to Exact t=0 Poised 8-Segment Ring
    detailReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.32));
    assembleAmt = 1 - easeInOutQuint(subProgress(sceneProgress, 0.28, 0.94));
    flipCos = 1;
  }

  // --- LAYER 1: Clean Dark Matte Emerald-Obsidian Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#061714");
  bgGrad.addColorStop(0.52, "#04110F");
  bgGrad.addColorStop(1, "#020A09");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Solid Seigaiha Wave Clusters (Strictly Outside Hero & Wave Bloom) ---
  const halfW = width * 0.5;
  if (halfW > 0.58 * s) {
    const clusterXDist = Math.min(halfW - 0.13 * s, 0.69 * s);
    const waveShift = Math.sin(loopPhase) * 0.014 * s * (1 + 0.45 * sideWaveBoost);
    const unit = 0.056 * s;

    drawSideSeigaihaCluster(cx - clusterXDist, cy - 0.21 * s, unit, waveShift);
    drawSideSeigaihaCluster(cx - clusterXDist, cy + 0.24 * s, unit * 0.90, -waveShift);
    drawSideSeigaihaCluster(cx + clusterXDist, cy - 0.21 * s, unit, -waveShift);
    drawSideSeigaihaCluster(cx + clusterXDist, cy + 0.24 * s, unit * 0.90, waveShift);
  }

  // --- LAYER 3: Scene 3 Sculptural Solid Seigaiha Wave-Fan Bloom (Strictly Outside Coin Perimeter) ---
  // Classic layered semicircular Seigaiha wave fans blooming radially outside coin R=0.215*s (zero HUD lines).
  if (waveStageP > 0.005 && waveStageP < 0.995) {
    ctx.save();
    ctx.translate(cx, cy + hoverY);

    const wavePalettes = [
      ["#105E4B", "#21A682", "#F2C96B"],
      ["#0C4A3B", "#1A8C6D", "#FFE4A3"]
    ];
    const fanCount = 8;
    const fanStep = TAU / fanCount;

    for (let w = 0; w < 2; w++) {
      const localP = w === 0
        ? subProgress(waveStageP, 0.0, 0.54)
        : subProgress(waveStageP, 0.46, 1.0);
      if (localP <= 0.005 || localP >= 0.995) continue;

      const env = Math.sin(localP * Math.PI);
      const easeP = easeOutQuart(localP);
      const baseR = lerp(0.254 * s, 0.342 * s, easeP);
      const fanR = lerp(0.032 * s, 0.042 * s, env);
      const rotOffset = w === 0 ? 0 : fanStep * 0.5;

      ctx.save();
      ctx.globalAlpha = clamp01(env * 1.25);

      for (let k = 0; k < fanCount; k++) {
        const ang = k * fanStep + rotOffset;
        drawRadialSeigaihaPetal(
          ang,
          baseR,
          fanR,
          wavePalettes[w][0],
          wavePalettes[w][1],
          wavePalettes[w][2]
        );
      }

      ctx.restore();
    }
    ctx.restore();
  }

  // --- LAYER 4: Hero Icon — Imperial Jade Fortune Coin (8-Segment Assembly + 2D Flip) ---
  const coinR = 0.215 * s;
  const jadeR = coinR * 0.84;
  const collarHalf = coinR * 0.335;
  const holeHalf = coinR * 0.255;

  ctx.save();
  ctx.translate(cx, cy + hoverY);

  const pulseScale = 1 + 0.022 * coinPulse;
  ctx.scale(pulseScale, pulseScale);

  if (assembleAmt < 0.999) {
    // 4A. Disassembled / Assembling 8 Exact Square-Hole Coin Segments (100% Seamless Match to Assembled Coin)
    const radialDist = lerp(0.105 * s, 0, assembleAmt);
    const segScale = lerp(0.84, 1.0, assembleAmt);
    const segCount = 8;
    const stepA = TAU / segCount;
    const gapA = lerp(0.055, 0, assembleAmt);

    for (let i = 0; i < segCount; i++) {
      const a0 = i * stepA - Math.PI * 0.5 + gapA * 0.5;
      const a1 = (i + 1) * stepA - Math.PI * 0.5 - gapA * 0.5;
      const midA = (a0 + a1) * 0.5;

      ctx.save();
      ctx.translate(Math.cos(midA) * radialDist, Math.sin(midA) * radialDist);
      ctx.scale(segScale, segScale);

      // Intersect exact coin-with-square-hole silhouette with this 45-degree wedge sector
      traceCoinSilhouetteWithHole(coinR, holeHalf);
      ctx.clip("evenodd");

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, coinR * 1.05, a0, a1, false);
      ctx.closePath();
      ctx.clip();

      // Outer Gold Rim
      ctx.fillStyle = "#F2C96B";
      ctx.fillRect(-coinR - 2, -coinR - 2, coinR * 2 + 4, coinR * 2 + 4);

      // Inner Gold Bevel Step
      ctx.fillStyle = "#C99630";
      ctx.beginPath();
      ctx.arc(0, 0, jadeR + coinR * 0.028, 0, TAU);
      ctx.fill();

      // Imperial Jade Field with Diagonal Editorial Tonal Split
      ctx.fillStyle = "#178C6D";
      ctx.beginPath();
      ctx.arc(0, 0, jadeR, 0, TAU);
      ctx.fill();

      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, jadeR, 0, TAU);
      ctx.clip();
      ctx.fillStyle = "#22AA85";
      ctx.beginPath();
      ctx.moveTo(-coinR, coinR);
      ctx.lineTo(-coinR, -coinR);
      ctx.lineTo(coinR, -coinR);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // Jade Bead Accent Centered in Outer Gold Rim Segment
      const beadR = coinR * 0.92;
      ctx.fillStyle = "#199473";
      ctx.beginPath();
      ctx.arc(Math.cos(midA) * beadR, Math.sin(midA) * beadR, coinR * 0.032, 0, TAU);
      ctx.fill();

      // Exact Square Gold Collar Matching Assembled State Seamlessly
      ctx.fillStyle = "#C99630";
      ctx.fillRect(-(collarHalf + coinR * 0.022), -(collarHalf + coinR * 0.022), (collarHalf + coinR * 0.022) * 2, (collarHalf + coinR * 0.022) * 2);

      ctx.fillStyle = "#F2C96B";
      ctx.fillRect(-collarHalf, -collarHalf, collarHalf * 2, collarHalf * 2);

      ctx.restore();
    }
  } else {
    // 4B. Fully Assembled Precision Coin with Pure-2D Horizontal Flip (Scene 1 End, Scene 2, Scene 3, Scene 4 Start)
    const absFlip = Math.abs(flipCos);
    const isFront = flipCos >= 0;
    const clampedSX = Math.max(0.015, absFlip);
    const edgeThick = (1 - absFlip) * 0.026 * s;

    // Crisp 2D Flat Coin Edge Band during Flip Transition
    if (edgeThick > 0.6) {
      ctx.save();
      const edgeOffset = flipCos >= 0 ? -edgeThick : edgeThick;
      ctx.translate(edgeOffset, 0);
      ctx.scale(clampedSX, 1);
      traceCoinSilhouetteWithHole(coinR, holeHalf);
      ctx.fillStyle = "#B88424";
      ctx.fill("evenodd");
      ctx.restore();
    }

    ctx.save();
    ctx.scale(clampedSX, 1);

    // Clip to authentic hollow coin silhouette (circle minus inner square)
    ctx.save();
    traceCoinSilhouetteWithHole(coinR, holeHalf);
    ctx.clip("evenodd");

    // Outer Imperial Gold Rim
    ctx.fillStyle = "#F2C96B";
    ctx.fillRect(-coinR - 2, -coinR - 2, coinR * 2 + 4, coinR * 2 + 4);

    // Outer Gold Rim Inner Recessed Step
    ctx.fillStyle = "#C99630";
    ctx.beginPath();
    ctx.arc(0, 0, jadeR + coinR * 0.028, 0, TAU);
    ctx.fill();

    // Base Imperial Jade Field
    ctx.fillStyle = isFront ? "#178C6D" : "#147A5F";
    ctx.beginPath();
    ctx.arc(0, 0, jadeR, 0, TAU);
    ctx.fill();

    // Clean 2D Flat Editorial Diagonal Tonal Facet on Jade Field
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, jadeR, 0, TAU);
    ctx.clip();
    ctx.fillStyle = isFront ? "#22AA85" : "#1D9675";
    ctx.beginPath();
    ctx.moveTo(-coinR, coinR);
    ctx.lineTo(-coinR, -coinR);
    ctx.lineTo(coinR, -coinR);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // 8 Jade Bead Studs Centered Symmetrically in the Gold Outer Rim
    for (let i = 0; i < 8; i++) {
      const ang = (i + 0.5) * (TAU / 8);
      const bx = Math.cos(ang) * coinR * 0.92;
      const by = Math.sin(ang) * coinR * 0.92;
      ctx.fillStyle = "#199473";
      ctx.beginPath();
      ctx.arc(bx, by, coinR * 0.032, 0, TAU);
      ctx.fill();
    }

    // Inner Stepped Gold Square Collar Framing the Hollow Square Hole
    ctx.fillStyle = "#C99630";
    ctx.fillRect(-(collarHalf + coinR * 0.022), -(collarHalf + coinR * 0.022), (collarHalf + coinR * 0.022) * 2, (collarHalf + coinR * 0.022) * 2);

    ctx.fillStyle = "#F2C96B";
    ctx.fillRect(-collarHalf, -collarHalf, collarHalf * 2, collarHalf * 2);

    // Subtle Crisp Inner Highlight Line on Square Collar
    ctx.strokeStyle = "#FFE8AD";
    ctx.lineWidth = Math.max(1.2, 0.0024 * s);
    ctx.strokeRect(-collarHalf + coinR * 0.025, -collarHalf + coinR * 0.025, (collarHalf - coinR * 0.025) * 2, (collarHalf - coinR * 0.025) * 2);

    // Carved Gold Cardinal Motifs & "20" / "27" Numerals (Revealed Cleanly with detailReveal)
    if (detailReveal > 0.01) {
      ctx.save();
      ctx.globalAlpha = detailReveal;

      if (isFront) {
        // Front Face: Crisp Geometric "20" (Top) & "27" (Bottom) + Left/Right Gold Fret Seals
        const dW = 0.027 * s;
        const dH = 0.040 * s;
        const dGap = 0.011 * s;
        const pairW = dW * 2 + dGap;
        const dLineW = Math.max(2, 0.0052 * s);
        const topY = -coinR * 0.595 - dH * 0.5;
        const botY = coinR * 0.595 - dH * 0.5;

        drawVectorDigit("2", -pairW * 0.5, topY, dW, dH, "#FFF0C7", dLineW);
        drawVectorDigit("0", -pairW * 0.5 + dW + dGap, topY, dW, dH, "#FFF0C7", dLineW);

        drawVectorDigit("2", -pairW * 0.5, botY, dW, dH, "#FFF0C7", dLineW);
        drawVectorDigit("7", -pairW * 0.5 + dW + dGap, botY, dW, dH, "#FFF0C7", dLineW);

        drawFretMotif(-coinR * 0.59, 0, coinR * 0.16, "#F5D076");
        drawFretMotif(coinR * 0.59, 0, coinR * 0.16, "#F5D076");
      } else {
        // Reverse Face (shown cleanly during 2D flip): 4 Symmetrical Auspicious Fret Seals
        drawFretMotif(0, -coinR * 0.59, coinR * 0.17, "#F5D076");
        drawFretMotif(0, coinR * 0.59, coinR * 0.17, "#F5D076");
        drawFretMotif(-coinR * 0.59, 0, coinR * 0.17, "#F5D076");
        drawFretMotif(coinR * 0.59, 0, coinR * 0.17, "#F5D076");
      }

      // 4 Diagonal Gold Diamond Studs
      for (let d = 0; d < 4; d++) {
        const da = (d + 0.5) * (Math.PI * 0.5);
        drawDiamond(
          Math.cos(da) * coinR * 0.65,
          Math.sin(da) * coinR * 0.65,
          coinR * 0.036 * detailReveal,
          coinR * 0.036 * detailReveal,
          "#FFE8AD"
        );
      }

      ctx.restore();
    }

    // Crisp Diagonal Flat Sheen Band Sweeping Cleanly Across Coin Face (Clipped strictly to coin)
    if (sheenPos >= 0 && sheenPos <= 1) {
      const sx = lerp(-coinR * 1.9, coinR * 1.9, sheenPos);
      ctx.fillStyle = "rgba(255, 248, 224, 0.36)";
      ctx.beginPath();
      ctx.moveTo(sx - 0.036 * s, -coinR * 1.2);
      ctx.lineTo(sx + 0.024 * s, -coinR * 1.2);
      ctx.lineTo(sx - 0.068 * s, coinR * 1.2);
      ctx.lineTo(sx - 0.128 * s, coinR * 1.2);
      ctx.closePath();
      ctx.fill();
    }

    ctx.restore();

    // Crisp Outer Gold Edge Outline
    ctx.strokeStyle = "#FFE8AD";
    ctx.lineWidth = Math.max(1.5, 0.003 * s);
    ctx.beginPath();
    ctx.arc(0, 0, coinR, 0, TAU);
    ctx.stroke();

    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function mixHex(hexA, hexB, u) {
    u = clamp01(u);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const r = Math.round(lerp((a >> 16) & 255, (b >> 16) & 255, u));
    const g = Math.round(lerp((a >> 8) & 255, (b >> 8) & 255, u));
    const bl = Math.round(lerp(a & 255, b & 255, u));
    return "rgb(" + r + "," + g + "," + bl + ")";
  }

  function drawEnvelopeBodyPath(x, y, w, h, topR, botR) {
    const tr = Math.min(topR, w * 0.5, h * 0.5);
    const br = Math.min(botR, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + tr, y);
    ctx.lineTo(x + w - tr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + tr);
    ctx.lineTo(x + w, y + h - br);
    ctx.quadraticCurveTo(x + w, y + h, x + w - br, y + h);
    ctx.lineTo(x + br, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - br);
    ctx.lineTo(x, y + tr);
    ctx.quadraticCurveTo(x, y, x + tr, y);
    ctx.closePath();
  }

  function drawRoundedRectPath(x, y, w, h, r) {
    const rr = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function tracePartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 1; i < points.length; i++) {
      const len = Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1]);
      segLens.push(len);
      totalLen += len;
    }
    if (totalLen <= 0) return;
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      const len = segLens[i];
      if (remaining >= len) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= len;
      } else {
        const frac = len > 0 ? remaining / len : 0;
        ctx.lineTo(
          lerp(points[i][0], points[i + 1][0], frac),
          lerp(points[i][1], points[i + 1][1], frac)
        );
        break;
      }
    }
    ctx.stroke();
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawDiamond(x, y, rx, ry, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fill();
  }

  function drawFourPointStar(x, y, rOut, rIn, rot, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? rOut : rIn;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawHexCoin(x, y, r, rot, outerCol, innerCol) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.fillStyle = outerCol;
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i * Math.PI) / 3;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();

    const hole = r * 0.38;
    ctx.fillStyle = innerCol;
    ctx.fillRect(-hole * 0.5, -hole * 0.5, hole, hole);
    ctx.restore();
  }

  function drawBgLatticeMotif(x, y, unit, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = color;
    // Outer stepped flat diamond
    ctx.beginPath();
    ctx.moveTo(0, -unit);
    ctx.lineTo(unit, 0);
    ctx.lineTo(0, unit);
    ctx.lineTo(-unit, 0);
    ctx.closePath();
    ctx.fill();

    // Inner cutout diamond
    ctx.fillStyle = "#120815";
    ctx.beginPath();
    ctx.moveTo(0, -unit * 0.58);
    ctx.lineTo(unit * 0.58, 0);
    ctx.lineTo(0, unit * 0.58);
    ctx.lineTo(-unit * 0.58, 0);
    ctx.closePath();
    ctx.fill();

    // Center accent square
    ctx.fillStyle = color;
    const sq = unit * 0.24;
    ctx.fillRect(-sq, -sq, sq * 2, sq * 2);
    ctx.restore();
  }

  function drawCurvedRibbon(side, x0, y0, spanX, ampY, thickness, progress, phase, color) {
    if (progress <= 0.01) return;
    const steps = 22;
    const drawSteps = Math.max(2, Math.floor(steps * progress));
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    for (let i = 0; i <= drawSteps; i++) {
      const u = i / steps;
      const px = x0 + side * u * spanX;
      const py = y0 + Math.sin(u * Math.PI * 1.5 + phase) * ampY;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
    ctx.restore();
  }

  function traceFlapPath(envHalfW, envTop, flapH, factor, cornerR) {
    const tipY = envTop + flapH * factor;
    const shoulderY = envTop + Math.min(cornerR * 0.6, Math.abs(flapH * factor) * 0.25) * (factor >= 0 ? 1 : -1);
    const tipRound = 0.022 * s * Math.abs(factor);
    ctx.beginPath();
    ctx.moveTo(-envHalfW, envTop);
    ctx.lineTo(-envHalfW, shoulderY);
    ctx.quadraticCurveTo(-envHalfW * 0.42, tipY, -tipRound, tipY);
    ctx.quadraticCurveTo(0, tipY + (factor >= 0 ? 0.008 * s * factor : 0.008 * s * factor), tipRound, tipY);
    ctx.quadraticCurveTo(envHalfW * 0.42, tipY, envHalfW, shoulderY);
    ctx.lineTo(envHalfW, envTop);
    ctx.closePath();
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const floatY = Math.sin(loopPhase * 2) * 0.007 * s;

  let envScale = 1.0;
  let envAngle = 0;
  let echoStrength = 0;
  let inlayAmt = 1;
  let sealAmt = 0;
  let sealRot = 0;
  let flapFactor = 1; // +1 = closed down, -1 = open up
  let cardSlide = 0;
  let cardDigitsAmt = 0;
  let cardSheen = -1;
  let celebrateAmt = 0;
  let celebrateWave = 0;

  if (currentScene === 0) {
    // Scene 1: Composed 2D Showcase Pivot & Champagne-Gold Geometric Inlay Assembly
    const moveP = subProgress(sceneProgress, 0.0, 0.52);
    envAngle = -Math.sin(moveP * Math.PI) * 0.072;
    echoStrength = Math.sin(moveP * Math.PI);
    envScale = lerp(0.94, 1.0, easeInOutCubic(moveP));
    inlayAmt = easeInOutCubic(subProgress(sceneProgress, 0.28, 0.86));
    sealAmt = easeOutQuart(subProgress(sceneProgress, 0.58, 0.94));
    sealRot = lerp(-Math.PI * 0.25, 0, sealAmt);
    flapFactor = 1;
    cardSlide = 0;
    cardDigitsAmt = 0;
    celebrateAmt = 0;
  } else if (currentScene === 1) {
    // Scene 2: Seal Unlock & Precision 2D Flat Origami Flap Unfold
    envScale = 1.0;
    envAngle = 0;
    inlayAmt = 1;
    const unlockP = easeInOutCubic(subProgress(sceneProgress, 0.0, 0.28));
    sealAmt = 1 - unlockP;
    sealRot = unlockP * Math.PI * 0.5;
    const foldP = easeInOutQuint(subProgress(sceneProgress, 0.22, 0.88));
    flapFactor = Math.cos(foldP * Math.PI);
    cardSlide = 0;
    cardDigitsAmt = 0;
    celebrateAmt = 0;
  } else if (currentScene === 2) {
    // Scene 3: "2027" Greeting Card Emergence & Symmetrical Non-Overlapping Celebration
    envScale = 1.0;
    envAngle = 0;
    inlayAmt = 1;
    sealAmt = 0;
    flapFactor = -1;
    cardSlide = easeOutQuart(subProgress(sceneProgress, 0.0, 0.42));
    cardDigitsAmt = easeInOutCubic(subProgress(sceneProgress, 0.22, 0.62));
    celebrateAmt = easeOutQuart(subProgress(sceneProgress, 0.26, 0.72));
    celebrateWave = sceneProgress * TAU;
    if (sceneProgress >= 0.54 && sceneProgress <= 0.86) {
      cardSheen = easeInOutCubic(subProgress(sceneProgress, 0.54, 0.86));
    }
  } else {
    // Scene 4: Graceful Accent Retraction, Card Tuck, Flap Refold & Seamless Reset to t=0
    celebrateAmt = 1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.30));
    celebrateWave = TAU + sceneProgress * Math.PI * 0.6;
    cardDigitsAmt = 1 - easeInOutCubic(subProgress(sceneProgress, 0.06, 0.28));
    cardSlide = 1 - easeInOutCubic(subProgress(sceneProgress, 0.14, 0.46));
    const refoldP = easeInOutQuint(subProgress(sceneProgress, 0.44, 0.76));
    flapFactor = -Math.cos(refoldP * Math.PI);
    sealAmt = 0;
    inlayAmt = 1 - easeInOutCubic(subProgress(sceneProgress, 0.70, 0.96));
    envScale = lerp(1.0, 0.94, easeInOutCubic(subProgress(sceneProgress, 0.70, 0.98)));
    envAngle = 0;
  }

  // --- LAYER 1: Clean Dark Matte Plum-Obsidian Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#170B1A");
  bgGrad.addColorStop(0.5, "#110714");
  bgGrad.addColorStop(1, "#09040C");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Far-Outer Architectural Background Diamond Motifs (Strictly Outside Hero & Ribbon Zones) ---
  const halfW = width * 0.5;
  if (halfW > 0.66 * s) {
    const motifConfigs = [
      { side: -1, xDist: 0.73, yOff: -0.25, unit: 0.046, phase: 0.0, col: "#211127" },
      { side: -1, xDist: 0.73, yOff: 0.25, unit: 0.038, phase: 1.5, col: "#27142E" },
      { side: 1, xDist: 0.73, yOff: -0.25, unit: 0.046, phase: 0.8, col: "#211127" },
      { side: 1, xDist: 0.73, yOff: 0.25, unit: 0.038, phase: 2.3, col: "#27142E" }
    ];
    for (let i = 0; i < motifConfigs.length; i++) {
      const m = motifConfigs[i];
      const mx = cx + m.side * Math.min(halfW - 0.09 * s, m.xDist * s);
      const my = cy + m.yOff * s + Math.sin(loopPhase + m.phase) * 0.012 * s;
      drawBgLatticeMotif(mx, my, m.unit * s, m.col);
    }
  }

  // --- LAYER 3: Symmetrical Non-Overlapping Celebration Ribbons & Tokens (Scene 3 & 4) ---
  // 5 strictly disjoint vertical lanes per side, strictly outside |x - cx| >= 0.24 * s (zero collision).
  if (celebrateAmt > 0.005 && halfW > 0.34 * s) {
    ctx.save();
    ctx.translate(cx, cy + floatY);
    ctx.globalAlpha = celebrateAmt;

    for (let side = -1; side <= 1; side += 2) {
      const drift = Math.sin(celebrateWave + (side > 0 ? 0.5 : 0)) * 0.007 * s;

      // Lane 1 (Upper Inner): Crisp Champagne 4-Point Star (Y band: -0.33..-0.24)
      const l1X = side * lerp(0.245, 0.315, celebrateAmt) * s;
      const l1Y = lerp(-0.23, -0.30, celebrateAmt) * s + drift;
      drawFourPointStar(l1X, l1Y, 0.017 * s * celebrateAmt, 0.0055 * s * celebrateAmt, side * celebrateAmt * 0.65, "#F2D28B");

      // Lane 2 (Upper Mid): Sleek Curved Champagne Flat Ribbon (Y band: -0.21..-0.13)
      drawCurvedRibbon(
        side,
        side * 0.255 * s,
        -0.175 * s + drift * 0.7,
        0.155 * s,
        0.022 * s,
        Math.max(2, 0.0065 * s),
        celebrateAmt,
        side > 0 ? 0.3 : 1.2,
        "#F2D28B"
      );

      // Lane 3 (Middle Outer): Crisp Ruby Diamond with Ivory Core (Y band: -0.06..+0.02)
      const l3X = side * lerp(0.26, 0.39, celebrateAmt) * s;
      const l3Y = -0.025 * s - drift * 0.8;
      const dSize = 0.016 * s * celebrateAmt;
      drawDiamond(l3X, l3Y, dSize * 0.85, dSize * 1.15, "#E03153");
      drawDiamond(l3X, l3Y, dSize * 0.34, dSize * 0.46, "#FFF6E5");

      // Lane 4 (Lower Mid): Sleek Curved Rose-Ruby Flat Ribbon (Y band: +0.08..+0.16)
      drawCurvedRibbon(
        side,
        side * 0.250 * s,
        0.120 * s - drift * 0.6,
        0.145 * s,
        0.020 * s,
        Math.max(2, 0.006 * s),
        celebrateAmt,
        side > 0 ? 2.0 : 0.7,
        "#E64566"
      );

      // Lane 5 (Lower Outer): Crisp Ivory & Gold Hexagonal Fortune Token (Y band: +0.21..+0.28)
      const l5X = side * lerp(0.255, 0.355, celebrateAmt) * s;
      const l5Y = lerp(0.20, 0.255, celebrateAmt) * s + drift * 0.9;
      drawHexCoin(l5X, l5Y, 0.0165 * s * celebrateAmt, side * celebrateAmt * 0.52, "#FFF4DC", "#110714");
    }

    ctx.restore();
  }

  // --- LAYER 4: Hero Icon — Luxury Red Envelope & Emerging "2027" Card ---
  const envW = 0.34 * s;
  const envHalfW = envW * 0.5;
  const envH = 0.42 * s;
  const envTop = -0.105 * s;
  const envBot = envTop + envH; // +0.315 * s
  const envTopR = 0.005 * s;
  const envBotR = 0.022 * s;
  const flapH = 0.140 * s;

  ctx.save();
  ctx.translate(cx, cy + floatY);

  // Subtle Clean 2D Flat Vector Motion Echoes during Scene 1 Showcase Pivot
  if (echoStrength > 0.02) {
    for (let e = 2; e >= 1; e--) {
      ctx.save();
      ctx.rotate(envAngle * (1 - e * 0.34));
      ctx.scale(envScale, envScale);
      ctx.globalAlpha = 0.10 * echoStrength * (3 - e) * 0.5;
      ctx.fillStyle = "#D12647";
      drawEnvelopeBodyPath(-envHalfW, envTop, envW, envH, envTopR, envBotR);
      ctx.fill();
      ctx.restore();
    }
  }

  ctx.rotate(envAngle);
  ctx.scale(envScale, envScale);

  // 4A. Envelope Interior Back Wall (Visible when flap is open)
  ctx.fillStyle = "#6E0F24";
  drawEnvelopeBodyPath(-envHalfW, envTop, envW, envH, envTopR, envBotR);
  ctx.fill();

  // 4B. Opened Inner Flap Lining (Rendered BEHIND the card when flapFactor < 0)
  if (flapFactor < 0) {
    const openAmt = -flapFactor;
    const liningCol = mixHex("#A67D38", "#E8C47C", openAmt);
    ctx.save();
    traceFlapPath(envHalfW, envTop, flapH, flapFactor, envTopR);
    ctx.fillStyle = liningCol;
    ctx.fill();

    // Inner champagne lining trim line
    if (openAmt > 0.15) {
      ctx.strokeStyle = "#FFF1CC";
      ctx.lineWidth = Math.max(1.2, 0.0028 * s);
      ctx.save();
      ctx.translate(0, envTop);
      ctx.scale(0.91, 0.87);
      ctx.translate(0, -envTop);
      traceFlapPath(envHalfW, envTop, flapH, flapFactor, envTopR);
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }

  // 4C. Emerging Luxury Ivory "2027" Greeting Card (Clipped strictly above pocket mouth y <= envTop)
  if (cardSlide > 0.001) {
    const cardW = 0.272 * s;
    const cardHalfW = cardW * 0.5;
    const cardH = 0.245 * s;
    const cardTop = lerp(envTop + 0.008 * s, envTop - 0.225 * s, cardSlide);
    const cardR = 0.014 * s;

    ctx.save();
    // Clip cleanly along the horizontal envelope pocket slit so card truly emerges from inside
    ctx.beginPath();
    ctx.rect(-envHalfW, envTop - 0.36 * s, envW, 0.36 * s);
    ctx.clip();

    // Card Paper Base
    drawRoundedRectPath(-cardHalfW, cardTop, cardW, cardH, cardR);
    ctx.fillStyle = "#FFF8EC";
    ctx.fill();

    // Crisp Subtle Edge Separation Outline (clean separation against champagne flap lining)
    ctx.strokeStyle = "#7D1329";
    ctx.lineWidth = Math.max(1.2, 0.0024 * s);
    ctx.stroke();

    // Double Champagne-Gold Inset Border Frame
    const pad1 = 0.014 * s;
    drawRoundedRectPath(-cardHalfW + pad1, cardTop + pad1, cardW - pad1 * 2, cardH - pad1 * 2, cardR * 0.55);
    ctx.strokeStyle = "#D4A955";
    ctx.lineWidth = Math.max(1.4, 0.003 * s);
    ctx.stroke();

    const pad2 = 0.021 * s;
    drawRoundedRectPath(-cardHalfW + pad2, cardTop + pad2, cardW - pad2 * 2, cardH - pad2 * 2, cardR * 0.35);
    ctx.strokeStyle = "#E8C882";
    ctx.lineWidth = Math.max(1, 0.0016 * s);
    ctx.stroke();

    // Card Top Auspicious Geometric Crest (Centered at cardTop + 0.044 * s)
    const crestReveal = easeOutQuart(subProgress(cardDigitsAmt, 0.0, 0.45));
    if (crestReveal > 0.01) {
      const crestY = cardTop + 0.044 * s;
      ctx.save();
      ctx.translate(0, crestY);
      ctx.scale(crestReveal, crestReveal);
      drawFourPointStar(0, 0, 0.014 * s, 0.0052 * s, 0, "#BA1C3B");
      drawDiamond(0, 0, 0.0042 * s, 0.0042 * s, "#F2D28B");
      ctx.restore();

      // Clean Horizontal Divider Rule with Symmetrical End Dots
      const ruleY = cardTop + 0.070 * s;
      const ruleHalfW = 0.082 * s * crestReveal;
      ctx.strokeStyle = "#D4A955";
      ctx.lineWidth = Math.max(1.1, 0.002 * s);
      ctx.beginPath();
      ctx.moveTo(-ruleHalfW, ruleY);
      ctx.lineTo(-0.012 * s * crestReveal, ruleY);
      ctx.moveTo(0.012 * s * crestReveal, ruleY);
      ctx.lineTo(ruleHalfW, ruleY);
      ctx.stroke();
      drawDiamond(0, ruleY, 0.004 * s * crestReveal, 0.004 * s * crestReveal, "#D4A955");
    }

    // Custom Geometric Vector "2027" Numerals (Staggered Vertical Clip Reveal)
    if (cardDigitsAmt > 0.01) {
      const digits = ["2", "0", "2", "7"];
      const dW = 0.035 * s;
      const dH = 0.054 * s;
      const dGap = 0.014 * s;
      const totalDW = digits.length * dW + (digits.length - 1) * dGap;
      const startX = -totalDW * 0.5;
      const centerY = cardTop + 0.126 * s;
      const dLineW = Math.max(2, 0.0066 * s);

      ctx.save();
      ctx.beginPath();
      ctx.rect(-cardHalfW + pad2, centerY - dH * 0.66, cardW - pad2 * 2, dH * 1.32);
      ctx.clip();

      for (let di = 0; di < digits.length; di++) {
        const dp = easeOutQuart(subProgress(cardDigitsAmt, 0.12 + di * 0.13, 0.52 + di * 0.13));
        if (dp <= 0.001) continue;
        const dx = startX + di * (dW + dGap);
        const dy = centerY - dH * 0.5 + (1 - dp) * 0.036 * s;
        ctx.save();
        ctx.globalAlpha = dp;
        drawVectorDigit(digits[di], dx, dy, dW, dH, "#B81C3A", dLineW);
        ctx.restore();
      }
      ctx.restore();

      // Bottom Geometric Ornamental Bar (Centered at cardTop + 0.184 * s)
      const barReveal = easeOutQuart(subProgress(cardDigitsAmt, 0.55, 1.0));
      if (barReveal > 0.01) {
        const barY = cardTop + 0.184 * s;
        ctx.strokeStyle = "#D4A955";
        ctx.lineWidth = Math.max(1.2, 0.0022 * s);
        ctx.beginPath();
        ctx.moveTo(-0.070 * s * barReveal, barY);
        ctx.lineTo(-0.022 * s * barReveal, barY);
        ctx.moveTo(0.022 * s * barReveal, barY);
        ctx.lineTo(0.070 * s * barReveal, barY);
        ctx.stroke();

        drawDiamond(-0.012 * s * barReveal, barY, 0.0035 * s * barReveal, 0.0035 * s * barReveal, "#BA1C3B");
        drawDiamond(0, barY, 0.005 * s * barReveal, 0.005 * s * barReveal, "#D4A955");
        drawDiamond(0.012 * s * barReveal, barY, 0.0035 * s * barReveal, 0.0035 * s * barReveal, "#BA1C3B");
      }
    }

    // Crisp Diagonal Sheen Sweep Clipped Strictly to Card (Scene 3)
    if (cardSheen >= 0 && cardSheen <= 1) {
      ctx.save();
      drawRoundedRectPath(-cardHalfW, cardTop, cardW, cardH, cardR);
      ctx.clip();
      const sx = lerp(-cardW * 1.1, cardW * 1.1, cardSheen);
      ctx.fillStyle = "rgba(255, 255, 255, 0.52)";
      ctx.beginPath();
      ctx.moveTo(sx - 0.028 * s, cardTop - 0.02 * s);
      ctx.lineTo(sx + 0.022 * s, cardTop - 0.02 * s);
      ctx.lineTo(sx - 0.048 * s, cardTop + cardH + 0.02 * s);
      ctx.lineTo(sx - 0.098 * s, cardTop + cardH + 0.02 * s);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  // 4D. Envelope Front Pocket Panel (Clean Royal Crimson with Precision 2D Flat Editorial Facets)
  ctx.save();
  drawEnvelopeBodyPath(-envHalfW, envTop, envW, envH, envTopR, envBotR);
  ctx.clip();

  // Base Royal Crimson Pocket
  ctx.fillStyle = "#BA1C3B";
  ctx.fillRect(-envHalfW, envTop, envW, envH);

  // Subtle Clean 2D Flat Lower Diagonal Fold Facet (Pure Flat Editorial Depth)
  ctx.fillStyle = "#A31632";
  ctx.beginPath();
  ctx.moveTo(-envHalfW, envBot);
  ctx.lineTo(0, envBot - 0.110 * s);
  ctx.lineTo(envHalfW, envBot);
  ctx.closePath();
  ctx.fill();

  // Crisp Champagne Gold Rim at Top Pocket Slit
  ctx.fillStyle = "#E8C47C";
  ctx.fillRect(-envHalfW, envTop, envW, 0.0055 * s);

  // Precision Champagne-Gold Geometric Inlay Frame (Symmetrical Path Draw)
  if (inlayAmt > 0.005) {
    const inPad = 0.020 * s;
    const inLeft = -envHalfW + inPad;
    const inRight = envHalfW - inPad;
    const inTop = envTop + 0.068 * s;
    const inBot = envBot - inPad;
    const step = 0.018 * s;

    ctx.strokeStyle = "#F2D28B";
    ctx.lineWidth = Math.max(1.5, 0.0032 * s);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    const leftBorderPts = [
      [inLeft, inTop],
      [inLeft, inBot - step],
      [inLeft + step, inBot - step],
      [inLeft + step, inBot],
      [0, inBot]
    ];
    const rightBorderPts = [
      [inRight, inTop],
      [inRight, inBot - step],
      [inRight - step, inBot - step],
      [inRight - step, inBot],
      [0, inBot]
    ];
    tracePartialPolyline(leftBorderPts, inlayAmt);
    tracePartialPolyline(rightBorderPts, inlayAmt);

    // Lower Centered Lunar Geometric Diamond & Knot Crest (Well Separated below Closed Seal)
    const crestP = easeOutQuart(subProgress(inlayAmt, 0.35, 1.0));
    if (crestP > 0.01) {
      const emY = 0.192 * s;
      ctx.save();
      ctx.translate(0, emY);
      ctx.scale(crestP, crestP);

      // Outer Champagne Diamond Ring
      ctx.strokeStyle = "#F2D28B";
      ctx.lineWidth = Math.max(1.5, 0.0036 * s);
      ctx.beginPath();
      ctx.moveTo(0, -0.042 * s);
      ctx.lineTo(0.042 * s, 0);
      ctx.lineTo(0, 0.042 * s);
      ctx.lineTo(-0.042 * s, 0);
      ctx.closePath();
      ctx.stroke();

      // Inner Stepped Octagonal Gold Coin Core
      ctx.fillStyle = "#F2D28B";
      ctx.beginPath();
      ctx.arc(0, 0, 0.023 * s, 0, TAU);
      ctx.fill();

      ctx.fillStyle = "#BA1C3B";
      const sq = 0.0125 * s;
      ctx.fillRect(-sq * 0.5, -sq * 0.5, sq, sq);

      // Symmetrical Horizontal Gold Bar Accents Flanking the Medallion
      ctx.strokeStyle = "#F2D28B";
      ctx.lineWidth = Math.max(1.3, 0.0026 * s);
      ctx.beginPath();
      ctx.moveTo(-0.094 * s, 0);
      ctx.lineTo(-0.055 * s, 0);
      ctx.moveTo(0.055 * s, 0);
      ctx.lineTo(0.094 * s, 0);
      ctx.stroke();

      drawDiamond(-0.102 * s, 0, 0.0045 * s, 0.0045 * s, "#FFF1CC");
      drawDiamond(0.102 * s, 0, 0.0045 * s, 0.0045 * s, "#FFF1CC");

      ctx.restore();
    }
  }

  ctx.restore();

  // 4E. Closed Outer Flap Face (Rendered IN FRONT of pocket when flapFactor >= 0)
  if (flapFactor >= 0) {
    const closedAmt = flapFactor;

    // Subtle Crisp Flat Shadow Band strictly below closed flap seam
    ctx.save();
    drawEnvelopeBodyPath(-envHalfW, envTop, envW, envH, envTopR, envBotR);
    ctx.clip();
    ctx.save();
    ctx.translate(0, 0.008 * s * closedAmt);
    traceFlapPath(envHalfW, envTop, flapH, flapFactor, envTopR);
    ctx.fillStyle = "#7D1027";
    ctx.fill();
    ctx.restore();

    // Outer Ruby Crimson Flap Face (smooth flat tonal shift as it hinges upward)
    const flapCol = mixHex("#9C1632", "#D12647", closedAmt);
    traceFlapPath(envHalfW, envTop, flapH, flapFactor, envTopR);
    ctx.fillStyle = flapCol;
    ctx.fill();

    // Crisp Champagne-Gold Flap Trim Edge
    if (inlayAmt > 0.01 && closedAmt > 0.06) {
      ctx.save();
      ctx.globalAlpha = inlayAmt;
      ctx.strokeStyle = "#F2D28B";
      ctx.lineWidth = Math.max(1.5, 0.0032 * s);
      ctx.translate(0, envTop);
      ctx.scale(0.92, 0.89);
      ctx.translate(0, -envTop);
      traceFlapPath(envHalfW, envTop, flapH, flapFactor, envTopR);
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();

    // Circular Champagne-Gold Flap Seal Emblem (Centered cleanly on closed flap tip)
    if (sealAmt > 0.01) {
      const sealY = envTop + flapH * flapFactor;
      const sealR = 0.032 * s * sealAmt;
      ctx.save();
      ctx.translate(0, sealY);
      ctx.rotate(sealRot);
      ctx.globalAlpha = sealAmt;

      // Outer Champagne Gold Disc
      ctx.fillStyle = "#F2D28B";
      ctx.beginPath();
      ctx.arc(0, 0, sealR, 0, TAU);
      ctx.fill();

      // Inner Crimson Ring
      ctx.strokeStyle = "#BA1C3B";
      ctx.lineWidth = Math.max(1.4, 0.0032 * s);
      ctx.beginPath();
      ctx.arc(0, 0, sealR * 0.76, 0, TAU);
      ctx.stroke();

      // Crisp Center Auspicious Diamond Mark
      drawFourPointStar(0, 0, sealR * 0.54, sealR * 0.22, 0, "#BA1C3B");
      drawDiamond(0, 0, sealR * 0.16, sealR * 0.16, "#FFF1CC");

      ctx.restore();
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const s = minSide;
  const TAU = Math.PI * 2;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function subProgress(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeInOutCubic(u) {
    u = clamp01(u);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) * 0.5;
  }

  function easeOutQuart(u) {
    u = clamp01(u);
    return 1 - Math.pow(1 - u, 4);
  }

  function easeInOutQuint(u) {
    u = clamp01(u);
    return u < 0.5 ? 16 * Math.pow(u, 5) : 1 - Math.pow(-2 * u + 2, 5) * 0.5;
  }

  function easeOutBackSubtle(u) {
    u = clamp01(u);
    const c1 = 0.72;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(u - 1, 3) + c1 * Math.pow(u - 1, 2);
  }

  function mixHex(hexA, hexB, u) {
    u = clamp01(u);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(lerp(ar, br, u));
    const g = Math.round(lerp(ag, bg, u));
    const bl = Math.round(lerp(ab, bb, u));
    return "rgb(" + r + "," + g + "," + bl + ")";
  }

  function tracePartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 1; i < points.length; i++) {
      const dx = points[i][0] - points[i - 1][0];
      const dy = points[i][1] - points[i - 1][1];
      const len = Math.hypot(dx, dy);
      segLens.push(len);
      totalLen += len;
    }
    if (totalLen <= 0) return;
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      const len = segLens[i];
      if (remaining >= len) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= len;
      } else {
        const frac = len > 0 ? remaining / len : 0;
        const px = lerp(points[i][0], points[i + 1][0], frac);
        const py = lerp(points[i][1], points[i + 1][1], frac);
        ctx.lineTo(px, py);
        break;
      }
    }
    ctx.stroke();
  }

  function drawRoundedRectPath(x, y, w, h, r) {
    const rr = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function drawOctagonPath(x, y, rx, ry, cut) {
    ctx.beginPath();
    ctx.moveTo(x - rx + cut, y - ry);
    ctx.lineTo(x + rx - cut, y - ry);
    ctx.lineTo(x + rx, y - ry + cut);
    ctx.lineTo(x + rx, y + ry - cut);
    ctx.lineTo(x + rx - cut, y + ry);
    ctx.lineTo(x - rx + cut, y + ry);
    ctx.lineTo(x - rx, y + ry - cut);
    ctx.lineTo(x - rx, y - ry + cut);
    ctx.closePath();
  }

  function drawRuyiCloud(x, y, scale, flipY, fillColor) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, flipY ? -scale : scale);
    ctx.fillStyle = fillColor;
    ctx.beginPath();
    ctx.moveTo(-1.0, 0.22);
    ctx.bezierCurveTo(-1.0, -0.18, -0.62, -0.22, -0.45, -0.05);
    ctx.bezierCurveTo(-0.36, -0.46, 0.36, -0.46, 0.45, -0.05);
    ctx.bezierCurveTo(0.62, -0.22, 1.0, -0.18, 1.0, 0.22);
    ctx.bezierCurveTo(1.0, 0.42, 0.72, 0.44, 0.52, 0.30);
    ctx.lineTo(-0.52, 0.30);
    ctx.bezierCurveTo(-0.72, 0.44, -1.0, 0.42, -1.0, 0.22);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawSideFlatCloud(x, y, unit, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-1.05 * unit, 0.24 * unit);
    ctx.arc(-0.72 * unit, 0.04 * unit, 0.33 * unit, Math.PI * 0.72, Math.PI * 1.88);
    ctx.arc(-0.16 * unit, -0.14 * unit, 0.42 * unit, Math.PI * 1.05, Math.PI * 1.94);
    ctx.arc(0.46 * unit, 0.02 * unit, 0.34 * unit, Math.PI * 1.12, Math.PI * 2.02);
    ctx.arc(0.84 * unit, 0.14 * unit, 0.22 * unit, Math.PI * 1.25, Math.PI * 0.5);
    ctx.lineTo(-0.88 * unit, 0.36 * unit);
    ctx.arc(-0.88 * unit, 0.24 * unit, 0.12 * unit, Math.PI * 0.5, Math.PI * 1.15);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawVectorDigit(digit, x, y, w, h, strokeColor, lineWidth) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (digit === "2") {
      ctx.moveTo(x + w * 0.10, y + h * 0.24);
      ctx.bezierCurveTo(
        x + w * 0.12, y - h * 0.02,
        x + w * 0.90, y - h * 0.02,
        x + w * 0.90, y + h * 0.27
      );
      ctx.bezierCurveTo(
        x + w * 0.90, y + h * 0.50,
        x + w * 0.40, y + h * 0.68,
        x + w * 0.10, y + h * 0.98
      );
      ctx.lineTo(x + w * 0.92, y + h * 0.98);
    } else if (digit === "0") {
      const rx = w * 0.41;
      const ry = h * 0.48;
      const ox = x + w * 0.50;
      const oy = y + h * 0.50;
      ctx.moveTo(ox, oy - ry);
      ctx.bezierCurveTo(ox + rx * 1.15, oy - ry, ox + rx * 1.15, oy + ry, ox, oy + ry);
      ctx.bezierCurveTo(ox - rx * 1.15, oy + ry, ox - rx * 1.15, oy - ry, ox, oy - ry);
    } else if (digit === "7") {
      ctx.moveTo(x + w * 0.10, y + h * 0.04);
      ctx.lineTo(x + w * 0.90, y + h * 0.04);
      ctx.lineTo(x + w * 0.36, y + h * 0.98);
    }
    ctx.stroke();
    ctx.restore();
  }

  function sampleGlobeHalfPoints(gx, gy, rx, ry, sideSign, steps) {
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const angle = -Math.PI * 0.5 + u * Math.PI;
      const px = gx + Math.cos(angle) * rx * sideSign;
      const py = gy + Math.sin(angle) * ry;
      pts.push([px, py]);
    }
    return pts;
  }

  // --- Timeline State Computation (Continuous & Seamless over 20s) ---
  const loopPhase = (loopT / duration) * TAU;
  const hoverY = Math.sin(loopPhase * 2) * 0.008 * s;

  let drawAmt = 1;
  let fillAmt = 1;
  let outlineAlpha = 0;
  let lanternScale = 1;
  let ribExpand = 1;
  let emblemReveal = 1;
  let digitsReveal = 1;
  let pulseVal = 0;
  let tasselAngle = 0;
  let plaqueSheen = -1;
  let petalBoost = 0;

  if (currentScene === 0) {
    // Scene 1: Precision Path Draw & Bottom-to-Top Flat Color Fill
    drawAmt = easeInOutCubic(subProgress(sceneProgress, 0.0, 0.54));
    fillAmt = easeInOutCubic(subProgress(sceneProgress, 0.42, 0.92));
    outlineAlpha = 1 - easeInOutCubic(subProgress(sceneProgress, 0.84, 1.0));
    lanternScale = 0.92;
    ribExpand = 0;
    emblemReveal = 0;
    digitsReveal = 0;
    pulseVal = 0;
    tasselAngle = 0;
  } else if (currentScene === 1) {
    // Scene 2: Controlled Elastic Bloom, Staggered Ribs & Emblem/2027 Reveal
    drawAmt = 1;
    fillAmt = 1;
    outlineAlpha = 0;
    const bloomP = subProgress(sceneProgress, 0.0, 0.46);
    lanternScale = lerp(0.92, 1.0, easeOutBackSubtle(bloomP));
    ribExpand = easeOutQuart(subProgress(sceneProgress, 0.14, 0.66));
    emblemReveal = easeOutQuart(subProgress(sceneProgress, 0.42, 0.78));
    digitsReveal = easeInOutCubic(subProgress(sceneProgress, 0.56, 0.96));
    pulseVal = 0;
    tasselAngle = 0;
  } else if (currentScene === 2) {
    // Scene 3: Internal Flat Light Pulse, Natural Pendulum Tassel & Petal Ascent
    drawAmt = 1;
    fillAmt = 1;
    outlineAlpha = 0;
    lanternScale = 1.0;
    ribExpand = 1;
    emblemReveal = 1;
    digitsReveal = 1;
    pulseVal = 0.5 - 0.5 * Math.cos(sceneProgress * Math.PI * 4);
    const pendulumEnv = Math.sin(sceneProgress * Math.PI);
    tasselAngle = pendulumEnv * Math.sin(sceneProgress * Math.PI * 4) * 0.072;
    petalBoost = Math.sin(sceneProgress * Math.PI);
    if (sceneProgress >= 0.18 && sceneProgress <= 0.56) {
      plaqueSheen = easeInOutCubic(subProgress(sceneProgress, 0.18, 0.56));
    }
  } else {
    // Scene 4: Graceful Retraction back to exact t=0 Crown Seed
    pulseVal = 0;
    tasselAngle = 0;
    digitsReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.0, 0.24));
    emblemReveal = 1 - easeInOutCubic(subProgress(sceneProgress, 0.06, 0.34));
    ribExpand = 1 - easeInOutCubic(subProgress(sceneProgress, 0.10, 0.38));
    lanternScale = lerp(1.0, 0.92, easeInOutCubic(subProgress(sceneProgress, 0.10, 0.42)));
    fillAmt = 1 - easeInOutCubic(subProgress(sceneProgress, 0.32, 0.72));
    outlineAlpha = easeInOutCubic(subProgress(sceneProgress, 0.28, 0.42));
    drawAmt = 1 - easeInOutCubic(subProgress(sceneProgress, 0.60, 0.98));
  }

  // --- LAYER 1: Clean Dark Matte Luxury Background (ZERO Glow) ---
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#1A0B0F");
  bgGrad.addColorStop(0.52, "#13070B");
  bgGrad.addColorStop(1, "#0B0406");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // --- LAYER 2: Strictly Separated Outer Side Architectural Clouds (No Overlap with Hero) ---
  const halfW = width * 0.5;
  const heroSafeHalf = 0.29 * s;
  if (halfW > heroSafeHalf + 0.14 * s) {
    const cloudConfigs = [
      { side: -1, xFrac: 0.72, yOff: -0.25, unit: 0.078, drift: 0.018, phase: 0.0, color: "#230E14" },
      { side: -1, xFrac: 0.80, yOff: 0.24, unit: 0.064, drift: -0.015, phase: 1.4, color: "#2B1219" },
      { side: 1, xFrac: 0.72, yOff: -0.22, unit: 0.074, drift: -0.018, phase: 0.7, color: "#230E14" },
      { side: 1, xFrac: 0.80, yOff: 0.26, unit: 0.068, drift: 0.015, phase: 2.1, color: "#2B1219" }
    ];
    for (let i = 0; i < cloudConfigs.length; i++) {
      const cfg = cloudConfigs[i];
      const baseDist = Math.max(heroSafeHalf + cfg.unit * 1.25 * s, halfW * cfg.xFrac);
      const driftX = Math.sin(loopPhase + cfg.phase) * cfg.drift * s;
      const cloudX = cx + cfg.side * baseDist + driftX;
      const cloudY = cy + cfg.yOff * s + Math.cos(loopPhase + cfg.phase) * 0.008 * s;
      drawSideFlatCloud(cloudX, cloudY, cfg.unit * s, cfg.color);
    }
  }

  // --- LAYER 3: Strictly Non-Overlapping Outer-Lane Floating Flat Vector Petals ---
  // Each petal owns an exclusive vertical column outside the hero zone (zero inter-petal collision).
  const laneInner = Math.max(0.35 * s, heroSafeHalf + 0.06 * s);
  const laneOuter = Math.max(laneInner + 0.08 * s, halfW - 0.075 * s);
  if (halfW > laneInner + 0.04 * s) {
    const laneCountPerSide = 4;
    const petalColors = ["#F5C76B", "#F0543A", "#FFE3A3", "#2DA890"];
    const travelTop = cy - 0.39 * s;
    const travelBot = cy + 0.39 * s;
    const travelH = travelBot - travelTop;

    for (let side = -1; side <= 1; side += 2) {
      for (let i = 0; i < laneCountPerSide; i++) {
        const laneU = laneCountPerSide > 1 ? i / (laneCountPerSide - 1) : 0.5;
        const baseX = cx + side * lerp(laneInner, laneOuter, laneU);
        const speedCycles = (i % 2 === 0) ? 1 : 2;
        const phaseOffset = (i * 0.27 + (side > 0 ? 0.14 : 0)) % 1;
        const rawProgress = (phaseOffset + (loopT / duration) * speedCycles) % 1;
        const py = travelBot - rawProgress * travelH;
        const swayX = Math.sin(loopPhase * speedCycles + i * 1.9 + side) * 0.009 * s;
        const px = baseX + swayX;

        const edgeFade = Math.sin(rawProgress * Math.PI);
        const alpha = clamp01(edgeFade * 1.35) * lerp(0.72, 0.96, petalBoost);
        const baseR = lerp(0.0085, 0.0135, (i % 3) * 0.5) * s * (1 + 0.14 * petalBoost);
        const rot = loopPhase * (side * (i % 2 === 0 ? 1 : -1)) + i * 0.85;
        const shapeType = (i + (side > 0 ? 1 : 0)) % 3;
        const col = petalColors[(i + (side > 0 ? 2 : 0)) % petalColors.length];

        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(rot);
        ctx.globalAlpha = alpha;
        ctx.fillStyle = col;

        if (shapeType === 0) {
          // Crisp flat geometric diamond
          ctx.beginPath();
          ctx.moveTo(0, -baseR * 1.25);
          ctx.lineTo(baseR * 0.82, 0);
          ctx.lineTo(0, baseR * 1.25);
          ctx.lineTo(-baseR * 0.82, 0);
          ctx.closePath();
          ctx.fill();
        } else if (shapeType === 1) {
          // Crisp flat 4-point star
          const rOut = baseR * 1.25;
          const rIn = baseR * 0.36;
          ctx.beginPath();
          for (let k = 0; k < 8; k++) {
            const ang = (k * Math.PI) / 4;
            const rr = k % 2 === 0 ? rOut : rIn;
            if (k === 0) ctx.moveTo(Math.cos(ang) * rr, Math.sin(ang) * rr);
            else ctx.lineTo(Math.cos(ang) * rr, Math.sin(ang) * rr);
          }
          ctx.closePath();
          ctx.fill();
        } else {
          // Crisp flat rounded paper petal
          ctx.beginPath();
          ctx.moveTo(0, -baseR * 1.3);
          ctx.bezierCurveTo(baseR * 0.95, -baseR * 0.5, baseR * 0.95, baseR * 0.5, 0, baseR * 1.3);
          ctx.bezierCurveTo(-baseR * 0.95, baseR * 0.5, -baseR * 0.95, -baseR * 0.5, 0, -baseR * 1.3);
          ctx.closePath();
          ctx.fill();
        }
        ctx.restore();
      }
    }
  }

  // --- LAYER 4: Hero Icon — Golden Lantern (Centered, Balanced, Precision 2D Flat Vector) ---
  ctx.save();
  ctx.translate(cx, cy + hoverY);

  const breathScaleX = lanternScale * (1 + 0.014 * pulseVal);
  const breathScaleY = lanternScale * (1 - 0.007 * pulseVal);
  ctx.scale(breathScaleX, breathScaleY);

  // Proportional lantern structural anchor coordinates (in local space centered at 0,0)
  const hangerRingY = -0.352 * s;
  const hangerRingR = 0.025 * s;
  const neckTopY = -0.326 * s;
  const topCapTopY = -0.252 * s;
  const topCapBotY = -0.204 * s;
  const globeY = -0.030 * s;
  const globeRx = 0.215 * s;
  const globeRy = 0.174 * s;
  const botCapTopY = globeY + globeRy;       // +0.144 * s
  const botCapBotY = botCapTopY + 0.044 * s; // +0.188 * s
  const beadCenterY = botCapBotY + 0.030 * s; // +0.218 * s
  const beadR = 0.021 * s;
  const tasselPivotY = beadCenterY + beadR + 0.010 * s; // +0.249 * s
  const tasselLen = 0.142 * s;

  const capOuterHalfW = 0.098 * s;
  const capInnerHalfW = 0.074 * s;
  const goldStrokeW = Math.max(1.5, 0.0042 * s);

  function traceLanternGlobeSilhouette() {
    ctx.beginPath();
    ctx.ellipse(0, globeY, globeRx, globeRy, 0, 0, TAU);
    ctx.closePath();
  }

  function traceFullLanternFillMask() {
    // Combined silhouette of top cap, globe, bottom cap, jade bead, and tassel bell
    // Used cleanly per-component via horizontal fill clip curtain
    ctx.beginPath();
    ctx.rect(-0.30 * s, lerp(tasselPivotY + tasselLen + 0.02 * s, hangerRingY - hangerRingR - 0.02 * s, fillAmt), 0.60 * s, 0.85 * s);
  }

  // 4A. Always-Present Crown Seed (Top Hanging Ring & Fret Knot so t=0 is never empty)
  ctx.save();
  ctx.strokeStyle = "#F5C76B";
  ctx.lineWidth = Math.max(2, 0.0085 * s);
  ctx.beginPath();
  ctx.arc(0, hangerRingY, hangerRingR, 0, TAU);
  ctx.stroke();

  ctx.fillStyle = "#D99E34";
  ctx.beginPath();
  ctx.arc(0, hangerRingY + hangerRingR, 0.0105 * s, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#FFE3A3";
  ctx.beginPath();
  ctx.arc(-0.0025 * s, hangerRingY + hangerRingR - 0.0025 * s, 0.0038 * s, 0, TAU);
  ctx.fill();
  ctx.restore();

  // 4B. Filled Lantern Assembly (Clipped cleanly by bottom-to-top fill curtain during Scene 1 & 4)
  if (fillAmt > 0.001) {
    ctx.save();
    traceFullLanternFillMask();
    ctx.clip();

    // Neck Cord
    ctx.fillStyle = "#F5C76B";
    drawRoundedRectPath(-0.0055 * s, neckTopY, 0.011 * s, topCapTopY - neckTopY + 0.004 * s, 0.004 * s);
    ctx.fill();

    // Top Stepped Gold Cap
    ctx.fillStyle = "#D99E34";
    ctx.beginPath();
    ctx.moveTo(-capInnerHalfW, topCapTopY);
    ctx.lineTo(capInnerHalfW, topCapTopY);
    ctx.lineTo(capOuterHalfW, topCapBotY);
    ctx.lineTo(-capOuterHalfW, topCapBotY);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "#F5C76B";
    drawRoundedRectPath(-capInnerHalfW * 0.88, topCapTopY - 0.010 * s, capInnerHalfW * 1.76, 0.014 * s, 0.005 * s);
    ctx.fill();

    ctx.fillStyle = "#8C5314";
    ctx.fillRect(-capOuterHalfW, topCapBotY - 0.007 * s, capOuterHalfW * 2, 0.007 * s);

    // Top Cap Rivet Studs (appear with ribExpand)
    if (ribExpand > 0.01) {
      ctx.fillStyle = "#FFE3A3";
      const studR = 0.0055 * s * ribExpand;
      for (let st = -1; st <= 1; st++) {
        ctx.beginPath();
        ctx.arc(st * 0.044 * s, (topCapTopY + topCapBotY) * 0.5 - 0.002 * s, studR, 0, TAU);
        ctx.fill();
      }
    }

    // Bottom Stepped Gold Cap
    ctx.fillStyle = "#D99E34";
    ctx.beginPath();
    ctx.moveTo(-capOuterHalfW, botCapTopY);
    ctx.lineTo(capOuterHalfW, botCapTopY);
    ctx.lineTo(capInnerHalfW, botCapBotY);
    ctx.lineTo(-capInnerHalfW, botCapBotY);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "#8C5314";
    ctx.fillRect(-capOuterHalfW, botCapTopY, capOuterHalfW * 2, 0.007 * s);

    ctx.fillStyle = "#F5C76B";
    drawRoundedRectPath(-capInnerHalfW * 0.86, botCapBotY - 0.004 * s, capInnerHalfW * 1.72, 0.012 * s, 0.005 * s);
    ctx.fill();

    // Jade Accent Bead & Gold Spacer Collars
    ctx.fillStyle = "#F5C76B";
    drawRoundedRectPath(-0.014 * s, botCapBotY + 0.006 * s, 0.028 * s, 0.008 * s, 0.003 * s);
    ctx.fill();

    ctx.fillStyle = "#2DA890";
    ctx.beginPath();
    ctx.arc(0, beadCenterY, beadR, 0, TAU);
    ctx.fill();

    // Crisp flat 2D facet highlight on jade bead
    ctx.fillStyle = "#5CD4BC";
    ctx.beginPath();
    ctx.arc(-beadR * 0.28, beadCenterY - beadR * 0.25, beadR * 0.34, 0, TAU);
    ctx.fill();

    ctx.fillStyle = "#F5C76B";
    drawRoundedRectPath(-0.014 * s, beadCenterY + beadR - 0.002 * s, 0.028 * s, 0.008 * s, 0.003 * s);
    ctx.fill();

    // Structured Pendulum Tassel (7 Clearly Separated Flat Silk Strands)
    ctx.save();
    ctx.translate(0, tasselPivotY);
    ctx.rotate(tasselAngle);

    // Tassel Bell Cap
    ctx.fillStyle = "#F5C76B";
    ctx.beginPath();
    ctx.moveTo(-0.018 * s, 0);
    ctx.lineTo(0.018 * s, 0);
    ctx.lineTo(0.029 * s, 0.024 * s);
    ctx.lineTo(-0.029 * s, 0.024 * s);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "#D99E34";
    ctx.fillRect(-0.029 * s, 0.018 * s, 0.058 * s, 0.006 * s);

    // 7 Spaced Flat Silk Strands (No Crossings, Clean Rounded Ends)
    const strandCount = 7;
    const strandSpacing = 0.0082 * s;
    const strandWidth = 0.0044 * s;
    for (let i = 0; i < strandCount; i++) {
      const idxFromCenter = i - (strandCount - 1) * 0.5;
      const sx = idxFromCenter * strandSpacing;
      const lenFactor = 1 - Math.abs(idxFromCenter) * 0.055;
      const sLen = (tasselLen - 0.024 * s) * lenFactor;
      const localLag = tasselAngle * 0.28 * (1 + Math.abs(idxFromCenter) * 0.12);

      ctx.save();
      ctx.translate(sx, 0.024 * s);
      ctx.rotate(localLag);
      ctx.fillStyle = i % 2 === 0 ? "#F5C76B" : "#E64632";
      drawRoundedRectPath(-strandWidth * 0.5, 0, strandWidth, sLen, strandWidth * 0.5);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();

    // Main Lantern Globe Body (5 Crisp Layered Flat Vector Panels)
    const outerPanelCol = mixHex("#C42A1E", "#D63728", pulseVal);
    const midPanelCol = mixHex("#DE3B2B", "#F2563C", pulseVal);
    const centerPanelCol = mixHex("#EF5138", "#FF7654", pulseVal);
    const ribGoldCol = mixHex("#F5C76B", "#FFE4A6", pulseVal);

    ctx.save();
    traceLanternGlobeSilhouette();
    ctx.clip();

    // Base Outer Panel Fill
    ctx.fillStyle = outerPanelCol;
    ctx.fillRect(-globeRx - 2, globeY - globeRy - 2, globeRx * 2 + 4, globeRy * 2 + 4);

    // Mid Symmetrical Flat Panel
    const midRx = lerp(globeRx * 0.58, globeRx * 0.72, ribExpand);
    ctx.fillStyle = midPanelCol;
    ctx.beginPath();
    ctx.ellipse(0, globeY, midRx, globeRy * 1.02, 0, 0, TAU);
    ctx.fill();

    // Center Symmetrical Flat Panel
    const innerRx = lerp(globeRx * 0.28, globeRx * 0.41, ribExpand);
    ctx.fillStyle = centerPanelCol;
    ctx.beginPath();
    ctx.ellipse(0, globeY, innerRx, globeRy * 1.02, 0, 0, TAU);
    ctx.fill();

    // Subtle Crisp Flat Inner Crescent Highlight (Pure 2D Flat Vector, Zero Glow)
    if (pulseVal > 0.01) {
      ctx.fillStyle = "#FF997A";
      ctx.globalAlpha = 0.26 * pulseVal;
      ctx.beginPath();
      ctx.ellipse(0, globeY - 0.012 * s, innerRx * 0.68, globeRy * 0.74, 0, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    // Staggered Precision Gold Ribs
    const ribInnerP = easeOutQuart(subProgress(ribExpand, 0.0, 0.72));
    const ribOuterP = easeOutQuart(subProgress(ribExpand, 0.28, 1.0));
    ctx.strokeStyle = ribGoldCol;
    ctx.lineCap = "round";

    if (ribInnerP > 0.01) {
      ctx.lineWidth = goldStrokeW * 1.1;
      ctx.globalAlpha = ribInnerP;
      ctx.beginPath();
      ctx.ellipse(0, globeY, innerRx, globeRy * 1.01, 0, 0, TAU);
      ctx.stroke();
    }
    if (ribOuterP > 0.01) {
      ctx.lineWidth = goldStrokeW * 1.05;
      ctx.globalAlpha = ribOuterP;
      ctx.beginPath();
      ctx.ellipse(0, globeY, midRx, globeRy * 1.01, 0, 0, TAU);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Subtle Top & Bottom Recessed Flat Rim Bands inside Globe
    ctx.fillStyle = "#9C1E16";
    ctx.fillRect(-globeRx, globeY - globeRy, globeRx * 2, 0.011 * s);
    ctx.fillRect(-globeRx, globeY + globeRy - 0.011 * s, globeRx * 2, 0.011 * s);

    ctx.restore();

    // Crisp Outer Gold Perimeter Contour on Filled Globe
    ctx.strokeStyle = ribGoldCol;
    ctx.lineWidth = goldStrokeW * 1.15;
    traceLanternGlobeSilhouette();
    ctx.stroke();

    // Central Octagonal Emblem Plaque + Ruyi Clouds + Custom Vector "2027"
    if (emblemReveal > 0.01) {
      ctx.save();
      ctx.translate(0, globeY);
      const plScale = lerp(0.55, 1.0, emblemReveal);
      ctx.scale(plScale, plScale);
      ctx.globalAlpha = emblemReveal;

      const plRx = 0.095 * s;
      const plRy = 0.075 * s;
      const plCut = 0.021 * s;

      // Outer Gold Octagon
      drawOctagonPath(0, 0, plRx, plRy, plCut);
      ctx.fillStyle = "#F5C76B";
      ctx.fill();

      // Inner Crimson Field
      drawOctagonPath(0, 0, plRx - 0.007 * s, plRy - 0.007 * s, plCut * 0.85);
      ctx.fillStyle = "#B52019";
      ctx.fill();

      // Inner Precision Gold Hairline Accent
      drawOctagonPath(0, 0, plRx - 0.013 * s, plRy - 0.013 * s, plCut * 0.72);
      ctx.strokeStyle = "#FFE3A3";
      ctx.lineWidth = Math.max(1, 0.0022 * s);
      ctx.stroke();

      // Symmetrical Top & Bottom Ruyi Cloud Flourishes inside Plaque
      const ruyiScale = 0.019 * s * easeOutQuart(subProgress(emblemReveal, 0.25, 1.0));
      if (ruyiScale > 0.5) {
        drawRuyiCloud(0, -0.043 * s, ruyiScale, false, "#F5C76B");
        drawRuyiCloud(0, 0.043 * s, ruyiScale, true, "#F5C76B");
      }

      // Custom Crisp Vector "2027" Numerals with Staggered Clip Reveal
      if (digitsReveal > 0.01) {
        const digits = ["2", "0", "2", "7"];
        const dW = 0.021 * s;
        const dH = 0.030 * s;
        const dGap = 0.009 * s;
        const totalDW = digits.length * dW + (digits.length - 1) * dGap;
        const startX = -totalDW * 0.5;
        const dLineW = Math.max(1.5, 0.0042 * s);

        ctx.save();
        ctx.beginPath();
        ctx.rect(-plRx + 0.014 * s, -0.022 * s, (plRx - 0.014 * s) * 2, 0.044 * s);
        ctx.clip();

        for (let di = 0; di < digits.length; di++) {
          const dp = easeOutQuart(subProgress(digitsReveal, di * 0.14, 0.58 + di * 0.14));
          if (dp <= 0.001) continue;
          const dx = startX + di * (dW + dGap);
          const dy = -dH * 0.5 + (1 - dp) * 0.024 * s;
          ctx.globalAlpha = emblemReveal * dp;
          drawVectorDigit(digits[di], dx, dy, dW, dH, "#FFF4D9", dLineW);
        }
        ctx.restore();
      }

      // Clean Diagonal Sheen Sweep Clipped Strictly Inside Octagon Plaque (Scene 3)
      if (plaqueSheen >= 0 && plaqueSheen <= 1) {
        ctx.save();
        drawOctagonPath(0, 0, plRx - 0.007 * s, plRy - 0.007 * s, plCut * 0.85);
        ctx.clip();
        const sx = lerp(-plRx * 1.9, plRx * 1.9, plaqueSheen);
        ctx.fillStyle = "rgba(255, 244, 217, 0.34)";
        ctx.beginPath();
        ctx.moveTo(sx - 0.022 * s, -plRy * 1.4);
        ctx.lineTo(sx + 0.012 * s, -plRy * 1.4);
        ctx.lineTo(sx - 0.016 * s, plRy * 1.4);
        ctx.lineTo(sx - 0.050 * s, plRy * 1.4);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }

      ctx.restore();
    }

    ctx.restore();
  }

  // 4C. Precision Construction Path Outline (Scene 1 Entry & Scene 4 Retraction)
  if (outlineAlpha > 0.005 && drawAmt > 0.001) {
    ctx.save();
    ctx.globalAlpha = outlineAlpha;
    ctx.strokeStyle = "#F5C76B";
    ctx.lineWidth = goldStrokeW;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    const pNeck = subProgress(drawAmt, 0.0, 0.14);
    const pTopCap = subProgress(drawAmt, 0.10, 0.28);
    const pGlobe = subProgress(drawAmt, 0.22, 0.68);
    const pBotCap = subProgress(drawAmt, 0.62, 0.78);
    const pTassel = subProgress(drawAmt, 0.74, 1.0);

    // Neck line
    if (pNeck > 0) {
      tracePartialPolyline([[0, neckTopY], [0, topCapTopY]], pNeck);
    }
    // Symmetrical top cap contours
    if (pTopCap > 0) {
      tracePartialPolyline([[0, topCapTopY], [-capInnerHalfW, topCapTopY], [-capOuterHalfW, topCapBotY]], pTopCap);
      tracePartialPolyline([[0, topCapTopY], [capInnerHalfW, topCapTopY], [capOuterHalfW, topCapBotY]], pTopCap);
    }
    // Symmetrical globe outer contours & inner construction arcs
    if (pGlobe > 0) {
      const leftGlobe = sampleGlobeHalfPoints(0, globeY, globeRx, globeRy, -1, 32);
      const rightGlobe = sampleGlobeHalfPoints(0, globeY, globeRx, globeRy, 1, 32);
      tracePartialPolyline(leftGlobe, pGlobe);
      tracePartialPolyline(rightGlobe, pGlobe);

      const leftMid = sampleGlobeHalfPoints(0, globeY, globeRx * 0.58, globeRy, -1, 24);
      const rightMid = sampleGlobeHalfPoints(0, globeY, globeRx * 0.58, globeRy, 1, 24);
      ctx.save();
      ctx.globalAlpha = outlineAlpha * 0.55;
      tracePartialPolyline(leftMid, subProgress(pGlobe, 0.18, 1.0));
      tracePartialPolyline(rightMid, subProgress(pGlobe, 0.18, 1.0));
      ctx.restore();
    }
    // Symmetrical bottom cap contours
    if (pBotCap > 0) {
      tracePartialPolyline([[-capOuterHalfW, botCapTopY], [-capInnerHalfW, botCapBotY], [0, botCapBotY]], pBotCap);
      tracePartialPolyline([[capOuterHalfW, botCapTopY], [capInnerHalfW, botCapBotY], [0, botCapBotY]], pBotCap);
    }
    // Jade bead + tassel bell cap + tassel silk guidelines
    if (pTassel > 0) {
      const beadLeft = sampleGlobeHalfPoints(0, beadCenterY, beadR, beadR, -1, 14);
      const beadRight = sampleGlobeHalfPoints(0, beadCenterY, beadR, beadR, 1, 14);
      tracePartialPolyline(beadLeft, subProgress(pTassel, 0.0, 0.35));
      tracePartialPolyline(beadRight, subProgress(pTassel, 0.0, 0.35));

      const bellP = subProgress(pTassel, 0.24, 0.55);
      if (bellP > 0) {
        tracePartialPolyline([[0, tasselPivotY], [-0.018 * s, tasselPivotY], [-0.029 * s, tasselPivotY + 0.024 * s], [0, tasselPivotY + 0.024 * s]], bellP);
        tracePartialPolyline([[0, tasselPivotY], [0.018 * s, tasselPivotY], [0.029 * s, tasselPivotY + 0.024 * s], [0, tasselPivotY + 0.024 * s]], bellP);
      }

      const strandP = subProgress(pTassel, 0.45, 1.0);
      if (strandP > 0) {
        const guideOffsets = [-0.024 * s, -0.012 * s, 0, 0.012 * s, 0.024 * s];
        for (let gi = 0; gi < guideOffsets.length; gi++) {
          const gx = guideOffsets[gi];
          const gLen = (tasselLen - 0.024 * s) * (1 - Math.abs(gi - 2) * 0.07);
          tracePartialPolyline([[gx, tasselPivotY + 0.024 * s], [gx, tasselPivotY + 0.024 * s + gLen]], strandP);
        }
      }
    }

    ctx.restore();
  }

  ctx.restore();
}
